window.DK_TERIM_DIZIN=window.DK_TERIM_DIZIN||{};DK_TERIM_DIZIN["mto342e"]={"v":"a2e96bd432","terim":[{"id":"mixed-phase-cloud","tr":"Karma fazlı bulut","en":"Mixed-phase cloud","kisa":"","tur":"kavram","es":["karışık fazlı bulut","karma faz","mixed phase","karışık faz bulutu"],"tanim":["Sıfır ile yaklaşık −40 °C sıcaklık aralığında, aşırı soğumuş sıvı su damlacıkları ile buz kristallerinin bir arada bulunduğu bulut.","Suya göre doyma buhar basıncı buza göre olandan yüksek olduğu için sistem termodinamik dengeye ulaşamaz.","Bergeron sürecinin gerçekleştiği ortamdır; su damlaları buharlaşırken buz kristalleri buhar birikimiyle hızla büyür."],"tanim_en":"A cloud containing both supercooled liquid water droplets and ice crystals at temperatures between 0 °C and approximately −40 °C.","bag":{"kavram":["bergeron","donma"],"soru":["S12","S37","S39"],"hesap":[]}},{"id":"ice-supersaturation","tr":"Buza göre aşırı doymuşluk","en":"supersaturation with respect to ice","kisa":"S_buz","tur":"olcu","es":["buza göre aşırı doygunluk","ice supersaturation","S_ice","Sbuz","buz aşırı doymuşluğu","S_i"],"tanim":["Su buharı kısmi basıncının, aynı sıcaklıktaki buza göre doyma buhar basıncına oranının bir eksiği olarak tanımlanan boyutsuz büyüklük.","Suya göre doymuş bir karma faz bulutta −14 °C sıcaklıkta tipik değeri yaklaşık 0,15 (%15) mertebesine ulaşır.","Bergeron sürecinde buz kristallerinin su buharı difüzyonu ile hızla büyümesini sağlayan temel termodinamik itici güçtür."],"tanim_en":"The fraction by which ambient water vapor pressure exceeds the saturation vapor pressure over ice, driving the diffusional growth of ice crystals in mixed-phase clouds.","bag":{"kavram":["bergeron","buz-kutle"],"soru":["S37","S39","S40"],"hesap":["bergeron","buz-kutle"]}},{"id":"latent-heat-of-fusion","tr":"Erime (donma) gizli ısısı","en":"latent heat of fusion","kisa":"L_f","tur":"olcu","es":["donma gizli ısısı","L_f","latent heat of melting","erime gizli ısısı","latent heat of freezing"],"tanim":["Sabit sıcaklık ve basınçta birim kütledeki buzun erimesi ya da suyun donması sırasında soğurulan veya salınan ısı miktarıdır.","SI birimi J kg⁻¹ olup 0 °C'de su-buz faz değişimi için değeri yaklaşık 3,3×10⁵ J kg⁻¹ (L_d − Lᵥ) kadardır.","Bulut fiziğinde aşırı soğumuş damlaların donması, dolu tanelerinin sulu büyümesi ve erime katmanındaki (parlak bant) ısı alışverişinde rol oynar."],"tanim_en":"The amount of thermal energy absorbed or given off per unit mass during a change between liquid and ice at constant temperature.","bag":{"kavram":["bergeron","donma"],"soru":[],"hesap":["es"]}},{"id":"relative-humidity-over-ice","tr":"Buza göre bağıl nem","en":"relative humidity with respect to ice","kisa":"RH_buz","tur":"olcu","es":["RH_ice","buza göre nisbi nem","relative humidity over ice","RH_buz","buz bağıl nemi"],"tanim":["Havadaki su buharı kısmi basıncının, aynı sıcaklıkta düz bir buz yüzeyi üzerindeki doyma buhar basıncına oranıdır.","Yüzde (%) olarak ifade edilir; 0 °C'nin altında su üzerinde doygun olan bir hava parselinde e_s(su) > e_s(buz) olduğundan buza göre bağıl nem %100'ü aşar.","Karma fazlı bulutlarda Bergeron sürecini ve buz kristallerinin buhar difüzyonu yoluyla büyüme hızını belirleyen temel termodinamik değişkendir."],"tanim_en":"The ratio of the ambient vapor pressure to the saturation vapor pressure over a flat ice plane at the same temperature, expressed as a percentage.","bag":{"kavram":["bergeron"],"soru":["S37"],"hesap":["bergeron"]}},{"id":"unit-okta","tr":"Okta","en":"okta","kisa":"","tur":"birim","es":["sekizde bir","eighths","eighths of sky"],"tanim":["Gökyüzünün bulutla kaplı alanını sekizde bir oranında belirten meteorolojik kapalılık birimi.","SYNOP iletisinde toplam bulut (N) ve alçak bulut miktarı (Nh) 0–8 okta ile kodlanır (9 = gök sis vb. nedeniyle görülemiyor); METAR'daki FEW, SCT, BKN ve OVC sınıfları okta aralıklarıyla tanımlanır.","Onda bir (tenths) birimine n₁₀ = n₈ × 10/8 bağıntısıyla dönüştürülerek bulut örtüsü sınıflamasında kullanılır."],"tanim_en":"A unit of measurement equal to one eighth of the celestial dome, used to describe the amount of cloud cover.","bag":{"kavram":["bulut-ortu"],"soru":["S13"],"hesap":["bulut-ortu"]}},{"id":"broken-clouds","tr":"Çok bulutlu","en":"Broken clouds","kisa":"BKN","tur":"kod","es":["BKN","broken","çok bulutlu gökyüzü","broken cloud cover"],"tanim":["Gökyüzünün onda 6 ile onda 9 arasındaki (veya 5–7 okta) bölümünün bulutlarla kaplı olduğu gök durumu.","Havacılık raporlarında BKN koduyla gösterilir ve taban yüksekliğiyle birlikte bulut tavanı hesabına temel oluşturur.","Parçalı bulutluluktan daha yoğun, kapalı gökyüzünden ise yer yer açıklıklar içermesiyle ayrılır."],"tanim_en":"A sky condition in which clouds cover 6 to 9 tenths of the celestial dome.","bag":{"kavram":["bulut-ortu"],"soru":["S13"],"hesap":[]}},{"id":"clear-sky","tr":"Açık gökyüzü","en":"Clear sky","kisa":"SKC","tur":"kod","es":["SKC","CLR","clear","açık hava"],"tanim":["Toplam bulut örtüsünün bir oktadan veya onda bir oranından az olduğu gök durumu.","Havacılık ve sinoptik kodlamalarda SKC veya CLR kısaltmasıyla belirtilir.","Açık ve sakin gecelerde yeryüzünün güçlü uzun dalga ışınımla soğuması yüzey terselmesine ve ışınım sisi oluşumuna zemin hazırlar."],"tanim_en":"A sky condition with a total cloud cover under one okta.","bag":{"kavram":["bulut-ortu","sis"],"soru":["S13","S14","S17","S18","S19","S23"],"hesap":[]}},{"id":"overcast-sky","tr":"Kapalı gökyüzü","en":"Overcast sky","kisa":"OVC","tur":"kod","es":["OVC","overcast","kapalı gök"],"tanim":["Gökyüzünün onda 9'undan fazlasının veya 8 oktanın tamamının bulut tabakasıyla örtülü olduğu durum.","Havacılık gözlemlerinde OVC koduyla belirtilir ve bulut tabanı havacılık tavanı sayılır.","Yeryüzü ile atmosfer arasındaki uzun dalga ışınım kaybını engelleyerek gece soğumasını belirgin biçimde sınırlar."],"tanim_en":"A sky condition in which clouds cover more than nine tenths of the celestial dome.","bag":{"kavram":["bulut-ortu"],"soru":["S13","S27"],"hesap":[]}},{"id":"scattered-clouds","tr":"Parçalı bulutlu","en":"Scattered clouds","kisa":"SCT","tur":"kod","es":["SCT","scattered","parçalı bulutluluk"],"tanim":["Gökyüzünün onda 1'i ile onda 5'i arasındaki (kabaca 1–4 okta; METAR'da 1–2 okta FEW, 3–4 okta SCT) alanının bulutlarla kaplı olduğu gök durumu.","Havacılık raporlarında SCT koduyla gösterilir.","Örtü oranı onda 5'i aşmadığı için kural olarak tek başına havacılık bulut tavanı oluşturmaz."],"tanim_en":"A sky condition in which clouds cover between one tenth and five tenths of the celestial dome.","bag":{"kavram":["bulut-ortu"],"soru":["S13","S23","S33"],"hesap":[]}},{"id":"cloud-ceiling","tr":"Bulut tavanı","en":"Cloud ceiling","kisa":"CIG","tur":"olcu","es":["tavan","ceiling","CIG","tavan yüksekliği"],"tanim":["Gökyüzünün yarıdan fazlasını örten (çok bulutlu veya kapalı) en alçak bulut katmanının yer yüzeyinden olan yüksekliği.","Havacılık meteorolojisinde ve meydan yaklaşma operasyonlarında iniş ve kalkış emniyetini belirleyen kritik bir ölçüdür.","Yalnızca örtüsü onda 6 ve üzerinde olan bulut katmanları tavan yüksekliği hesabında dikkate alınır."],"tanim_en":"The height above the ground of the base of the lowest cloud layer covering more than half of the sky.","bag":{"kavram":["bulut-ortu"],"soru":["S7","S13","S14"],"hesap":["bulut-ortu"]}},{"id":"altocumulus","tr":"Altocumulus","en":"Altocumulus","kisa":"Ac","tur":"kavram","es":["altokümülüs","orta küme bulutu","Ac","altocumulus cloud","orta seviye küme bulut"],"tanim":["Orta katmanda yer alan, beyaz veya gri renkli, yuvarlak kütleler veya yuvarlar içeren tabaka ya da yama biçimli bulut cinsi.","Düzenli dizilmiş küçük bulut öğelerinin görünür genişliği bir kol boyu mesafeden bir ile beş derece arasındadır.","Çoğunlukla (çoğu kez aşırı soğumuş) su damlacıklarından oluşur; kuleli türü (Ac castellanus) orta seviye kararsızlığa işaret eder."],"tanim_en":"A middle-level cloud genus appearing as a white or grey layer of rounded elements with an apparent width between one and five degrees.","bag":{"kavram":["bulut-tur"],"soru":["S12","S17"],"hesap":[]}},{"id":"anvil-cloud","tr":"Örs","en":"anvil","kisa":"","tur":"kavram","es":["örs bulutu","anvil cloud","Cb örsü","incus","cumulonimbus anvil","örs tepesi"],"tanim":["İyi gelişmiş bir kümülonimbüs bulutunun üst kesiminde yer alan, örs biçimli ve lifli buz kristallerinden oluşan tepe yapısı.","Şiddetli dikey konvektif hava akımının kararlı stratosfer tabanı ve tropopoz terselmesiyle karşılaşması sonucu yatay yönde yayılmasıyla oluşur.","Tamamen buzlaşmış kristaller içerir ve meteoroloji uydularının kızılötesi görüntülerinde çok soğuk parlak tepe olarak izlenir."],"tanim_en":"The upper glaciated part of a cumulonimbus cloud forming an anvil shape that expands horizontally at the tropopause.","bag":{"kavram":["bulut-tur","terselme","yagis-surec"],"soru":["S9","S12","S17","S46"],"hesap":[]}},{"id":"castellanus-cloud","tr":"Kuleli altokümülüs","en":"Altocumulus castellanus","kisa":"Ac cas","tur":"kavram","es":["castellanus","kuleli bulut","kastelan bulutu","Ac cas"],"tanim":["Üst kısımlarında kale burçlarını andıran dikey kule biçimli kabarıntılar sergileyen ve ortak bir tabana bağlı bulut türü.","Orta troposferdeki sığ kararsız katmanın varlığına işaret eder ve konvektif küçük kulelerin yukarı doğru büyümesiyle şekillenir.","Sabah saatlerinde görülmesi orta seviyelerde kararsızlık bulunduğunu ve günün ilerleyen saatlerinde gök gürültülü fırtına gelişebileceğini haber verir."],"tanim_en":"A cloud species showing vertical turrets rising from a common base, indicating instability in the middle troposphere.","bag":{"kavram":["bulut-tur","kararlilik"],"soru":["S17"],"hesap":[]}},{"id":"cirrocumulus","tr":"Cirrocumulus","en":"Cirrocumulus","kisa":"Cc","tur":"kavram","es":["sirrokümülüs","Cc"],"tanim":["Yüksek katmanda (6 km üzerinde) gölgesiz, çok küçük tanecikler ya da dalgacıklar biçiminde, tek tek ya da birleşik dizilen ince beyaz bulut katmanı veya yaması.","Tamamen ya da neredeyse tamamen buz kristallerinden oluşur; tekil elemanlarının görünür açısal genişliği bir dereceden küçüktür.","Gökyüzünde uskumru deseni oluşturur; yüksek irtifadaki hafif sığ konveksiyon hareketlerini yansıtır."],"tanim_en":"A high-level cloud patch or sheet composed of very small, thin white ice elements without shading, having an apparent width of less than one degree.","bag":{"kavram":["bulut-tur"],"soru":["S12"],"hesap":[]}},{"id":"cirrostratus","tr":"Cirrostratus","en":"Cirrostratus","kisa":"Cs","tur":"kavram","es":["sirrostratüs","Cs","tül bulut"],"tanim":["Yüksek seviyede (6 km üzerinde) gökyüzünü lifli veya düzgün bir tül gibi örten, çoğunlukla 22° optik hale oluşturan ince beyaz buz bulutu tabakası.","Tamamen buz kristallerinden oluşur; Güneş ve Ay çevresinde hale üretmesine karşın yerdeki nesnelerin net gölge bırakmasını engellemez.","Yaklaşan sıcak cephe ve siklonik sistemlerin 12–24 saat önünden gelerek hava değişiminin ilk habercisi rolünü üstlenir."],"tanim_en":"A high-level, transparent ice cloud layer that covers the sky and generates a 22° optical halo around the Sun or Moon.","bag":{"kavram":["bulut-tur"],"soru":["S12"],"hesap":[]}},{"id":"cirrus","tr":"Cirrus","en":"Cirrus","kisa":"Ci","tur":"kavram","es":["sirrüs","Ci","lifli bulut"],"tanim":["Yüksek seviyede (6 km üzerinde) ayrık, beyaz, ince lifli veya ipeksi parlaklıkta saç tutamları biçiminde görülen buz bulutu.","Tamamen buz kristallerinden meydana gelir; üst troposferin çok soğuk katmanında oluşur.","Üst troposferdeki kuvvetli rüzgârlar kristallerin düşerken savrulmasına yol açarak virgül veya at kuyruğu biçimli lifli kuyruklar oluşturur."],"tanim_en":"A high-level tropospheric cloud composed of ice crystals, characterized by thin, white, fibrous or hair-like filaments.","bag":{"kavram":["bulut-tur"],"soru":["S12","S40"],"hesap":[]}},{"id":"cloud","tr":"Bulut","en":"cloud","kisa":"","tur":"kavram","es":["bulut kütlesi"],"tanim":["Serbest atmosferde asılı duran ve genellikle yer yüzeyine temas etmeyen, çok küçük sıvı su damlacıkları, buz kristalleri veya her ikisinin karışımından oluşan hidrometeor.","Havanın doyma noktasına gelerek yoğuşması ya da buharın doğrudan buz olarak birikmesiyle (depozisyon) oluşur; duman, kurum veya toz gibi katı parçacıkları da barındırabilir.","Nemli termodinamikte sıvı su yükü (r_L) ve buz yükü (r_I) terimleriyle sanal sıcaklığı ve parsel kaldırma kuvvetini doğrudan azaltıcı etki yapar."],"tanim_en":"A visible hydrometeor consisting of minute liquid water droplets or ice crystals suspended in the atmosphere above the ground.","bag":{"kavram":["bulut-tur"],"soru":["S2","S12","S15","S17","S32","S46"],"hesap":["lcl-lfc","bulut-ortu","lognormal","fohn"]}},{"id":"cloud-top","tr":"Bulut tepesi","en":"cloud top","kisa":"","tur":"kavram","es":["cloud top height","bulut üst sınırı","bulut tepe seviyesi","bulut tepe yüksekliği"],"tanim":["Belirli bir bulutun veya bulut katmanının, havanın algılanabilir miktarda bulut parçacığı içerdiği en yüksek seviyesidir.","Meteoroloji uydularının kızılötesi kanallarında parlaklık sıcaklığı ölçülerek tepe yüksekliği ve sıcaklığı belirlenir.","Yağış mekanizmasında belirleyicidir; bulut tepesi sıcaklığı 0 °C'nin altına indiğinde soğuk yağmur ve Bergeron süreci devreye girer."],"tanim_en":"The highest level in a specific cloud or cloud layer where the air contains a perceptible quantity of cloud particles.","bag":{"kavram":["bulut-tur"],"soru":["S12","S13","S46"],"hesap":[]}},{"id":"cumuliform-cloud","tr":"Kümülüs biçimli bulut","en":"cumuliform cloud","kisa":"","tur":"kavram","es":["kümüliform bulut","yığın bulut","kabarık bulut","convective cloud"],"tanim":["Belirgin dikey gelişime, kubbe veya karnabahar biçimli kabarık üst sınırlara ve genellikle düz bir tabana sahip konvektif bulut.","Kararsız hava katmanlarında serbest konveksiyon veya termik yükselmeler sonucu yerel yukarı hava akımlarıyla oluşur.","Kitapta ve meteorolojide kararsız atmosfer koşullarının temel göstergesidir; tabanı LCL seviyesinde kurulur."],"tanim_en":"A convective cloud exhibiting vertical development with dome-shaped, bulging upper structures produced by unstable air.","bag":{"kavram":["bulut-tur","carpisma"],"soru":[],"hesap":[]}},{"id":"cumulonimbus","tr":"Kümülonimbüs","en":"cumulonimbus","kisa":"Cb","tur":"kavram","es":["Cb","cumulonimbus cloud","oraj bulutu"],"tanim":["Büyük dikey kalınlığa sahip, tabanı alçak katmanda (2 km altında), tepesi ise tropopoza kadar uzanan dev fırtına bulutu kulesi.","Üst kesimi buz kristallerinden oluşur ve genellikle lifli yapıda geniş bir örs meydana getirir; yüksek CAPE ve derin konveksiyon ile beslenir.","Gök gürültüsü, şimşek, şiddetli sağanak, hamleli rüzgâr ve dolu gibi kuvvetli hava olaylarını üretir."],"tanim_en":"A heavy and dense convective cloud of great vertical extent, with an anvil-like ice top that generates thunderstorms, heavy rain, and hail.","bag":{"kavram":["bulut-tur","terselme","cape"],"soru":["S9","S10","S11","S12","S17","S46"],"hesap":[]}},{"id":"cumulus-congestus","tr":"Cumulus congestus","en":"Cumulus congestus","kisa":"Cu con","tur":"kavram","es":["gelişen cumulus","kule yapan kümülüs","towering cumulus","kule tipi bulut","bulut kulesi","cumulus tower"],"tanim":["Güçlü konvektif yukarı akımlarla düşey doğrultuda hızla kabaran, karnabahar benzeri keskin sınırlı kuleler oluşturan gelişmiş kümülüs bulutu.","Tabanı LCL seviyesinde bulunur; gövdesi ve keskin hatlı tepesi çoğunlukla sıvı su damlacıklarından oluşur, tepe henüz buzlaşıp lifli yapı ya da örs kazanmamıştır.","Koşullu kararsız atmosferde CAPE alanının büyüklüğüne bağlı olarak kısa sürede cumulonimbus aşamasına evrilerek sağanak yağış başlatabilir."],"tanim_en":"A towering convective cloud with significant vertical growth and sharp, cauliflower-shaped tops that has not yet formed an icy anvil.","bag":{"kavram":["bulut-tur","cape","kararlilik"],"soru":["S11","S12"],"hesap":[]}},{"id":"lenticular-cloud","tr":"Mercek bulutu","en":"lenticular cloud","kisa":"","tur":"kavram","es":["Altocumulus lenticularis","mercek biçimli bulut","lenticular","Ac lent","Altokümülüs lentikülaris"],"tanim":["Kararlı hava akımının bir dağ engelini aşarken oluşturduğu dağ dalgalarının doruk noktalarında meydana gelen mercek veya badem biçimli durağan bulut.","Dağ dalgası doruğunun rüzgârüstü tarafında yükselen nemli hava adyabatik soğumayla yoğuşur, doruğu aşıp rüzgâraltı tarafında alçalırken ısınarak buharlaşır; bu yüzden bulut rüzgâra rağmen yerinde sabit görünür.","Altında şiddetli türbülans ve rotor akımları barındırdığından havacılıkta uçuş güvenliği açısından kritik bir tehlike işaretidir."],"tanim_en":"A lens-shaped stationary cloud that forms at the crest of mountain waves in stable airflow crossing an elevated barrier.","bag":{"kavram":["bulut-tur"],"soru":["S17"],"hesap":[]}},{"id":"mackerel-sky","tr":"Uskumru gökyüzü","en":"Mackerel sky","kisa":"","tur":"kavram","es":["uskumru deseni","mackerel sky pattern"],"tanim":["Cirrocumulus veya altocumulus bulutlarının gökyüzünde balık pullarını veya kumsal dalgacıklarını andıran düzenli küçük parçacıklar ve dalgalar oluşturduğu görünüm.","Cirrocumulus durumunda 6 km üzerindeki buz kristali katmanı, altocumulus durumunda orta seviyedeki (2–6 km) su damlacığı katmanı rüzgâr kesmesi ve sığ konveksiyonla dalgalanarak biçimlenir.","Genellikle üst seviyede nem artışının ve yaklaşan bir cephe sisteminin erken habercisi sayılır."],"tanim_en":"A sky pattern characterized by small, rippled cirrocumulus or altocumulus cloud elements that resemble the scales of a fish.","bag":{"kavram":["bulut-tur"],"soru":["S12"],"hesap":[]}},{"id":"mammatus-cloud","tr":"Mammatus bulutu","en":"mammatus cloud","kisa":"","tur":"kavram","es":["torba bulut","meme bulut","mammatus"],"tanim":["Bulut tabanından aşağıya doğru torba, kese veya meme biçiminde sarkan keskin hatlı pürüzsüz çıkıntılar oluşturan bulut yapısı.","Kümülonimbüs örsünden dökülen soğuk ve hidrometeor yüklü havanın, altındaki kuru havada buharlaşarak negatif kaldırma kuvvetiyle çökmesi sonucu oluşur.","Çoğu bulutun aksine yukarı yönlü akımlarla değil, aşağı doğru çöken soğuk hava akımlarıyla beslenen ender bulut yapılarındandır."],"tanim_en":"A cloud structure characterized by hanging downward pouches formed by sinking pockets of cold air under a cumulonimbus anvil.","bag":{"kavram":["bulut-tur"],"soru":["S17"],"hesap":[]}},{"id":"nimbostratus","tr":"Nimbostratus","en":"Nimbostratus","kisa":"Ns","tur":"kavram","es":["yağmur katman bulutu","Ns","yağmur bulutu"],"tanim":["Geniş bir alanda yere ulaşan sürekli yağmur veya kar üreten, Güneş ışığını tamamen engelleyecek kadar kalın ve koyu gri renkli bir bulut katmanıdır.","Tabanı orta enlemlerde genellikle 2 km altına kadar alçalır ve çoğunlukla su damlacıkları ile eriyen kar taneciklerinden meydana gelir.","Bulut fiziğinde geniş ölçekli cephesel zorlanmış yükselme sonucu oluşur; kararlı hava koşullarında sürekli yağış sürecini temsil eder."],"tanim_en":"A dark and thick gray cloud layer producing continuous rain or snow that reaches the ground and blots out the Sun.","bag":{"kavram":["bulut-tur","yagis-surec"],"soru":["S12"],"hesap":[]}},{"id":"noctilucent-cloud","tr":"Gece parlayan bulut","en":"noctilucent cloud","kisa":"NLC","tur":"kavram","es":["noctilucent","kutup mezosfer bulutu","gece ışıldayan bulut","NLC","polar mesospheric cloud"],"tanim":["Kutup bölgelerinde yaz aylarında mezosfer katmanında, yaklaşık 85 km irtifada oluşan ve gün batımından sonra alttan gelen güneş ışığıyla aydınlanan en yüksek buluttur.","Çok düşük sıcaklıklarda meteor tozu ve su buharının birleşmesiyle meydana gelen son derece ince buz kristallerinden oluşur.","Bulut fiziğinde troposfer dışındaki aşırı soğuk koşullarda buz çekirdeklenmesini ve üst atmosfer dinamiğini incelemede temel bir örnektir."],"tanim_en":"A tenuous ice crystal cloud occurring in the summer polar mesosphere at altitudes of about 85 km, illuminated by sunlight from below the horizon.","bag":{"kavram":["bulut-tur"],"soru":["S17"],"hesap":[]}},{"id":"optical-halo","tr":"22° hale","en":"22° halo","kisa":"","tur":"kavram","es":["optik hale","buz halesi","22-degree halo","22 derece hale","halo"],"tanim":["Güneş veya Ay ışığının rastgele yönlenmiş altıgen buz kristallerinden 22° minimum sapma açısıyla kırılması sonucu oluşan dairesel optik olaydır.","Işığın 60° tepe açılı prizma geometrisine sahip buz kristallerinde kırılmasıyla oluştuğu için su damlacıklarından meydana gelen bulutlarda gözlenmez.","Bulut fiziği ve rasat uygulamasında gökyüzündeki ince tül tabakasının su damlası değil yüksek seviye buz kristali içerdiğini belirten tanı aracıdır."],"tanim_en":"A luminous optical ring with an angular radius of 22° formed by the refraction of light through hexagonal ice crystals.","bag":{"kavram":["bulut-tur"],"soru":["S12"],"hesap":[]}},{"id":"overshooting-top","tr":"Aşma tepesi","en":"overshooting top","kisa":"","tur":"kavram","es":["stratosfere taşan tepe","aşan tepe","overshooting dome"],"tanim":["Şiddetli bir Kümülonimbüs bulutundaki güçlü yukarı hava akımının denge seviyesini ve tropopozu aşarak alt stratosfere doğru kubbe biçiminde yükselmesidir.","Stratosferde çevre sıcaklığı yükseklikle arttığından yükselen hava parseli çevresine göre soğuk kalarak negatif kaldırma kuvvetine uğrar ve kısa sürede geri çöker.","Bulut dinamiğinde yukarı akımın kinetik enerjisinin büyüklüğünü ve fırtına hücresinin şiddetini doğrudan yansıtan bir yapıdır."],"tanim_en":"A domelike protrusion above a cumulonimbus anvil penetrating the tropopause into the lower stratosphere by virtue of strong updraft momentum.","bag":{"kavram":["bulut-tur","kaldirma"],"soru":["S9"],"hesap":[]}},{"id":"polar-stratospheric-cloud","tr":"Kutup stratosfer bulutu","en":"polar stratospheric cloud","kisa":"PSC","tur":"kavram","es":["PSC","sedef bulutu","nacreous cloud","polar stratospheric cloud kısaltması","kutup stratosferik bulutu"],"tanim":["Kutup kışında kutup girdabı içinde stratosfer sıcaklığının yaklaşık −78 °C altına indiği aşırı soğuk koşullarda 20–30 km irtifada oluşan bulutlardır.","Sedef parlaklığında görünen bu bulutlar nitrik asit trihidrat kristalleri veya aşırı soğumuş su ve buz taneciklerinden meydana gelir.","Bulut fiziği ve atmosfer kimyasında klor bileşiklerini etkinleştirerek kutup bölgesi ozon incelmesinde doğrudan rol oynar."],"tanim_en":"A winter polar stratospheric cloud occurring at altitudes between 20 and 30 km under extreme cold conditions below −78 °C.","bag":{"kavram":["bulut-tur"],"soru":["S17"],"hesap":[]}},{"id":"stratiform-cloud","tr":"Katman bulutu","en":"stratiform cloud","kisa":"","tur":"kavram","es":["duz bulut","layered cloud","tabaka bulut","layer cloud","stratiform clouds","katman bulut"],"tanim":["Yatay yayılımı düşey kalınlığına göre çok geniş olan, gökyüzünü geniş tabaka halinde örten bulut grubudur.","Statik olarak kararlı bir atmosfer katmanında havanın cephe yüzeyi boyunca veya orografik zorlanmayla yavaşça yükselmesi sonucu oluşur.","Bulut fiziğinde Stratus, Altostratus ve Nimbostratus cinslerini içerir; zayıf düşey hızlar ve sürekli yağış tipiyle nitelenir."],"tanim_en":"A cloud having extensive horizontal development and a layered appearance, formed by widespread slow ascent in a statically stable environment.","bag":{"kavram":["bulut-tur","kararlilik"],"soru":["S6","S11","S12","S23"],"hesap":[]}},{"id":"wind-shear","tr":"Rüzgâr kesmesi","en":"Wind shear","kisa":"","tur":"kavram","es":["rüzgar kayması","düşey rüzgâr kesmesi","yatay rüzgâr kesmesi","vertical wind shear"],"tanim":["Rüzgâr vektörünün veya herhangi bir bileşeninin belirli bir doğrultuda, özellikle yükseklikle veya yatay mesafeyle gösterdiği yerel değişimdir.","Düşey rüzgâr kesmesi birim irtifa başına hız ve yön değişimi olarak m s⁻¹ / km veya s⁻¹ birimleriyle ifade edilir.","Bulut fiziğinde Kelvin–Helmholtz dalgaları ile sirrokümülüsteki uskumru desenlerini üretir ve fırtına hücrelerinin yukarı akımını eğerek ömrünü uzatır."],"tanim_en":"The local variation of the wind vector or any of its components with distance in a specific direction.","bag":{"kavram":["bulut-tur"],"soru":["S12","S17"],"hesap":[]}},{"id":"crystal-habit","tr":"Buz kristali biçimi","en":"ice crystal habit","kisa":"","tur":"kavram","es":["kristal morfolojisi","buz alışkanlığı","crystal habit","kristal büyüme biçimi","kristal alışkanlığı"],"tanim":["Aşırı doymuş bir ortamda büyüyen buz kristalinin sıcaklık ve aşırı doymuşluk koşullarına bağlı olarak benimsediği karakteristik geometrik dış yapıdır.","Altıgen temel simetriye dayanır; ortam sıcaklığına göre levha, prizmatik sütun, iğne veya dallı dendrit biçimlerine evrilir.","Bulut fiziğinde kristalin kütle artış hızını, iki boyutlu ya da üç boyutlu difüzyonel büyüme denklemlerini ve limit düşme hızını doğrudan etkiler."],"tanim_en":"The characteristic geometric shape and growth form assumed by an ice crystal, governed primarily by ambient temperature and vapor supersaturation.","bag":{"kavram":["buz-kutle"],"soru":[],"hesap":[]}},{"id":"dendrite","tr":"Dendrit","en":"dendrite","kisa":"","tur":"kavram","es":["dallı kar kristali","dallı kristal","stellar dendrite","dendrit bandı","Dendrit büyüme bandı","dendritic growth zone"],"tanim":["Bulut içinde yaklaşık −12 ile −16 °C sıcaklık aralığında su buharı depozisyonu ile oluşan altı kollu, ağaçsı dallanma gösteren kar kristali.","Su ve buz arasındaki doyma buhar basıncı farkının en yüksek olduğu −12 °C ile −15 °C civarında en yüksek difüzyonel büyüme hızına erişir.","Geniş yüzey alanı ve dallı yapısı sayesinde buharı hızla toplayarak bulut içinde kar tanelerinin kısa sürede oluşmasını sağlar."],"tanim_en":"An ice crystal exhibiting a branched, tree-like hexagonal structure that forms by vapor deposition around minus 15 °C.","bag":{"kavram":["buz-kutle","bergeron"],"soru":["S37","S39"],"hesap":[]}},{"id":"snowflake","tr":"Kar tanesi","en":"snowflake","kisa":"","tur":"kavram","es":["kar kristali","snow crystal","kar kristali kümesi","küme kar kristali"],"tanim":["Buluttan düşen tek bir buz kristali veya daha yaygın olarak çok sayıda buz kristalinin topaklanarak kenetlenmesiyle oluşan katı yağış elemanı.","Büyüklüğü tekil mikroskobik kristallerden topaklanma sonucu birkaç santimetre çapa kadar geniş bir aralıkta değişebilir.","Soğuk bulut mekanizmasında difüzyon, kırağılaşma ve topaklanma süreçleriyle olgunlaşır; 0 °C seviyesinin altına indiğinde eriyerek yağmur damlalarına dönüşür."],"tanim_en":"An individual ice crystal or an aggregate of interconnected ice crystals falling from a cloud.","bag":{"kavram":["buz-kutle","yagis-surec","bergeron"],"soru":["S39"],"hesap":[]}},{"id":"two-dimensional-plate","tr":"Levha (buz kristali)","en":"plate (ice crystal)","kisa":"","tur":"kavram","es":["2D levha","ince buz levhasi","thin plate","2-D levha","buz levhası","ince levha"],"tanim":["Genellikle altıgen biçimli, bazal yüzeylerine dik yönde kalınlığı sabit kalırken kenarlarından genişleyen düz buz kristali formu.","Kalınlığı d sabit kabul edildiğinde yarıçapı zamanla doğrusal artar ve toplam kütlesi sürenin karesiyle (t²) orantılı olarak büyür.","0 ile −4 °C ve −10 ile −22 °C aralıklarında levha biçimi baskındır; aynı sürede küresel (3 boyutlu) kristalden çok daha hızlı kütle toplar."],"tanim_en":"A flat hexagonal ice crystal that expands along its edges with nearly constant thickness, yielding quadratic mass growth over time.","bag":{"kavram":["buz-kutle","bergeron"],"soru":["S37","S39"],"hesap":["buz-kutle"]}},{"id":"ice-density","tr":"Buz yoğunluğu","en":"ice density","kisa":"ρᵢ","tur":"olcu","es":["buzun yoğunluğu","density of ice","kristal buzu yoğunluğu","rhoi","rho_i","saf buz yoğunluğu"],"tanim":["Buzun birim hacminin kütlesi olup bulut fiziğinde buz kristallerinin kütle ve boyut hesaplamalarında kullanılan temel sabittir.","Kitapta standart değeri 916,8 kg/m³ (yaklaşık 917 kg/m³) olarak alınır; sıvı suyun yoğunluğundan (1000 kg/m³) düşüktür.","Kristalin buhar difüzyonu ile büyüme denkleminde paydada yer alarak yarıçap artış hızını doğrudan belirler."],"tanim_en":"The mass per unit volume of ice, taken as approximately 917 kg m⁻³ in cloud microphysics formulations.","bag":{"kavram":["buz-kutle"],"soru":["S39"],"hesap":["buz-kutle"]}},{"id":"aggregation","tr":"Topaklanma","en":"aggregation","kisa":"","tur":"surec","es":["kristal birleşmesi","kar kristali topaklanması","kar tanesi oluşumu","ice crystal aggregation","kristal topaklanması"],"tanim":["Atmosferde katı yağış parçacıklarının ve buz kristallerinin çarpışıp yapışarak daha büyük parçacıklar üretmesi süreci.","Özellikle 0 °C seviyesine yakın sıcaklıklarda buz yüzeyindeki yarı sıvı tabaka sayesinde kristallerin kenetlenme verimi hızla yükselir.","Soğuk bulutlarda difüzyonla büyüyen tekil kristallerin santimetre boyutunda kar tanelerine dönüşmesini sağlar."],"tanim_en":"The phenomenon in which solid precipitation particles collide and adhere in the atmosphere to produce larger hydrometeors such as snowflakes.","bag":{"kavram":["buz-kutle","yagis-surec","bergeron"],"soru":["S32","S33","S36","S42","S46"],"hesap":[]}},{"id":"riming","tr":"Kırağılanma","en":"riming","kisa":"","tur":"surec","es":["tanelenme","kırağılaşma","accretion","kristale damla donması","accretion by ice"],"tanim":["Düşmekte olan bir buz kristali veya kar tanesinin aşırı soğumuş bulut damlacıklarıyla çarpışması ve damlacıkların anında donarak yapışması süreci.","Kristalin düşme hızı ve süpürme alanı arttıkça hızlanır; ileri aşamalarında graupel (kar paleti) ve dolu tanelerini oluşturur.","Accretion (birikim) adıyla da geçen bu süreç, uçak gövdesinde oluşan yapısal buzlanmayla aynı mekanizmadır."],"tanim_en":"Growth of an ice crystal or snowflake by the collision and freezing of supercooled cloud droplets upon impact.","bag":{"kavram":["buz-kutle","yagis-surec","bergeron"],"soru":["S39","S46"],"hesap":[]}},{"id":"unit-joule-per-kilogram","tr":"Kilogram başına Joule","en":"joule per kilogram","kisa":"J/kg","tur":"birim","es":["J/kg","J kg⁻¹","Joule bölü kilogram","özgül enerji birimi","CAPE birimi","jul bölü kilogram"],"tanim":["Uluslararası Birimler Sisteminde (SI) birim kütle başına düşen enerjiyi veya yapılan işi ifade eden türetilmiş özgül enerji birimidir.","Sembolü J/kg veya J kg⁻¹ olup boyutsal olarak m² s⁻² birimine eşittir.","Bulut termodinamiğinde CAPE ve CIN gibi konvektif kararsızlık indeksleri ile buharlaşma gizli ısısı Lᵥ (2,5×10⁶ J/kg) bu birimle belirtilir."],"tanim_en":"An SI unit of specific energy expressing energy or work per unit mass, equivalent to one meter squared per second squared.","bag":{"kavram":["cape","theta-e","es-cc"],"soru":["S3","S10"],"hesap":[]}},{"id":"thermodynamic-diagram","tr":"Termodinamik diyagram","en":"thermodynamic diagram","kisa":"","tur":"cihaz","es":["aerolojik diyagram","aerological diagram","termodinamik profil grafiği","Skew-T grafiği"],"tanim":["Atmosferin termodinamik durumunu basınç, sıcaklık ve nem değişkenleriyle grafik üzerinde göstermek için kullanılan diyagramdır.","Enerji eşdeğerliği özelliğine sahip diyagramlarda parsel ve çevre eğrileri arasında kalan alan doğrudan birim kütle başına enerjiye (J/kg) karşılık gelir.","Bulut fiziğinde LCL, LFC, EL seviyelerinin bulunması, CAPE ve CIN hesaplamaları ile atmosferik kararlılık durumunun analizinde temel araçtır."],"tanim_en":"A diagram used to represent the thermodynamic state of the atmosphere as defined by pressure, temperature, and humidity, on which equal areas represent equal energy.","bag":{"kavram":["cape","kararlilik"],"soru":[],"hesap":[]}},{"id":"equilibrium-level","tr":"Denge seviyesi","en":"equilibrium level","kisa":"EL","tur":"kavram","es":["EL","nötr yüzerlik seviyesi","level of neutral buoyancy","nötr kaldırma seviyesi","LNB","denge seviyesi kısaltması"],"tanim":["Yükselen nemli bir hava parselinin sıcaklığının çevre sıcaklığına yeniden eşitlendiği ve pozitif kaldırma kuvvetinin sıfırlandığı irtifadır.","Termodinamik diyagramda pozitif alanın bittiği üst sınır olup metre veya hektopaskal (hPa) basınç cinsinden belirlenir.","Bulut fiziğinde konvektif bulut kulelerinin tepe yüksekliğini ve konvektif potansiyel enerjinin (CAPE) üst entegrasyon sınırını tanımlar."],"tanim_en":"The atmospheric level at which an ascending air parcel achieves neutral buoyancy when its virtual temperature becomes equal to that of the environment.","bag":{"kavram":["cape","lcl-lfc"],"soru":["S10"],"hesap":["cape"]}},{"id":"negative-area","tr":"Negatif alan","en":"negative area","kisa":"","tur":"kavram","es":["CIN alanı","negatif enerji alanı","negative energy area"],"tanim":["Termodinamik diyagramda parsel eğrisinin çevre eğrisinin solunda kaldığı (parselin çevreden soğuk olduğu) alandır; kitapta asıl olarak yüzey ile LFC arasındaki bölüm (CIN) kastedilir, EL üstündeki aşma bölgesi de negatiftir.","Birimi J/kg'dır; parseli LFC'ye çıkarmak için dışarıdan verilmesi gereken enerjiyi gösterir. Kitapta CIN değeri negatif işaretle yazılır.","Isınma, cephe, dağ ya da yakınsama bu engeli aşabilir; CIN büyükse CAPE kilitli kalır, küçükse derin konveksiyon kolay başlar."],"tanim_en":"The negative area is the region on a thermodynamic diagram, below the level of free convection, where the lifted parcel is colder than its environment; its size is proportional to the convective inhibition (CIN).","bag":{"kavram":["cape"],"soru":["S8"],"hesap":["cape"]}},{"id":"positive-area","tr":"Pozitif alan","en":"positive area","kisa":"","tur":"kavram","es":["CAPE alanı","pozitif enerji alanı","positive energy area"],"tanim":["Termodinamik diyagramda parsel eğrisinin çevre eğrisinin sağında kaldığı, LFC ile denge seviyesi (EL) arasındaki alandır; parsel burada çevreden sıcaktır.","Birimi J/kg = m²/s²'dir; kaldırma kuvvetinin birim kütle başına yaptığı toplam işi ve parselin kazanabileceği kinetik enerjinin üst sınırını verir.","Kalın pozitif alan büyük CAPE ve derin Cb demektir; en büyük düşey hız w_max ≈ √(2·CAPE) bağıntısıyla bulunur."],"tanim_en":"The positive area is the region on a thermodynamic diagram between the level of free convection and the equilibrium level where the lifted parcel is warmer than its environment; its size is proportional to the convective available potential energy (CAPE).","bag":{"kavram":["cape"],"soru":["S10"],"hesap":[]}},{"id":"thunderstorm","tr":"Gök gürültülü fırtına (oraj)","en":"thunderstorm","kisa":"","tur":"kavram","es":["oraj","gök gürültülü sağanak","convective storm"],"tanim":["Cumulonimbus bulutundan oluşan; şimşek ve gök gürültüsü eşlik eden, çoğu kez sağanak ya da dolu getiren yerel konvektif fırtınadır.","Güçlü yukarı hava akımı, örs ve düşey gelişme taşır; kuramsal tepe düşey hız CAPE'ten w_max ≈ √(2·CAPE) ile tahmin edilir.","Kitapta CAPE ve CIN birlikte yorumlanır: büyük CAPE fırtınanın şiddetini, küçük CIN ise başlama kolaylığını gösterir."],"tanim_en":"A thunderstorm is a local storm produced by a cumulonimbus cloud and accompanied by lightning and thunder, often with heavy rain or hail.","bag":{"kavram":["cape"],"soru":["S9","S10","S12","S17","S45"],"hesap":[]}},{"id":"troposphere","tr":"Troposfer","en":"troposphere","kisa":"","tur":"kavram","es":["üst troposfer","troposfer katmanı","tropospheric layer"],"tanim":["Atmosferin yüzeyden kutuplarda yaklaşık 9 km, ekvatorda yaklaşık 17 km yüksekliğe uzanan, sıcaklığın yükseklikle oldukça düzgün azaldığı alt katmanıdır.","Hava olaylarının ve bulutların neredeyse tamamı burada oluşur; üstündeki sınır tropopozdur.","Kitapta parsel yükselmesi, CAPE ve CIN hesapları troposfer içinde yapılır; tropopoz üstündeki sıcaklık artışı Cb'nin yükselmesini durdurur."],"tanim_en":"The troposphere is the lower part of the terrestrial atmosphere, extending from the surface up to a height varying from about 9 km at the poles to about 17 km at the equator, in which temperature drops fairly uniformly with height.","bag":{"kavram":["cape"],"soru":["S1","S10","S17"],"hesap":[]}},{"id":"maximum-vertical-velocity","tr":"En büyük düşey hız","en":"maximum vertical velocity","kisa":"w_max","tur":"olcu","es":["maksimum dusey hiz","maximum updraft speed","tepe düşey hız","wmax","maksimum updraft hızı","teorik en büyük düşey hız"],"tanim":["Parselin CAPE'in tamamını kinetik enerjiye çevirmesi durumunda ulaşabileceği kuramsal yukarı hava akımı hızıdır; sembolü w_max, birimi m/s'dir.","Enerji korunumundan ½w² = CAPE ve w(LFC) ≈ 0 varsayımıyla w_max = √(2·CAPE) bulunur.","Bu bir üst sınırdır; karışma (entrainment), yağış yükü ve basınç etkileri yüzünden gerçek yukarı hava akımı yaklaşık yarısı kadardır."],"tanim_en":"Maximum vertical velocity is the theoretical upper limit of updraft speed, obtained when all convective available potential energy is converted to kinetic energy, w_max = √(2 CAPE).","bag":{"kavram":["cape"],"soru":["S10"],"hesap":["cape"]}},{"id":"deep-convection","tr":"Derin konveksiyon","en":"deep convection","kisa":"","tur":"surec","es":["derin konvektif hareket","derin nemli konveksiyon","deep moist convection","fırtına konveksiyonu","derin konvektif fırtına"],"tanim":["Nemli konveksiyonun sınır tabakasından tropopoza yakın seviyelere kadar troposferin büyük bölümünü kapladığı süreçtir; genellikle Cb ile görülür.","Başlaması CAPE ve CIN dengesine bağlıdır: CAPE büyük ve CIN küçükse kolay başlar, CIN büyükse CAPE kilitli kalır.","Gün içi ısınma, cephe ya da dağ kaldırması bu kilidi açabilir; tropopoz üstündeki kararlı terselme süreci durdurur."],"tanim_en":"Deep convection is moist convection that extends through most of the depth of the troposphere, typically in the form of cumulonimbus clouds.","bag":{"kavram":["cape"],"soru":["S9","S10","S12","S17"],"hesap":[]}},{"id":"entrainment","tr":"Entrainment","en":"entrainment","kisa":"","tur":"surec","es":["içe karışma","çevre havası karışması","lateral entrainment"],"tanim":["Çevre havanın var olan bir buluta ya da hava akımına karışarak onun parçası olması sürecidir.","Yukarı akımı çevreden daha kuru ve soğuk havayla sulandırır; bu yüzden gerçek w, w_max = √(2·CAPE) değerinin yaklaşık yarısıdır.","Kitapta limit hız konusundaki aerodinamik sürüklenme (drag) farklı bir kavramdır; entrainment kütle karışmasıdır, kuvvet değildir."],"tanim_en":"Entrainment is the mixing of environmental air into a pre-existing organized cloud or air current so that the environmental air becomes part of the current or the cloud.","bag":{"kavram":["cape"],"soru":["S10","S23","S41"],"hesap":[]}},{"id":"collector-drop","tr":"Toplayıcı damla","en":"collector drop","kisa":"","tur":"kavram","es":["toplayan damla","collecting drop","iri damla","yakalayıcı damla","iri toplayıcı damlacık","öncü damla"],"tanim":["Çarpışma ve birleşme sürecinde çevresindeki küçük bulut damlalarından daha yüksek limit düşme hızına sahip olan ve düşerken onları süpüren iri damla.","Çarpışma mekanizmasını etkin başlatabilmek için yarıçapının en az 20 µm olması gerekir; kitabın hesaplarında toplayıcı damla 100 µm yarıçaptan başlatılır.","Sürekli toplama modelinde geometrik süpürme silindiri oluşturarak bulut sıvı suyunu toplar ve hızla yağmur damlasına dönüşür."],"tanim_en":"A relatively large cloud drop that falls faster than surrounding smaller droplets, sweeping them out through collision and coalescence.","bag":{"kavram":["carpisma"],"soru":["S32","S33","S41","S44","S46"],"hesap":[]}},{"id":"raindrop","tr":"Yağmur damlası","en":"raindrop","kisa":"","tur":"kavram","es":["yağmur damlası boyutu","rain drop","yağış damlası","rain droplet"],"tanim":["Çapı 0,5 mm veya daha büyük olan sıvı su damlası.","Tipik bir yağmur damlası yaklaşık bir milyon bulut damlacığı kadar su taşır ve limit düşme hızı yaklaşık 7 m s⁻¹ mertebesinde.","Difüzyonla bu boyuta ulaşamayacağı için sıcak bulutlarda çarpışma–birleşme, soğuk bulutlarda Bergeron süreciyle büyür."],"tanim_en":"A drop of water with a diameter of 0.5 mm or more.","bag":{"kavram":["carpisma","yagis-surec","difuzyon-buyume"],"soru":["S36","S41","S44"],"hesap":[]}},{"id":"warm-cloud","tr":"Sıcak bulut","en":"warm cloud","kisa":"","tur":"kavram","es":["donmasız bulut","yalnız sıvı su içeren bulut","warm clouds","sıcak bulut yapısı","warm-rain cloud"],"tanim":["Tabanından tepesine kadar sıcaklığı 0 °C üzerinde olan ve bütünüyle sıvı su damlacıklarından oluşan bulut.","İçinde buz fazı bulunmadığından yağış üretimi tümüyle çarpışma ve birleşme mekanizmasına bağlı olarak gerçekleşir.","Özellikle tropik ve denizel hava kütlelerindeki sığ bulutlarda yaygın olup higroskopik tohumlama hedefidir."],"tanim_en":"A cloud having temperatures entirely above 0 °C throughout its depth and containing only liquid water droplets.","bag":{"kavram":["carpisma","yagis-surec"],"soru":["S33","S42","S46"],"hesap":[]}},{"id":"coalescence-efficiency","tr":"Birleşme verimi","en":"coalescence efficiency","kisa":"","tur":"olcu","es":["kaynaşma verimi","E_coal","Ecoal","damla birleşme verimi"],"tanim":["Fiziksel olarak birbiriyle çarpışan bulut damlalarından sekmeden birleşip tek bir büyük damla oluşturanların oranı olarak tanımlanan boyutsuz katsayı.","Değeri 0 ile 1 arasında değişir; damla boyutlarına, çarpışma kinetik enerjisine ve aradaki hava filminin tahliyesine bağlıdır.","Çarpışma verimi ile çarpılarak toplam büyüme hızını belirleyen toplama verimini oluşturur."],"tanim_en":"The fraction of all colliding drops which coalesce to form larger drops.","bag":{"kavram":["carpisma"],"soru":["S32","S42"],"hesap":["carpisma"]}},{"id":"collection-efficiency","tr":"Toplama verimi","en":"collection efficiency","kisa":"E","tur":"olcu","es":["toplama etkinliği","toplama katsayısı","total collection efficiency","collection efficiency E"],"tanim":["Büyük bir toplayıcı damlanın düşüş yolundaki küçük damlacıklarla çarpışma ve birleşme olasılıklarının çarpımını belirten boyutsuz oran.","Çarpışma verimi ile birleşme veriminin çarpımına eşittir (E = E_c · E_coal); değeri 0 ile 1 aralığında olup kitabın hesap örneklerinde 0,8 alınır.","Sürekli toplama modelinde düşen toplayıcı damlanın yarıçap artış hızını (dR/dt) belirler."],"tanim_en":"The fraction of cloud droplets in the geometric sweep path of a falling collector drop that actually collide and coalesce with it.","bag":{"kavram":["carpisma"],"soru":["S39","S42"],"hesap":["carpisma"]}},{"id":"collision-efficiency","tr":"Çarpışma verimi","en":"collision efficiency","kisa":"E_c","tur":"olcu","es":["çarpışma etkinliği","çarpma verimi","E_c","Ec"],"tanim":["Başlangıçta çarpışma rotasında bulunan ve çevresindeki hava akışına rağmen toplayıcı damlayla fiziksel temas kurabilen damlacıkların oranı.","Boyutsuz bir orandır; hidrodinamik akış çizgilerinin küçük damlacıkları kenara saptırması nedeniyle küçük toplayıcı damlalar için sıfıra yakın kalabilir.","Çarpışma-birleşme sürecinde toplayıcı damlanın geometrik süpürme silindirindeki yakalama payını belirler."],"tanim_en":"Fraction of drops on an initial collision course with other drops that actually collide with them.","bag":{"kavram":["carpisma"],"soru":["S42","S46"],"hesap":["carpisma"]}},{"id":"liquid-water-content","tr":"Sıvı su içeriği","en":"liquid water content","kisa":"LWC","tur":"olcu","es":["bulut sıvı su içeriği","sıvı su miktarı","LWC","bulut sıvı suyu","sıvı su kütlesi"],"tanim":["Birim bulut hacminde bulunan sıvı su damlacıklarının toplam kütlesi.","SI birimi kg/m³ olup bulut fiziğinde yaygın olarak g/m³ cinsinden ifade edilir (1 g/m³ = 10⁻³ kg/m³; bulutlarda tipik değeri 10⁻³ kg/m³ kabul edilir).","Sürekli toplama modelinde düşen damlanın kütle kazanım hızını belirler; aynı LWC çok sayıda çekirdeğe bölünürse (karasal hava) damlalar küçük, az sayıda çekirdeğe bölünürse (denizel hava) iri olur."],"tanim_en":"The total amount of liquid water per unit volume of cloudy air.","bag":{"kavram":["carpisma","mp","su-butcesi"],"soru":["S4","S32","S33","S42","S44","S46"],"hesap":["ccn","carpisma"]}},{"id":"liquid-water-density","tr":"Sıvı su yoğunluğu","en":"liquid water density","kisa":"ρ_L","tur":"olcu","es":["suyun yoğunluğu","water density","su yoğunluğu","density of liquid water","ρ_L","rho_L"],"tanim":["Sıvı haldeki suyun birim hacim başına düşen kütlesi.","Standart koşullarda ve bulut fiziği hesaplarında sabit olarak 1000 kg/m³ kabul edilir.","Damla kütlesi ile damla yarıçapı arasındaki bağıntıyı kurar ve sürekli toplama denkleminde yarıçap büyüme hızını belirler."],"tanim_en":"The density of liquid water, taken as 1000 kg m⁻³ in cloud droplet growth equations.","bag":{"kavram":["carpisma","su-butcesi","ccn"],"soru":["S32","S36","S42","S45"],"hesap":["ccn","dif-buyume","su-butcesi"]}},{"id":"snowball-effect","tr":"Kartopu etkisi","en":"snowball effect","kisa":"","tur":"surec","es":["runaway droplet growth","runaway growth","runaway collection","kartopu büyümesi","hızlanan büyüme"],"tanim":["Çarpışma-birleşme sürecinde toplayıcı bir damlanın büyüdükçe limit düşme hızının artması ve birim zamanda daha büyük hacim tarayarak giderek daha hızlı büyümesidir.","Limit düşme hızının yarıçapla doğrusal arttığı ara rejimde (w_T = k₂ R) dR/dt yarıçapla orantılı olur ve yarıçap zamanla üstel artar.","Sıcak bulutlarda difüzyonun yavaşladığı eşikten sonra yağmur damlalarının çok kısa sürede hızla oluşmasını sağlayan temel mekanizmadır."],"tanim_en":"The accelerating growth mechanism where a falling collector drop sweeps a larger volume as it expands, leading to exponential radius enlargement.","bag":{"kavram":["carpisma"],"soru":[],"hesap":[]}},{"id":"continuous-collection-model","tr":"Sürekli toplama modeli","en":"continuous collection model","kisa":"","tur":"yontem","es":["sürekli çarpışma yaklaşımı","süpürme hacmi modeli","sürekli süpürme modeli","çarpışma büyüme denklemi","collection equation","sürekli toplama denklemi"],"tanim":["Düşen büyük bir toplayıcı damlanın, süpürdüğü hacim içindeki küçük bulut damlacıklarını kesintisiz ve sürekli bir ortam gibi toplayarak büyüdüğünü varsayan analitik yaklaşım.","Büyüme hızı dR/dt = (E · LWC · w_T) / (4 ρ_L) formülüyle ifade edilir; ayrık çarpışmaları tekdüze ortalama büyümeyle basitleştirir.","Sıcak bulutlarda çarpışma-birleşme yoluyla yağmur damlası oluşum hızını ve damla boyut gelişimini hesaplamada temel alınır."],"tanim_en":"A theoretical approach assuming a falling collector drop sweeps up smaller cloud droplets in a continuous manner proportional to its cross section and fall speed.","bag":{"kavram":["carpisma"],"soru":[],"hesap":["carpisma"]}},{"id":"net-heat-effect","tr":"Net ısı etkisi","en":"net heat effect","kisa":"Q","tur":"olcu","es":["net buharlaşma ısısı","net heat of vaporization"],"tanim":["Doygun tuz çözeltisinin buhar basıncı için kitabın kullandığı etkin ısıdır; buharlaşma ısısından çözünme katkısı çıkarılarak Q = Q₁ − S·Q₂ yazılır.","Birimi J/mol'dür; saf suda Lᵥ·M ≈ 45 kJ/mol, kitaptaki NaNO₃ çözeltisinde Q ≈ 43,3 kJ/mol'dür.","Clausius–Clapeyron iki nokta yönteminde ln P ile 1/T doğrusal çıkar ve eğim −Q/R olur; iki sıcaklıktan buhar basıncı hesaplanır."],"tanim_en":"The net heat effect Q is the effective molar heat governing the temperature dependence of the vapor pressure over a saturated solution, equal to the heat of vaporization minus the contribution of dissolution.","bag":{"kavram":["cc-iki"],"soru":["S25"],"hesap":["cc-iki"]}},{"id":"solubility","tr":"Çözünürlük","en":"solubility","kisa":"","tur":"olcu","es":["doygunluk derişimi","çözünme kapasitesi","solubility of salt"],"tanim":["Belirli sıcaklık ve basınçta bir çözünenin çözücüde ulaşabileceği denge derişimidir; bu derişimde çözelti doygundur.","Kitapta doygun tuz çözeltisinin sudaki mol kesri x_w ve çözünürlüğün sıcaklıkla değişimi (S) Q = Q₁ − S·Q₂ içinde yer alır.","Çözünürlüğü yüksek tuzda x_w küçüktür; kritik bağıl nem RH_kr = 100·x_w düşük çıkar ve tuz daha düşük nemde eriyik olur."],"tanim_en":"Solubility is the equilibrium concentration of a solute in a solvent at a given temperature and pressure.","bag":{"kavram":["cc-iki","higroskopik"],"soru":["S25"],"hesap":["drh"]}},{"id":"universal-gas-constant","tr":"Evrensel gaz sabiti","en":"universal gas constant","kisa":"R","tur":"olcu","es":["ideal gaz sabiti","molar gas constant","R_u","molar gaz sabiti"],"tanim":["Tüm ideal gazlar için aynı olan, mol başına gaz sabitidir; R ≈ 8,314 J mol⁻¹ K⁻¹.","Evrensel gaz sabiti molar kütleye bölünerek özgül gaz sabiti bulunur (ℜ = R/M): ℜd = 287 J kg⁻¹ K⁻¹ (kuru hava), ℜᵥ = 461,5 J kg⁻¹ K⁻¹ (su buharı).","Kitapta Clausius–Clapeyron iki nokta yönteminde Q/R terimi olarak girer; ℜd ve ℜᵥ ise θ, Tᵥ ve ε hesaplarında kullanılır."],"tanim_en":"The universal gas constant is the molar gas constant, R ≈ 8.314 J mol⁻¹ K⁻¹, that appears in the ideal gas law for one mole of any ideal gas.","bag":{"kavram":["cc-iki"],"soru":["S25"],"hesap":["cc-iki"]}},{"id":"aerosol","tr":"Aerosol","en":"aerosol","kisa":"","tur":"kavram","es":["atmosferik aerosol","aerosol parçacığı","aerosoller","aerosol parçacıkları","aerosol particles","atmospheric aerosol"],"tanim":["Atmosferde asılı halde bulunan katı parçacıklar ya da sıvı damlacıklar.","Yarıçapları 0,001 µm ile 100 µm arasında değişir; bulut damlası oluşumunda rol alan çekirdekler çoğunlukla 0,01–1 µm aralığında yer alır.","Bulut mikrofiziğinde bulut yoğuşma çekirdeği ya da buz çekirdeği görevi görerek su buharının heterojen çekirdeklenmesini sağlar."],"tanim_en":"An aerosol is a suspension of fine solid particles or liquid droplets in the atmosphere.","bag":{"kavram":["ccn","kelvin"],"soru":["S26","S28","S29","S32","S33","S36"],"hesap":[]}},{"id":"ammonium-sulfate","tr":"Amonyum sülfat","en":"ammonium sulfate","kisa":"(NH₄)₂SO₄","tur":"kavram","es":["(NH4)2SO4","ammonium sulphate","sülfat aerosolü","(NH₄)₂SO₄"],"tanim":["Atmosferde yaygın bulunan, suda kolayca çözünen inorganik ve higroskopik bir tuz aerosolü.","Van 't Hoff faktörü i = 3 olup kritik bağıl nem eşiği yaklaşık %81 seviyesinde yer alır.","Bulut yoğuşma çekirdeği olarak görev yapar ve çözünen etkisiyle kritik aşırı doymuşluğu düşürerek damlacık oluşumunu kolaylaştırır."],"tanim_en":"Ammonium sulfate is a hygroscopic aerosol salt that acts as an effective cloud condensation nucleus in the atmosphere.","bag":{"kavram":["ccn","higroskopik","kohler"],"soru":["S24","S30","S31"],"hesap":[]}},{"id":"continental-air","tr":"Karasal hava (kara havası)","en":"continental air","kisa":"","tur":"kavram","es":["karasal hava kütlesi","continental air mass","kara tipi aerosol","continental CCN","karasal aerosol","continental aerosol"],"tanim":["Bir kıta üzerinde birkaç gün kalarak nem oranı görece düşük kalan ve yüksek miktarda aerosol içeren hava kütlesi.","Bulut yoğuşma çekirdeği (CCN) derişimi yüksektir; S = %0,5 aşırı doymuşlukta aktif CCN sayısı yaklaşık 4,24 × 10⁸ m⁻³ (424 cm⁻³) mertebesinde bulunur.","Yüksek çekirdek sayısı mevcut bulut suyunu çok sayıda küçük damlaya böler, çarpışma-birleşmeyi geciktirir."],"tanim_en":"Mass of air that remains over a continent for several days and therefore has a fairly low moisture content.","bag":{"kavram":["ccn"],"soru":["S32"],"hesap":[]}},{"id":"continental-cloud","tr":"Kara bulutu","en":"continental cloud","kisa":"","tur":"kavram","es":["karasal bulut","kıtasal bulut","continental air mass cloud","karasal kümülüs","continental Cu","kara kümülüsü"],"tanim":["Karasal hava kütlesi içinde yüksek aerosol ve CCN derişimi altında oluşan bulut.","Aynı sıvı su içeriğini (tipik 1 g/m³) çok sayıda çekirdeğe bölerek küçük ortalama damla yarıçapı (yaklaşık 8,3 µm) ve dar damla boyut dağılımı sergiler.","Küçük damla boyutu nedeniyle çarpışma-birleşme süreci yavaş işler; yüksek albedoya sahiptir ancak sıcak yağmur üretimi gecikir."],"tanim_en":"A cloud formed in continental air characterized by a high concentration of small droplets and slow warm-rain formation.","bag":{"kavram":["ccn","carpisma","bulut-tur"],"soru":["S32"],"hesap":[]}},{"id":"droplet-size-spectrum","tr":"Damla boyut spektrumu","en":"droplet size spectrum","kisa":"","tur":"kavram","es":["damla boyutu dağılımı","drop size spectrum","damla boy spektrumu","damla boyut dağılımı","Damla spektrumu"],"tanim":["Bir bulut hacmindeki damlaların farklı çap ya da yarıçap aralıklarına göre sayısal dağılımını gösteren spektrum.","CCN spektrumu, aşırı doymuşluk ve yükselme hızı tarafından belirlenir; birimi genellikle cm⁻³ µm⁻¹ cinsinden ifade edilir.","Spektrumun genişliği ve 15–20 µm üzerindeki iri damlaların varlığı, çarpışma-birleşme sürecinin başlayıp başlamayacağını doğrudan belirler."],"tanim_en":"The distribution of droplet radii per unit volume in a cloud.","bag":{"kavram":["ccn","carpisma","difuzyon-buyume"],"soru":["S32","S46"],"hesap":[]}},{"id":"giant-ccn","tr":"Dev CCN","en":"giant cloud condensation nuclei","kisa":"GCCN","tur":"kavram","es":["iri tuz parçacıkları","giant CCN","GCCN","dev bulut yoğuşma çekirdekleri"],"tanim":["Kuru yarıçapı 1 µm'den büyük olan ve çok düşük aşırı doymuşluklarda bile hızla su buharı toplayarak etkinleşen iri aerosol parçacıkları.","Çoğunlukla deniz tuzu parçacıklarıdır; düşük aşırı doymuşlukta hemen aktive olup az sayıda iri damla (r > 20 µm) üretir.","Çarpışma-birleşme sürecinin başlaması için gereken toplayıcı damlaları üreterek sıcak bulutlarda yağışı hızlandırır; higroskopik bulut tohumlamanın temelidir."],"tanim_en":"Large hygroscopic aerosol particles with dry radii greater than one micrometer that activate at very low supersaturations to form collector drops.","bag":{"kavram":["ccn","carpisma"],"soru":["S33"],"hesap":[]}},{"id":"maritime-air","tr":"Denizel hava (deniz havası)","en":"maritime air","kisa":"","tur":"kavram","es":["denizsel hava kütlesi","maritime air mass","temiz denizel hava","temiz deniz havası","clean maritime air"],"tanim":["Deniz veya okyanus üzerinde birkaç gün kalarak özellikle alt katmanlarında yüksek nem kazanan hava kütlesi.","Düşük aerosol ve CCN derişimine sahiptir (S = %0,5 aşırı doymuşlukta aktif CCN tipik 62 cm⁻³ civarında bulunur).","Mevcut bulut sıvı suyunu az sayıda çekirdeğe bölerek iri damlalar (yarıçap ≈ 16 µm) üretir ve sıcak yağmur sürecini hızlandırır."],"tanim_en":"Air mass that has been over a maritime area for several days and therefore has a high moisture content, at least in the lower levels.","bag":{"kavram":["ccn"],"soru":["S32"],"hesap":[]}},{"id":"maritime-cloud","tr":"Deniz bulutu","en":"maritime cloud","kisa":"","tur":"kavram","es":["denizsel bulut","denizel bulut","maritime air mass cloud","okyanusal bulut","maritime cumulus","denizel kümülüs"],"tanim":["Denizel hava kütlesi içinde oluşan bulut.","Aerosol kaynağı kısıtlı olduğundan aktif yoğuşma çekirdeği (CCN) derişimi düşüktür (tipik olarak yaklaşık 10² cm⁻³, kitap S32 örneğinde 62 cm⁻³); bu nedenle damla sayısı az fakat damla yarıçapı büyüktür (R ≈ 15,7 µm).","İri damlalar sayesinde çarpışma-birleşme erken başlar ve sıcak yağmur verimli şekilde meydana gelir."],"tanim_en":"A cloud formed in maritime air characterized by low droplet concentration and large droplet size that accelerates collision-coalescence.","bag":{"kavram":["ccn","carpisma","bulut-tur"],"soru":["S32","S46"],"hesap":[]}},{"id":"sea-salt","tr":"Deniz tuzu","en":"sea salt","kisa":"NaCl","tur":"kavram","es":["deniz tuzu aerosolu","sea-salt aerosol","deniz aerosolü","marine salt","deniz tuzu parçacığı","NaCl aerosolu"],"tanim":["Deniz yüzeyinde rüzgâr ve dalga köpüklerinin patlamasıyla atmosfere karışan doğal higroskopik aerosol türü.","Büyük oranda NaCl içerir; van 't Hoff faktörü i = 2 olup kritik bağıl nem eşiği yaklaşık %75 seviyesine karşılık gelir.","İri boyutu sayesinde çok düşük aşırı doymuşluklarda kolayca aktifleşir ve denizel bulutlarda erken çarpışma–birleşmeyi başlatır."],"tanim_en":"Sea salt is a hygroscopic aerosol generated by breaking waves that acts as cloud condensation nuclei over oceans.","bag":{"kavram":["ccn","higroskopik"],"soru":["S30","S31","S33"],"hesap":[]}},{"id":"albedo","tr":"Albedo","en":"Albedo","kisa":"","tur":"olcu","es":["yansıtma gücü","bulut albedosu","yansıtırlık","reflection coefficient"],"tanim":["Bir yüzey veya bulut tarafından yansıtılan ışıma enerjisinin gelen toplam ışıma enerjisine oranı.","Boyutsuz bir büyüklüktür ve genellikle yüzde ya da 0 ile 1 arasında bir kesir olarak verilir.","Bulut fiziğinde, çok sayıda küçük damla içeren kirli kara bulutları yüksek albedoya sahip olup güneş ışımasını daha fazla yansıtır."],"tanim_en":"The fraction of incident radiant energy reflected by a surface or cloud layer.","bag":{"kavram":["ccn"],"soru":["S32"],"hesap":["kelvin"]}},{"id":"mean-droplet-spacing","tr":"Damlalar arası ortalama uzaklık","en":"mean droplet spacing","kisa":"x","tur":"olcu","es":["damla aralığı","ortalama damlacık mesafesi","damlalar arası mesafe","droplet spacing","komşu damla mesafesi","mean droplet distance"],"tanim":["Bulut hacmi içinde komşu iki su damlacığının merkezleri arasındaki ortalama mesafe.","Damla sayısı konsantrasyonu N olmak üzere x = (1/N)^(1/3) eşitliğiyle hesaplanır; kitabın örneklerinde 1–3 mm çıkar (karasal 1,33 mm, denizel 2,53 mm).","Damlalar arasındaki buhar rekabetini, yoğuşma ile büyüme hızını ve çarpışma olasılığını belirler."],"tanim_en":"Mean droplet spacing is the average distance between adjacent cloud droplets, determined from droplet number concentration.","bag":{"kavram":["ccn"],"soru":["S32"],"hesap":["kelvin"]}},{"id":"heterogeneous-nucleation","tr":"Heterojen çekirdeklenme","en":"heterogeneous nucleation","kisa":"","tur":"surec","es":["heterojen nükleasyon","parçacıklı çekirdeklenme","aerosol üzerinde yoğuşma","parçacık üstünde çekirdeklenme","aerosol çekirdeklenmesi","heterojen yoğunlaşma"],"tanim":["Yeni bir termodinamik fazın yabancı aerosol parçacıkları yüzeyinde başlaması süreci.","Higroskopik parçacıkların çözünmesi sayesinde atmosferik su buharının %0,1 ile %1 gibi çok düşük aşırı doymuşluklarda yoğunlaşmasını mümkün kılar.","Doğal bulut ve sis damlacıklarının tamamının oluşum mekanizmasını teşkil eder."],"tanim_en":"Heterogeneous nucleation is the initiation of water vapor condensation on foreign aerosol particles at low supersaturation.","bag":{"kavram":["ccn","kelvin"],"soru":["S29","S33","S40"],"hesap":[]}},{"id":"homogeneous-nucleation","tr":"Homojen çekirdeklenme","en":"homogeneous nucleation","kisa":"","tur":"surec","es":["homojen nükleasyon","kendiliğinden çekirdeklenme","homojen yoğuşma","spontaneous nucleation","parçacıksız çekirdeklenme"],"tanim":["Aerosol parçacıklarının yokluğunda, saf su buharı moleküllerinin rastgele çarpışmasıyla yeni bir faz oluşturması süreci.","Oluşan embriyonik damlacıkların eğriliği nedeniyle dengede kalabilmesi için bağıl nemin %113 ile %340 arasında olması (aşırı doymuşluk %13–240) gerekir.","Atmosferde bağıl nem nadiren %101'i aştığı için buhar yoğuşmasında bu süreç gerçekleşmez; saf damlaların yaklaşık −38 / −40 °C'de kendiliğinden donması ise homojen donmadır."],"tanim_en":"Homogeneous nucleation is the formation of liquid droplets from pure water vapor in the absence of aerosol particles.","bag":{"kavram":["ccn","kelvin"],"soru":["S29","S33"],"hesap":[]}},{"id":"nucleation","tr":"Çekirdeklenme","en":"nucleation","kisa":"","tur":"surec","es":["nükleasyon","çekirdek oluşumu","faz çekirdeklenmesi","faz dönüşümü başlangıcı","nucleation process"],"tanim":["Bir maddenin buhar fazından sıvı ya da katı faza, ya da sıvı fazdan katı faza geçişinde yeni fazın ilk kararlı embriyosunun oluşmasıdır; saf ortamda (homojen) ya da yabancı bir yüzeyde (heterojen) gerçekleşebilir.","Bulut fiziğinde su buharının yoğunlaşması için kritik aşırı doymuşluğu, su damlacıklarının donması için ise aşırı soğuma derecesini tayin eder.","Sıvı damla oluşumunda CCN, buz kristali oluşumunda ise daldırma, temas, yoğuşma-donma ve depozisyon mekanizmalarıyla buz çekirdekleri üzerinden yürür."],"tanim_en":"Nucleation is the initial transition of a substance from vapor to liquid or solid, mediated by small particles.","bag":{"kavram":["ccn","donma"],"soru":["S29","S33","S40","S46"],"hesap":[]}},{"id":"twomey-relation","tr":"CCN aktivasyon spektrumu","en":"CCN activation spectrum","kisa":"N = c S^k","tur":"yontem","es":["Twomey CCN denklemi","Twomey formülü","Twomey güç yasası","Twomey equation","Twomey kuvvet yasası","Twomey bağıntısı"],"tanim":["Aktif bulut yoğuşma çekirdeği derişimini ortamdaki aşırı doymuşluk yüzdesine bağlayan ampirik kuvvet (güç) yasası.","N = c · S^k biçiminde tanımlanır; c parametresi %1 aşırı doymuşluktaki çekirdek sayısını, k ise spektrumun eğimini gösterir.","Karasal ve denizel hava kütlelerinde aktifleşen damla derişimi ile damlalar arası ortalama uzaklığı hesaplamada kullanılır."],"tanim_en":"The CCN activation spectrum is an empirical power-law relationship expressing active cloud condensation nuclei concentration as a function of supersaturation.","bag":{"kavram":["ccn"],"soru":[],"hesap":["kelvin"]}},{"id":"dew","tr":"Çiy","en":"dew","kisa":"","tur":"kavram","es":["cig","yüzey yoğunlaşması","çiğ","çiy damlası","surface condensation"],"tanim":["Gece ışınımsal soğuma sonucu sıcaklığı çiy noktasının altına inen zemin ve nesneler üzerinde su buharının doğrudan yoğunlaşmasıyla oluşan su damlacıkları birikintisi.","Yüzey sıcaklığının 0 °C üzerinde ve havanın çiy noktası sıcaklığına eşit ya da altında olduğu açık ve durgun gecelerde meydana gelir.","Havada asılı sis oluşturmaksızın yalnızca soğuk zemin yüzeyinde sıvı birikimi sağlayan bir hidrometeordur."],"tanim_en":"Dew is a deposit of water droplets formed by nocturnal radiative cooling when ground temperatures drop below the dew point.","bag":{"kavram":["ciy-don"],"soru":["S3","S14","S19","S22"],"hesap":["theta","kaldir-z","theta-e","lcl-lfc"]}},{"id":"frost","tr":"Kırağı","en":"frost","kisa":"","tur":"kavram","es":["hoarfrost","beyaz don","kiragi","hoar frost"],"tanim":["Soğuk yüzeylerde su buharının doğrudan buza geçmesiyle (depozisyon) oluşan buz kaplamasıdır.","Yüzey sıcaklığı don noktası T_f'nin ve 0 °C'nin altına inince oluşur; T_f, e ve e₀ ile L_d üzerinden hesaplanır (L_d/ℜᵥ = 6139 K).","Kitapta çiy ile karşılaştırılır: çiy sıvı damladır, kırağı buzdur; 0 °C altında T_f > T_d olur."],"tanim_en":"Frost (hoarfrost) is a deposit of ice crystals formed by deposition of water vapor directly onto surfaces colder than 0 °C.","bag":{"kavram":["ciy-don"],"soru":["S22","S46"],"hesap":["ciy-don"]}},{"id":"frozen-dew","tr":"Donmuş çiy","en":"frozen dew","kisa":"","tur":"kavram","es":["donmuş çiğ"],"tanim":["Önce yoğuşarak oluşmuş çiy damlalarının sonradan 0 °C altına inen yüzeyde donmasıyla oluşan buzdur.","Kırağıdan ayrımı oluşum sırasındadır: yüzey önce çiğ noktasına iner (sıvı damla), sonra donma sıcaklığına iner.","Kitapta kırağı (hoarfrost) ile karşılaştırmak için kullanılır; buzun yapısı damla biçimini korur."],"tanim_en":"Frozen dew is ice formed when dew droplets that have already condensed on a surface freeze as the surface cools below 0 degrees Celsius.","bag":{"kavram":["ciy-don","donma"],"soru":["S22"],"hesap":[]}},{"id":"dew-point-depression","tr":"Çiğ noktası açığı","en":"dew-point depression","kisa":"T - T_d","tur":"olcu","es":["çiğleşme açığı","çiğ açığı","sıcaklık-çiğ noktası farkı","dew point spread","çiğ noktası farkı","dew-point spread"],"tanim":["Hava sıcaklığı T ile çiğ noktası T_d arasındaki fark T − T_d'dir.","Birimi K (ya da °C farkı) olup sıfır olması havanın doyduğunu gösterir; radyosonde ya da yüzey ölçümünden hesaplanır.","Kitapta LCL yüksekliğini veren z_LCL ≈ 0,125 km/K × (T − T_d) bağıntısında ve sis oluşum süresi hesabında kullanılır."],"tanim_en":"Dew-point depression is the difference between the air temperature and the dew-point temperature.","bag":{"kavram":["ciy-don","lcl-lfc","sis"],"soru":["S8","S14","S16","S19"],"hesap":["kaldir-z"]}},{"id":"deposition-process","tr":"Depozisyon","en":"deposition","kisa":"","tur":"surec","es":["buhar birikimi","vapor deposition","buhardan buza geçiş"],"tanim":["Su buharının sıvı evreden geçmeden doğrudan buza dönüşmesidir.","Açığa çıkan gizli ısı L_d ≈ 2,83×10⁶ J/kg'dır (L_d/ℜᵥ = 6139 K); bu değer Lᵥ ≈ 2,5×10⁶ J/kg'dan büyüktür.","Kitapta kırağı oluşumunda ve buz kristalinin difüzyonla büyümesinde temel süreçtir."],"tanim_en":"Deposition is the phase change of water vapor directly to ice without passing through the liquid phase.","bag":{"kavram":["ciy-don","buz-kutle","bergeron"],"soru":["S19","S22","S39","S40"],"hesap":[]}},{"id":"mean-free-path","tr":"Ortalama serbest yol","en":"mean free path","kisa":"λ","tur":"olcu","es":["moleküler serbest yol","serbest yol","lambda free path","molecular mean free path"],"tanim":["Gaz fazındaki bir molekülün ardışık iki çarpışma arasında katettiği ortalama mesafedir.","Kinetik teoriye göre ortam basıncıyla ters orantılıdır; basınç düştükçe moleküler çarpışmalar seyrekleşir ve serbest yol uzar.","Su buharının havadaki difüzivitesini belirler; yüksek irtifada serbest yolun uzaması buhar difüzyonunu hızlandırır."],"tanim_en":"The average distance traveled by a gas molecule between successive collisions with other particles.","bag":{"kavram":["difuzivite"],"soru":["S34"],"hesap":["difuzivite"]}},{"id":"vapor-density-difference","tr":"Buhar yoğunluğu farkı","en":"vapor density difference","kisa":"Δρᵥ","tur":"olcu","es":["yoğunluk farkı","delta rho_v","su buharı yoğunluk farkı","ambient-to-surface vapor density difference","buhar yoğunluk farkı","Δρᵥ"],"tanim":["Uzak çevre ortamındaki su buharı yoğunluğu ile bulut damlacığının veya buz kristalinin yüzeyindeki doygun buhar yoğunluğu arasındaki farktır.","SI birimi kg m⁻³ olup aşırı doymuşlukla doğrudan bağlantılıdır (Δρᵥ ≈ S eₛ / (ℜᵥ T)).","Fick yasası uyarınca damlaya doğru yönelen buhar difüzyon akısının ve R² büyüme hızının temel termodinamik itici gücüdür."],"tanim_en":"The difference between the ambient water vapor density and the saturation vapor density at the droplet surface, which drives vapor diffusion.","bag":{"kavram":["difuzivite","difuzyon-buyume","nem-akisi"],"soru":["S5","S34","S36"],"hesap":["dif-buyume"]}},{"id":"vapor-diffusion","tr":"Difüzyon (su buharı)","en":"diffusion (of water vapor)","kisa":"","tur":"surec","es":["difuzyon","vapor diffusion","buhar difüzyonu","difüzyon","su buharı yayınımı","water vapor diffusion"],"tanim":["Su buharının yoğunluk farkı (Δρᵥ) yönünde, yani yoğun bölgeden seyrek bölgeye moleküler hareketle taşınmasıdır.","Hız D difüzivitesine bağlıdır (D ≈ 2×10⁻⁵ m²/s mertebesinde) ve basınç ile sıcaklıkla değişir.","Kitapta damla ve kristalin büyümesini sağlar; damlada R² ∝ t olduğu için büyüme zamanla yavaşlar."],"tanim_en":"Diffusion of water vapor is the molecular transport of water vapor down a vapor density gradient toward a growing droplet or crystal.","bag":{"kavram":["difuzivite","difuzyon-buyume","buz-kutle"],"soru":["S35","S36","S37","S39","S42","S46"],"hesap":["dif-buyume"]}},{"id":"drizzle-drop","tr":"Çisenti damlası","en":"drizzle","kisa":"","tur":"kavram","es":["çisenti damlacığı","drizzle droplet","çiseleme damlası","küçük damlalı yağış","drizzle drop"],"tanim":["Çapı 0,5 mm'den küçük, çisenti yağışını oluşturan ince su damlasıdır.","Tipik 100 µm yarıçapındaki bir çisenti damlası ara rejimde yaklaşık 0,8 m s⁻¹ limit düşme hızına sahiptir.","Stratus gibi sığ bulutlarda zayıf yukarı hava akımı altında difüzyon ve çarpışma ile büyüyerek yere ulaşır."],"tanim_en":"A fine water drop, less than 0.5 mm in diameter, that falls as drizzle.","bag":{"kavram":["difuzyon-buyume","yagis-surec","limit-hiz"],"soru":["S36","S41"],"hesap":[]}},{"id":"saturation-vapor-density","tr":"Doyma buhar yoğunluğu","en":"saturation vapor density","kisa":"ρᵥₛ","tur":"olcu","es":["saturation vapor concentration","doygun buhar yoğunluğu","rho_vs","ρᵥₛ","doyma buhar derişimi"],"tanim":["Belirli bir sıcaklıkta düz bir su veya buz yüzeyi ile termodinamik dengede bulunan doymuş havadaki su buharı kütlesinin birim hacme oranıdır.","SI birimi kg m⁻³ olup ideal gaz durum denkleminden ρᵥₛ = eₛ / (ℜᵥ T) şeklinde hesaplanır ve sıcaklıkla üstel olarak artar.","Bulut damlalarının ve buz kristallerinin yüzey sınır koşulunu oluşturarak difüzyonel büyümede buhar akısını sınırlar."],"tanim_en":"The maximum mass of water vapor that can occupy a unit volume of air in thermodynamic equilibrium over a plane surface of liquid water or ice at a given temperature.","bag":{"kavram":["difuzyon-buyume","es-cc"],"soru":["S36"],"hesap":["dif-buyume"]}},{"id":"latent-heat-release","tr":"Gizli ısı salımı","en":"latent heat release","kisa":"","tur":"surec","es":["yoğuşma ısısı açığa çıkması","latent heating","gizli ısınma","yoğuşma gizli ısısı salımı"],"tanim":["Su buharının sıvı suya yoğuşması veya doğrudan buza depozisyonu sırasında çevre havaya termal enerji aktarılması sürecidir.","Yoğuşan her bir kilogram su buharı için çevreye yaklaşık 2,5×10⁶ J enerji aktarılır; bu durum yükselen doymuş havanın kuru adyabatik orana kıyasla daha yavaş soğumasını sağlar (Γs < Γd).","Föhn ısınmasına güç verir, konvektif fırtınalarda kaldırma kuvvetini besler ve difüzyonla damla büyümesinde damlayı ısıtarak büyümeyi yavaşlatıcı bir geri besleme üretir."],"tanim_en":"The liberation of thermal energy into the surrounding air during condensation of water vapor or deposition into ice.","bag":{"kavram":["difuzyon-buyume"],"soru":["S4","S16","S36"],"hesap":[]}},{"id":"aircraft-icing","tr":"Uçakta buzlanma","en":"aircraft icing","kisa":"","tur":"kavram","es":["uçak buzlanması","aviation icing","gövde buzlanması","in-flight icing"],"tanim":["Bir hava taşıtı yüzeyinde buz, kırağı veya donmuş tanecik tabakasının birikmesi olayıdır.","Bulut içindeki aşırı soğumuş sıvı su damlacıklarının uçağın gövde, kanat ve motor girişlerine çarparak donmasıyla meydana gelir.","Yaklaşık 0 °C ile −20 °C arasındaki karma ve sıvı fazlı bulutlarda şiddetlenir; aerodinamik kaldırmayı düşürüp sürüklenmeyi artırarak uçuş emniyetini tehdit eder."],"tanim_en":"Formation of ice, rime or hoar frost on an aircraft.","bag":{"kavram":["donma"],"soru":["S38"],"hesap":[]}},{"id":"cold-cloud","tr":"Soğuk bulut","en":"cold cloud","kisa":"","tur":"kavram","es":["buzlu bulut","karma fazlı bulut","cold clouds","soğuk tabanlı bulut"],"tanim":["Tepe sıcaklığı veya tamamı 0 °C altında bulunan ve buz kristali ya da aşırı soğumuş su damlacıkları içeren bulut.","0 °C ile yaklaşık −40 °C arasında aşırı soğumuş su ve buz bir arada bulunurken, yaklaşık −40 °C altında tamamen buz kristallerinden meydana gelir.","Yağış oluşumunda difüzyonun yavaş kaldığı sıcak bulutların aksine, Bergeron süreci ve kırağılanma ile hızlı parçacık büyümesi gerçekleşir."],"tanim_en":"A cloud with temperature below 0 °C that contains ice crystals or supercooled liquid droplets.","bag":{"kavram":["donma","yagis-surec","bergeron"],"soru":["S33","S40","S46"],"hesap":[]}},{"id":"ice-nucleus","tr":"Buz çekirdeği","en":"ice nucleating particle","kisa":"IN","tur":"kavram","es":["INP","buzlaşma çekirdeği","ice nucleus","ice nuclei","IN"],"tanim":["Aşırı soğumuş su damlacıklarının donmasını ya da su buharının doğrudan buz olarak birikmesini (depozisyon) başlatan aerosol parçacığı.","Atmosferde konsantrasyonu çok düşüktür; bu parçacıklar olmadan saf su damlaları homojen donma sınırı olan yaklaşık −38 °C ile −40 °C civarına kadar sıvı kalır.","Karma fazlı bulutlarda Bergeron sürecini ve soğuk yağmur mekanizmasını başlatmada belirleyici rol oynar."],"tanim_en":"An aerosol particle that catalyzes the formation of ice crystals from supercooled liquid water or water vapor.","bag":{"kavram":["donma"],"soru":["S38","S40"],"hesap":[]}},{"id":"silver-iodide","tr":"Gümüş iyodür","en":"silver iodide","kisa":"AgI","tur":"kavram","es":["AgI parçacığı","buz çekirdeği yapay","AgI","gümüş iyodür bileşiği","buz tohumlama ajanı","yapay buz çekirdeği"],"tanim":["Kristal örgü yapısı buza çok benzediği için etkin bir yapay buz çekirdeği görevi gören inorganik bileşik.","Yaklaşık −5 °C ile −10 °C gibi ılık sıcaklıklarda heterojen buz çekirdeklenmesini başlatarak damlaların donmasını sağlar.","Soğuk bulut tohumlamasında aşırı soğumuş damlaları hızla buza çevirip Bergeron sürecini tetiklemek amacıyla kullanılır."],"tanim_en":"An inorganic compound with a hexagonal crystal lattice resembling ice that serves as an effective ice nucleating agent in cloud seeding.","bag":{"kavram":["donma","bergeron"],"soru":["S33","S40"],"hesap":[]}},{"id":"supercooled-water","tr":"Aşırı soğumuş su","en":"supercooled water","kisa":"SLW","tur":"kavram","es":["aşırı soğumuş su damlacıkları","supercooled droplets","aşırı soğuk su","aşırı soğumuş sıvı","süper-soğumuş sıvı","metastable water"],"tanim":["Donma noktasının altına soğutulduğu hâlde katılaşmamış sıvı sudur.","Saf su damlaları kendiliğinden (homojen) ≈ −40 °C'de donar; bu yüzden 0 ile ≈ −40 °C arasında sıvı damlalar bulutta bulunabilir.","Buz çekirdekleri seyrek olduğu için (−20 °C'de litrede ~1) yaygındır; Bergeron sürecinde kristaller bu damlaların buharlaşması pahasına büyür."],"tanim_en":"Supercooled water is liquid water cooled below its freezing point without solidification or crystallization.","bag":{"kavram":["donma","ciy-don","es-cc"],"soru":["S37","S38","S40","S46"],"hesap":[]}},{"id":"free-energy-barrier","tr":"Serbest enerji bariyeri","en":"free energy barrier","kisa":"ΔG*","tur":"olcu","es":["aktivasyon enerjisi bariyeri","nucleation barrier","nükleasyon bariyeri","serbest entalpi engeli"],"tanim":["Bir yeni faz embriyosunun kararlı büyüme aşamasına geçebilmesi için aşması gereken Gibbs serbest enerjisi eşiği.","Joule cinsinden ifade edilir; kritik yarıçapta yüzey gerilimi maliyeti ile hacimsel serbest enerji kazancının dengelendiği tepe enerji değeridir.","Homojen çekirdeklenmede bu bariyer çok yüksektir; yabancı aerosol parçacıkları ve buz çekirdekleri yüzey sağlayarak serbest enerji bariyerini belirgin biçimde düşürür."],"tanim_en":"The thermodynamic Gibbs free energy threshold that a molecular cluster must overcome to form a stable embryo.","bag":{"kavram":["donma"],"soru":["S40"],"hesap":["donma"]}},{"id":"condensation-freezing","tr":"Yoğuşma-donma","en":"condensation-freezing","kisa":"","tur":"surec","es":["yoğuşarak donma","yoğuşma ardından donma","Yoğuşma-donma çekirdeklenmesi","condensation-freezing nucleation","yoğuşma ve donma"],"tanim":["Su buharının bir buz çekirdeği üzerinde önce sıvı su olarak yoğuşması ve ardından derhal donarak buz kristaline dönüşmesi süreci.","Heterojen buz çekirdeklenmesinin dört temel yolundan biridir; suya göre aşırı doymuş ve 0 °C altındaki ortamlarda gerçekleşir.","Karma fazlı bulutlarda buz parçacıklarının oluşumunu hızlandırarak Bergeron sürecinin başlamasına katkı sağlar."],"tanim_en":"A heterogeneous ice nucleation mode where water vapor transforms into liquid on a nucleus and immediately freezes.","bag":{"kavram":["donma"],"soru":["S40"],"hesap":[]}},{"id":"contact-nucleation","tr":"Temas çekirdeklenmesi","en":"contact nucleation","kisa":"","tur":"surec","es":["temasla donma","contact freezing","temasla çekirdeklenme","Temas donması","temas çekirdeklenmesi modu"],"tanim":["Havada serbest dolaşan bir buz çekirdeğinin aşırı soğumuş bir su damlasının dış yüzeyine çarpmasıyla donmayı başlatan heterojen çekirdeklenme mekanizması.","Heterojen buz çekirdeklenmesinin dört temel yolundan biridir ve damla yüzeyinde serbest enerji bariyerinin aşılmasını sağlar.","Etkinliği çekirdeğin damlaya ulaşıp çarpma olasılığına, dolayısıyla damla ve parçacık sayısına bağlıdır."],"tanim_en":"A heterogeneous ice nucleation mode initiated when an airborne ice nucleus collides with the boundary of a supercooled droplet.","bag":{"kavram":["donma"],"soru":["S40"],"hesap":[]}},{"id":"deposition-nucleation","tr":"Depozisyon çekirdeklenmesi","en":"deposition nucleation","kisa":"","tur":"surec","es":["buhardan doğrudan buza geçiş","vapor deposition","buhardan doğrudan donma","depozisyon yolu","buhar depozisyonu","depozisyonla nükleasyon"],"tanim":["Su buharının sıvı faza uğramadan doğrudan bir buz çekirdeği yüzeyi üzerinde buz kristaline dönüşmesi süreci.","Heterojen buz çekirdeklenmesinin dört yolundan biridir; buza göre aşırı doymuş fakat genellikle suya göre doymamış ortamlarda gerçekleşir.","Soğuk üst troposferde ve sirüs bulutlarında buz kristallerinin ilk oluşumunda temel mekanizmalardan biridir."],"tanim_en":"A heterogeneous ice nucleation mode in which water vapor deposits directly from the vapor state onto an ice nucleus as ice.","bag":{"kavram":["donma","buz-kutle"],"soru":[],"hesap":[]}},{"id":"freezing","tr":"Donma","en":"freezing","kisa":"","tur":"surec","es":["sıvının donması","katılaşma","drop freezing"],"tanim":["Sıvı suyun buza dönüşmesidir.","Saf su damlaları kendiliğinden (homojen) ≈ −38 / −40 °C'de donar; içinde buz çekirdeği bulunan damlalar daha ılık sıcaklıkta (heterojen, içten donma) donar ve büyük damla daha ılıkta donar.","Kitapta içten (immersion) donma T ≈ T₁ + T₂ ln(R/R₀) bağıntısıyla damla yarıçapına bağlanır (T₁ = 235 K, T₂ = 3 K, R₀ = 5 µm): 100 µm → ≈ −29 °C, 1 mm → ≈ −22 °C."],"tanim_en":"Freezing is the change of liquid water to ice, and for small pure droplets it occurs spontaneously near −40 degrees Celsius.","bag":{"kavram":["donma","ciy-don"],"soru":["S16","S22","S37","S38","S40","S46"],"hesap":["donma"]}},{"id":"heterogeneous-ice-nucleation","tr":"Heterojen buz çekirdeklenmesi","en":"heterogeneous ice nucleation","kisa":"","tur":"surec","es":["heterojen donma","heterojen buz oluşumu"],"tanim":["Su moleküllerinin yabancı bir parçacık (buz çekirdeği) yüzeyinde buz kristali yapısına geçerek faz dönüşümünü başlatması süreci.","Depozisyon, yoğuşma-donma, daldırma ve temas olmak üzere dört ana modda gerçekleşir; serbest enerji bariyerini düşürerek 0 °C ile −38 °C arasında donmayı mümkün kılar.","Saf suyun homojen donması için gereken −40 °C civarındaki aşırı soğuma koşuluna gerek kalmadan bulutlarda buz fazını başlatır."],"tanim_en":"The formation of ice crystals from liquid water or vapor facilitated by foreign aerosol particles acting as ice nuclei.","bag":{"kavram":["donma"],"soru":["S29","S33","S40"],"hesap":[]}},{"id":"homogeneous-freezing","tr":"Homojen donma","en":"homogeneous freezing","kisa":"","tur":"surec","es":["kendiliğinden donma","homojen buz çekirdeklenmesi","homojen donma eşiği","homojen çekirdeklenme sınırı","spontaneous freezing"],"tanim":["Donma çekirdekleri veya yabancı parçacıklar bulunmaksızın, saf sıvı su moleküllerinin kendiliğinden buz kristali oluşturması süreci.","Saf bulut damlacıkları yaklaşık −38 °C ile −40 °C'ye soğuduğunda kendiliğinden donar; sirüs ve Cb örsü gibi çok soğuk bulutlarda buzun bir bölümü bu yolla oluşur.","Homojen donma sınırı, karma fazlı bulutların alt sınırını ve uçak buzlanması riskinin sona erdiği sıcaklık eşiğini belirler."],"tanim_en":"Freezing that occurs spontaneously in liquid water in the absence of freezing nuclei.","bag":{"kavram":["donma"],"soru":["S29","S33","S38","S40"],"hesap":[]}},{"id":"immersion-freezing","tr":"İçten donma","en":"immersion freezing","kisa":"","tur":"surec","es":["daldırma donma","içten immersion donma","immersion-mode freezing","damla içi çekirdeklenme","immersion çekirdeklenme","içten donma"],"tanim":["Aşırı soğumuş bir damlacık içine önceden gömülmüş katı bir buz çekirdeğinin etkisiyle başlayan heterojen donma sürecidir.","Donma sıcaklığı damla yarıçapına bağlıdır ve T ≈ T₁ + T₂ ln(R/R₀) bağıntısıyla ifade edilir; burada T₁ = 235 K, T₂ = 3 K ve R₀ = 5 µm alınır.","Karma fazlı bulutlarda heterojen buz oluşumunu başlatıp damlaların homojen donma sınırı olan −38 °C'den daha ılık sıcaklıklarda buza dönüşmesini sağlar."],"tanim_en":"Heterogeneous ice nucleation mode in which an insoluble ice-nucleating particle immersed within a supercooled droplet triggers freezing.","bag":{"kavram":["donma"],"soru":["S38","S40"],"hesap":[]}},{"id":"glaciogenic-cloud-seeding","tr":"Glasiyojenik bulut tohumlama","en":"glaciogenic cloud seeding","kisa":"","tur":"yontem","es":["soğuk bulut tohumlama","cold cloud seeding","AgI tohumlama","soğuk bulut tohumlaması","gümüş iyodür tohumlaması","silver iodide seeding"],"tanim":["Aşırı soğumuş su damlacıkları içeren soğuk bulutlara yapay buz çekirdekleri ekleyerek buz kristali oluşumunu ve Bergeron sürecini başlatma yöntemidir.","Kristal yapısı buza benzeyen gümüş iyodür (AgI) gibi maddeler −5 ile −10 °C sıcaklık aralığında etkin buz çekirdeği olarak görev yapar.","Doğal buz çekirdeği yetersiz olan karma fazlı bulutlarda çökelmeyi erkenden başlatmayı veya aşırı dolu büyümesini engellemeyi hedefler."],"tanim_en":"The introduction of artificial ice-nucleating agents such as silver iodide into supercooled clouds to trigger ice crystal formation and precipitation.","bag":{"kavram":["donma","yagis-surec"],"soru":["S33","S40"],"hesap":["damla-boyu"]}},{"id":"supersaturation","tr":"Aşırı doymuşluk","en":"supersaturation","kisa":"S","tur":"kavram","es":["aşırı doygunluk","su buharı aşırı doymuşluğu","süpersatürasyon","bağıl aşırı doymuşluk","supersaturation S"],"tanim":["Havadaki buhar basıncının doyma buhar basıncını aştığı durumdur; kitapta S = e/eₛ − 1 (genellikle yüzde olarak) alınır.","Bulutlarda aşırı doymuşluk genellikle %1'in altındadır (çoğu kez %0,1–0,5); homojen yoğuşma için yüzlerce yüzde gerekir.","Köhler eğrisinde kritik aşırı doymuşluk S* damlanın aktive olacağı eşiği belirler; difüzyonla büyümede Δρᵥ ≈ S ρᵥₛ itici güçtür."],"tanim_en":"Supersaturation is the amount by which the relative humidity exceeds 100 percent, expressed as the excess of the vapor pressure over the saturation vapor pressure.","bag":{"kavram":["es-cc","karisma","kritik"],"soru":["S28","S31","S32","S33","S35","S37"],"hesap":["kelvin","kohler","ccn","damla-boyu"]}},{"id":"absolute-humidity","tr":"Mutlak nem","en":"absolute humidity","kisa":"ρᵥ","tur":"olcu","es":["su buharı yoğunluğu","buhar yoğunluğu","water vapor density","rhov","çevre buhar yoğunluğu","vapor density"],"tanim":["Birim nemli hava hacmindeki su buharı kütlesidir.","Birimi kg/m³'tür; kitapta ρᵥ = e/(ℜᵥT) ile hesaplanır (e Pa cinsinden).","Kitapta difüzyonla büyümede itici güç Δρᵥ ≈ S ρᵥₛ ve buz kristali kütlesi formüllerinde kullanılır."],"tanim_en":"Absolute humidity is the mass of water vapor contained in a unit volume of moist air.","bag":{"kavram":["es-cc","difuzivite","buz-kutle"],"soru":["S19","S34","S36","S39"],"hesap":["buz-kutle"]}},{"id":"latent-heat-of-sublimation","tr":"Süblimleşme gizli ısısı","en":"latent heat of sublimation","kisa":"L_d","tur":"olcu","es":["süblimleşme ısısı","Ls","L_d","depozisyon gizli ısısı","latent heat of deposition","Ld"],"tanim":["Birim kütle buzun buhara (ya da tersine) dönüşmesinde soğurulan ya da açığa çıkan ısıdır.","Kitapta L_d ≈ 2,83×10⁶ J/kg'dır (L_d/ℜᵥ = 6139 K); Lᵥ ≈ 2,5×10⁶ J/kg'dan L_d − Lᵥ ≈ 3,3×10⁵ J/kg (donma ısısı) kadar büyüktür.","Buz üstü doyma basıncının ve don noktası T_f'nin hesabında L yerine kullanılır."],"tanim_en":"The latent heat of sublimation is the heat absorbed when a unit mass of ice changes to water vapor, or released in the reverse change.","bag":{"kavram":["es-cc","ciy-don","buz-kutle"],"soru":["S22"],"hesap":["theta"]}},{"id":"saturation-mixing-ratio","tr":"Doyma karışma oranı","en":"saturation mixing ratio","kisa":"rₛ","tur":"olcu","es":["doygunluk karisma orani","rs","doygunluk karışma oranı","doymuş karışma oranı","doygun karışma oranı","saturation humidity mixing ratio"],"tanim":["Belirli bir sıcaklık ve basınçta doymuş havadaki su buharı kütlesinin kuru hava kütlesine oranıdır.","Birimi kg/kg veya g/kg olup atmosferde tipik değerleri 0,001–0,03 kg/kg aralığında değişir.","Sıcaklıkla üstel artar; nemli adyabatik azalma oranı Γs ve eşdeğer potansiyel sıcaklık θe formüllerinde temel değişkendir."],"tanim_en":"The ratio of the mass of water vapor to the mass of dry air in an air parcel saturated with water vapor at a given temperature and pressure.","bag":{"kavram":["es-cc","theta-e","gamma-s"],"soru":["S2","S4","S35"],"hesap":["damla-boyu","nem-akisi"]}},{"id":"saturation-vapor-pressure-ice","tr":"Buza göre doyma buhar basıncı","en":"saturation vapor pressure over ice","kisa":"eₛ,buz","tur":"olcu","es":["buza gore doyma buhar basinci","buz üzeri doygunluk basıncı","e_s,ice","buz üzerinde doyma buhar basıncı","buza göre doyma basıncı","e_si"],"tanim":["Düz bir buz yüzeyi ile dengede bulunan su buharının belirli bir sıcaklıktaki kısmi basıncıdır.","0 °C altında süblimleşme gizli ısısı buharlaşmadan büyük olduğu için su üzerindeki değerden düşüktür; −14 °C'de yaklaşık 0,181 kPa'dır (su üzerinde 0,209 kPa).","Karma fazlı bulutlarda Bergeron sürecini yürütür ve don noktasının çiğ noktasından yüksek çıkmasını sağlar."],"tanim_en":"The partial pressure exerted by water vapor in thermodynamic equilibrium over flat ice at a given temperature.","bag":{"kavram":["es-cc","bergeron","ciy-don"],"soru":["S22","S37"],"hesap":["theta"]}},{"id":"saturation-vapor-pressure-water","tr":"Su üzerinde doyma buhar basıncı","en":"saturation vapor pressure over liquid water","kisa":"eₛ,su","tur":"olcu","es":["su üzeri doygunluk basıncı","e_s,water","suya göre doyma basıncı","e_s(T)","saturation vapor pressure over water","es,su"],"tanim":["Saf ve düz bir sıvı su yüzeyi ile termodinamik dengede bulunan su buharının kısmi basıncıdır.","0 °C sıcaklıkta 0,611 kPa, 20 °C sıcaklıkta yaklaşık 2,37 kPa olup sıcaklık arttıkça üstel olarak yükselir.","Bulut damlacıklarının yoğuşma yoluyla oluşumunda, bağıl nem hesabında ve çiğ noktası sıcaklığının belirlenmesinde temel alınır."],"tanim_en":"The partial pressure exerted by water vapor in thermodynamic equilibrium with a flat liquid water layer at a given temperature.","bag":{"kavram":["es-cc","ciy-don","bergeron"],"soru":["S20","S21","S22","S26","S37"],"hesap":["ciy-don","bergeron"]}},{"id":"vapor-pressure","tr":"Buhar basıncı","en":"vapor pressure","kisa":"e","tur":"olcu","es":["su buhari basinci","partial vapor pressure","su buharı basıncı","water vapor pressure","kısmi buhar basıncı","aktüel buhar basıncı"],"tanim":["Atmosferdeki su buharı moleküllerinin uyguladığı kısmi basınçtır.","Birimi kilopaskal (kPa) veya hektopaskal (hPa) olup çiğ noktasındaki su üzeri doyma buhar basıncına eşittir.","Bağıl nemin hesaplanmasında, buharlaşma hızında ve tuz parçacıklarının nem çekerek eriyik haline geçişinde doğrudan belirleyicidir."],"tanim_en":"The partial pressure exerted by water vapor molecules in a volume of moist air.","bag":{"kavram":["es-cc","tv","lcl-lfc"],"soru":["S3","S22","S24","S27","S33","S37"],"hesap":["theta","kaldir-z","theta-e","karisma"]}},{"id":"saturation","tr":"Doyma","en":"Saturation","kisa":"","tur":"surec","es":["doygunluk","atmospheric saturation","doymuş hal","doymus hava","doygun hava","saturated atmosphere"],"tanim":["Nemli havanın belirli bir sıcaklık ve basınçta düz saf su veya buz yüzeyi ile buharlaşma-yoğuşma dengesine ulaştığı termodinamik durumdur.","Havadaki aktüel buhar basıncının doyma buhar basıncına eşitlenmesiyle gerçekleşir ve bağıl nem %100 değerine ulaşır.","Atmosferde adyabatik yükselme ile soğuma, çevreye buhar ekleme ya da farklı sıcaklıktaki iki hava kütlesinin karışması sonucu ortaya çıkar."],"tanim_en":"The thermodynamic state in which moist air is in equilibrium with flat liquid water or ice at a given temperature and pressure.","bag":{"kavram":["es-cc","karisma"],"soru":["S3","S4","S6","S20","S21","S37"],"hesap":["kaldir-z","theta-e","karisma","ciy-don"]}},{"id":"sublimation","tr":"Süblimleşme","en":"sublimation","kisa":"","tur":"surec","es":["katıdan gaza geçiş","buzun buharlaşması","süblimasyon","buharlaşma (buzdan)","sublimation process","phase transition solid-gas"],"tanim":["Maddenin sıvı faza uğramadan doğrudan katı fazdan gaz fazına geçişidir.","Meteoroloji sözlüklerinde geçmişte gazdan katıya geçişi de kapsayacak biçimde tanımlanmış olsa da kitapta katıdan gaza geçiş için kullanılır; tersi depozisyon adını alır.","Süblimleşme gizli ısısı L_d yaklaşık 2,83×10⁶ J/kg olup buz kristallerinin ve kar tanelerinin doymamış havada yok olmasını açıklar."],"tanim_en":"The transition of a substance directly from the solid to the vapor phase without passing through the liquid phase.","bag":{"kavram":["es-cc","ciy-don","buz-kutle"],"soru":["S22","S37","S40"],"hesap":[]}},{"id":"chinook","tr":"Chinook rüzgârı","en":"chinook wind","kisa":"","tur":"kavram","es":["chinook","Kaya Dağları föhnü","chinook ruzgari","Rocky mountain foehn","snow eater"],"tanim":["Kuzey Amerika'da Kayalık Dağlar'ın doğu yamaçlarında esen sıcak ve çok kuru bir föhn türü rüzgârdır.","Dağın rüzgârüstü yamacında yoğuşma gizli ısısını bırakan havanın rüzgâraltı yamaçta kuru adyabatik olarak (yaklaşık 9,8 K/km) hızla ısınmasıyla meydana gelir.","Kışın karları çok hızlı eritmesi ve ani sıcaklık artışları üretmesiyle bilinir."],"tanim_en":"A warm and dry wind of foehn type blowing on the eastern side of the Rocky Mountains.","bag":{"kavram":["fohn"],"soru":["S16"],"hesap":[]}},{"id":"leeward-slope","tr":"Rüzgâraltı yamaç","en":"leeward slope","kisa":"","tur":"kavram","es":["rüzgâraltı","lee side","leeward","rüzgâraltı tarafı","leeward side"],"tanim":["Bir tepe, dağ ya da dağ sırasının rüzgâr akışının gittiği yöne bakan, rüzgârdan korunaklı yamacıdır.","Dağı aşan hava kütlesi bu yamaç boyunca çökerken kuru adyabatik olarak ısınır ve bağıl nem hızla düşer.","Föhn etkisi nedeniyle bulutsuzluk, yüksek sıcaklık, kuraklık ve yağmur gölgesi alanı oluşturur."],"tanim_en":"The slope of a hill or mountain facing away from the incoming wind where descending air warms adiabatically.","bag":{"kavram":["fohn"],"soru":["S16","S17"],"hesap":[]}},{"id":"mountain-wave","tr":"Dağ dalgası","en":"mountain wave","kisa":"","tur":"kavram","es":["lee wave","yerçekimi dalgası","gravity wave","dağ dalgaları","orografik dalga","mountain lee wave"],"tanim":["Kararlı hava akımının bir dağ engelini aşarken rüzgâraltı tarafta düşey salınımlar yapmasıyla oluşan duran yerçekimi dalgasıdır.","Havanın statik denge seviyesinden yukarı ötelenmesi durumunda kararlı tabakalaşma nedeniyle dengeye dönme eğiliminden kaynaklanır.","Dalga tepelerinde adyabatik soğumayla mercek bulutları oluşur; altındaki rotor alanları havacılıkta şiddetli türbülans riski taşır."],"tanim_en":"An atmospheric gravity wave in a stable air stream to the lee of a mountain barrier.","bag":{"kavram":["fohn"],"soru":["S17"],"hesap":[]}},{"id":"windward-slope","tr":"Rüzgârüstü yamaç","en":"windward slope","kisa":"","tur":"kavram","es":["rüzgârüstü","windward side","windward","rüzgârüstü tarafı","windward face"],"tanim":["Bir tepenin, dağın veya coğrafi yükseltinin rüzgârın geldiği yöne bakan yamacıdır.","Zorlanmış orografik yükselme nedeniyle hava kütlesi LCL seviyesine kadar kuru adyabatik, doyduktan sonra nemli adyabatik olarak soğur.","Su buharının yoğuşmasıyla yoğun bulut ve yağış üretir; orografik yağışların ve gür bitki örtüsünün yoğunlaştığı bölgedir."],"tanim_en":"The side of a hill or mountain facing into the wind where forced orographic lifting leads to cloud formation and precipitation.","bag":{"kavram":["fohn"],"soru":["S11","S16"],"hesap":[]}},{"id":"moist-adiabat","tr":"Nemli adyabat","en":"moist adiabat","kisa":"","tur":"kavram","es":["doymus adyabat","saturated adiabat","doymuş adyabat","moist adiabatic curve"],"tanim":["Doymuş bir hava parselinin adyabatik olarak yükselirken veya alçalırken izlediği sıcaklık-basınç eğrisi.","Yoğuşmayla açığa çıkan gizli ısı soğumayı yavaşlattığı için eğimi kuru adyabattan küçüktür; tipik azalma oranı Γs ≈ 4–7 K/km mertebesinde kalır.","Termodinamik diyagramlarda LCL seviyesinin üzerinde parsel durumunu izlemek ve kararlılık çözümlemesi yapmak için kullanılır; eşdeğer potansiyel sıcaklık (θe) bu eğri boyunca korunur."],"tanim_en":"A line on a thermodynamic diagram that shows the temperature change of a saturated air parcel undergoing reversible or pseudoadiabatic ascent.","bag":{"kavram":["gamma-s"],"soru":["S3","S6","S7","S9","S16"],"hesap":["gamma","lcl-lfc","fohn"]}},{"id":"latent-heat","tr":"Gizli ısı","en":"latent heat","kisa":"L","tur":"olcu","es":["yoğuşma gizli ısısı","latent heat of condensation","saklı ısı","özgül gizli ısı","faz değişim ısısı"],"tanim":["Bir maddenin sabit sıcaklık ve basınçta faz değiştirmesi sırasında soğurduğu veya açığa çıkardığı enerji miktarı.","Meteorolojide suyun buharlaşma gizli ısısı Lv ≈ 2,5×10⁶ J/kg, süblimleşme gizli ısısı Ld ≈ 2,83×10⁶ J/kg ve erime gizli ısısı ≈ 3,3×10⁵ J/kg mertebesinde yer alır.","Doymuş parsel yükselirken yoğuşan suyun ortama verdiği gizli ısı, parselin soğumasını geciktirerek konvektif kaldırma kuvvetini besler."],"tanim_en":"Amount of thermal energy absorbed or liberated by a substance during a transition between states of matter at constant temperature.","bag":{"kavram":["gamma-s","kuru-adyabat","es-cc"],"soru":["S4","S16","S36"],"hesap":["theta"]}},{"id":"pseudoadiabatic-process","tr":"Yalancı adyabatik süreç","en":"pseudoadiabatic process","kisa":"","tur":"surec","es":["yalancı adyabat","pseudoadiabatic ascent","irreversible moist adiabatic process","pseudoadiabatic expansion","pseudoadiyabatik süreç"],"tanim":["Doymuş bir hava parseli yükselirken yoğuşan suyun derhal parseli terk edip çökeldiği varsayılan geri dönüşsüz adyabatik süreç.","Yoğuşan sıvının ısı sığası sistemden çıktığı için tersinir nemli adyabatik süreçten kuramsal olarak ayrılır; pratikte sıcaklık değişimi farkı çok küçüktür.","Föhn olayında rüzgâraltı yamaçta oluşan belirgin ısınmayı ve Skew-T diyagramlarındaki doymuş adyabat eğrilerini açıklamakta temel kabul olarak kullanılır."],"tanim_en":"A moist adiabatic expansion in which all condensed liquid water falls out of the parcel immediately upon formation.","bag":{"kavram":["gamma-s"],"soru":[],"hesap":[]}},{"id":"haze-droplet","tr":"Pus damlacığı","en":"haze droplet","kisa":"","tur":"kavram","es":["haze damlası","pus damlası","aktive olmamış damla","unactivated droplet","haze particle"],"tanim":["Higroskopik bir aerosol çekirdeğinin doymamış havada su buharı soğurarak oluşturduğu kararlı dengedeki çözelti damlacığı.","Köhler eğrisinin tepe noktasından önceki kararlı sol kolda yer alır; ortam bağıl nemiyle dengede kalır.","Çözünen etkisi eğrilik etkisinden büyük olduğu için %100 bağıl nemin altında dahi buharlaşmadan varlığını korur ve atmosferde görüş mesafesini düşürür."],"tanim_en":"A stable aqueous solution droplet formed on a hygroscopic nucleus in equilibrium with air at a relative humidity below 100%.","bag":{"kavram":["higroskopik","ccn","kohler"],"soru":["S26","S30"],"hesap":[]}},{"id":"saturated-solution","tr":"Doygun çözelti","en":"saturated solution","kisa":"","tur":"kavram","es":["doymuş çözelti","doygun eriyik","saturated aqueous solution"],"tanim":["Belirli bir sıcaklık ve basınçta, çözücünün çözebileceği en yüksek miktarda çözünen madde içeren ve çözünmemiş katısıyla dinamik dengede bulunan çözelti.","Doygun çözeltinin buhar basıncı aynı sıcaklıktaki saf suyun buhar basıncından daima düşüktür; bu oran kritik bağıl nemi verir.","Atmosferde higroskopik aerosol taneciklerinin nem çekip eriyik faza geçiş sınırını belirler."],"tanim_en":"A chemical solution containing the maximum concentration of dissolved solute in equilibrium with the undissolved substance at a given temperature.","bag":{"kavram":["higroskopik","raoult"],"soru":["S24","S25","S27"],"hesap":["drh"]}},{"id":"relative-humidity","tr":"Bağıl nem","en":"relative humidity","kisa":"RH","tur":"olcu","es":["bagil nem","RH","nisbi nem","oransal nem","bağıl nem denklemi","nispi nem"],"tanim":["Belirli bir sıcaklık ve basınçta havadaki su buharı kısmi basıncının, aynı sıcaklıkta düz su yüzeyine göre doyma buhar basıncına yüzde oranı.","WMO tanımında aynı basınç ve sıcaklıkta su buharı mol kesrinin doymuş havadakine yüzde oranı olarak tanımlanır; kitapta e/es veya buhar basınçları oranı olarak kullanılır.","Sis oluşumu, higroskopik aerosollerin delikesans eşiği ve Köhler eğrisi aktivasyon kriterinde doymayı belirleyen temel termodinamik büyüklüktür."],"tanim_en":"The percentage ratio of the actual vapor pressure of moist air to the saturation vapor pressure over liquid water at the same temperature and pressure.","bag":{"kavram":["higroskopik","es-cc","sis"],"soru":["S21","S24","S27","S28","S29","S30"],"hesap":["theta","kaldir-z","karisma","drh"]}},{"id":"saturated-solution-vapor-pressure","tr":"Doygun çözeltinin buhar basıncı","en":"saturated solution vapor pressure","kisa":"p_sat,sol","tur":"olcu","es":["çözelti buhar basıncı","equilibrium vapor pressure of solution","p_sat,sol","p_sol","p_çözelti","p(doygun çözelti)"],"tanim":["Katı çözüneni ile dengede bulunan doygun bir çözeltinin üzerindeki denge su buharı kısmi basıncı.","Raoult etkisi nedeniyle aynı sıcaklıktaki saf suyun doyma buhar basıncından daima düşüktür.","Saf su buhar basıncına bölünerek higroskopik tuzların kritik bağıl nemini ve delikesans başlangıç noktasını belirler."],"tanim_en":"The partial pressure exerted by water vapor in thermodynamic equilibrium with a saturated aqueous solution at a given temperature.","bag":{"kavram":["higroskopik","raoult","cc-iki"],"soru":["S24","S25","S27"],"hesap":["drh"]}},{"id":"deliquescence","tr":"Delikesans (nemle erime)","en":"deliquescence","kisa":"","tur":"surec","es":["nem çekip eriyik olma","nemle erime","eriyikleşme","nem çekerek çözünme","deliquescent"],"tanim":["Havadaki su buharı kısmi basıncının katının doygun çözeltisinin buhar basıncını aşması durumunda katı parçacığın nem çekerek tamamen sıvı eriyiğe dönüşmesi süreci.","Ortam bağıl nemi maddenin kritik bağıl nem eşiğini aştığında kendiliğinden başlar.","Deniz tuzu ve amonyum sülfat gibi atmosferik aerosollerin doymamış havada dahi çözelti damlası haline gelmesini ve pus oluşturmasını açıklar."],"tanim_en":"The transition in which a soluble solid salt absorbs ambient moisture to become a liquid droplet when ambient relative humidity climbs above the deliquescence threshold.","bag":{"kavram":["higroskopik"],"soru":["S24","S27"],"hesap":[]}},{"id":"cloud-seeding","tr":"Bulut tohumlama","en":"cloud seeding","kisa":"","tur":"yontem","es":["hava müdahalesi","yağış artırma tohumlaması","yapay yağmur","suni tohumlama","hava modifikasyonu","weather modification"],"tanim":["Yağış oluşturmak veya bulut yapısını değiştirmek amacıyla uygun özellikteki parçacıkların bulut içine yapay olarak salınması yöntemidir.","Sıcak bulutlarda higroskopik tuz aerosolleri, aşırı soğumuş soğuk bulutlarda ise gümüş iyodür veya kuru buz parçacıkları kullanılır.","Yağış miktarını artırma, sisi dağıtma ya da dolu tanelerinin büyümesini sınırlandırma amacıyla uygulanır."],"tanim_en":"Introduction of particles of appropriate material into a cloud which modifies the cloud structure in order to trigger precipitation.","bag":{"kavram":["higroskopik","donma","ccn"],"soru":["S33","S40"],"hesap":["drh"]}},{"id":"hygroscopic-cloud-seeding","tr":"Higroskopik bulut tohumlama","en":"hygroscopic cloud seeding","kisa":"","tur":"yontem","es":["tuzla tohumlama","higroskopik tohumlama","sıcak bulut tohumlama","hygroscopic seeding","tuz tohumlaması"],"tanim":["Sıcak bulutların tabanına iri higroskopik tuz tanecikleri salarak çarpışma-birleşme sürecini erkenden başlatmayı amaçlayan tohumlama yöntemidir.","Eklenen dev CCN parçacıkları düşük aşırı doymuşlukta bile hızla su çekerek en az 20 µm yarıçapında öncü toplayıcı damlalar üretir.","Karasal bulutlardaki çok sayıda küçük damla nedeniyle geciken sıcak yağmur oluşumunu hızlandırmak için uygulanır."],"tanim_en":"The dispersal of large hygroscopic aerosol particles into warm clouds to accelerate the collision-coalescence mechanism by producing collector drops.","bag":{"kavram":["higroskopik","carpisma","ccn"],"soru":["S33","S40","S46"],"hesap":["drh"]}},{"id":"environment","tr":"Çevre (ortam havası)","en":"environment (ambient air)","kisa":"","tur":"kavram","es":["çevre","ortam havası","ambient air","environmental air","çevre havası","environment"],"tanim":["Termodinamik çözümlemelerde yükselen veya alçalan hava parselinin dışında kalan ve parselle etkileşen ortam atmosferi.","Sıcaklık, basınç ve nem profili radyosonde ölçümleriyle belirlenir; sıcaklığın düşey değişim oranı çevre azalma oranı ile ifade edilir.","Parsel ile çevre arasındaki sanal sıcaklık ve yoğunluk farkı, kaldırma kuvvetini ve atmosferin statik kararlılık durumunu belirler."],"tanim_en":"The ambient atmosphere surrounding an air parcel whose thermodynamic properties determine the buoyant acceleration and static stability of the parcel.","bag":{"kavram":["kaldirma","kararlilik"],"soru":["S5","S6","S7","S8","S9","S10"],"hesap":["kaldirma","gamma","lcl-lfc","cape"]}},{"id":"negative-buoyancy","tr":"Negatif kaldırma kuvveti","en":"negative buoyancy","kisa":"","tur":"kavram","es":["batma eğilimi","negative buoyant force","negatif yüzerlik","downward buoyant force","aşağı yönlü kaldırma"],"tanim":["Bir hava parselinin sanal sıcaklığının çevre havasından daha düşük olması nedeniyle parselin çevresinden daha yoğun olup aşağı doğru ivmelenmesi durumu.","Birim kütle başına net kuvvet F/m = |g| (T_v,p − T_v,e) / T_v,e denklemiyle hesaplanır ve parsel çevreden soğuk olduğunda eksi işaret alır.","Konvektif bastırmayı (CIN), inversiyon katmanlarındaki kararlılığı ve buharlaşma soğumasıyla tetiklenen aşağı yönlü hava akımlarını üretir."],"tanim_en":"A downward net buoyant acceleration experienced by an air parcel that is colder and more dense than the surrounding ambient air.","bag":{"kavram":["kaldirma","cape","su-butcesi"],"soru":["S8","S9","S10","S17","S45"],"hesap":[]}},{"id":"positive-buoyancy","tr":"Pozitif kaldırma kuvveti","en":"positive buoyancy","kisa":"","tur":"kavram","es":["pozitif yüzerlik","yukarı ivmelenme","pozitif yüzdürme"],"tanim":["Hava parselinin yoğunluğunun çevre havasından daha düşük, yani sanal sıcaklığının daha yüksek olması sonucu ortaya çıkan yukarı yönlü net kaldırma kuvveti.","Birim kütle başına ivme birimi m s⁻² olup sanal sıcaklık farkı pozitif olduğunda parseli yukarı doğru ivmelendirir.","Serbest konveksiyon seviyesinin (LFC) üzerinde parselin kendiliğinden hızlanmasını sağlayarak CAPE alanını meydana getirir."],"tanim_en":"The upward net buoyant acceleration of an air parcel having a higher virtual temperature than the ambient environment.","bag":{"kavram":["kaldirma","cape"],"soru":["S6","S8","S10","S11"],"hesap":[]}},{"id":"thermal-plume","tr":"Termik","en":"thermal","kisa":"","tur":"kavram","es":["termikler","thermal plume","sıcak hava termiği","termik yükselici hava","ısıl kabarcık","termal hava sütunu"],"tanim":["Çevresine göre daha sıcak bir yüzey üzerinde yerel olarak üretilen yukarı yönlü konvektif hava akımı sütunu ya da kabarcığı.","Güneş ışınımıyla ısınan yüzeyden kuru adyabatik olarak yükselir ve çevre sıcaklığıyla eşitlendiği termik tepesinde durur.","Konvektif kaldırma mekanizmasıyla LCL seviyesine ulaştığında kümülüs bulut tabanının oluşumunu başlatır."],"tanim_en":"A local buoyant updraft produced above ground that is warmer than the surrounding ambient air.","bag":{"kavram":["kaldirma","kararlilik","terselme"],"soru":["S7","S11","S41"],"hesap":["limit-hiz","carpisma"]}},{"id":"gravitational-acceleration","tr":"Yerçekimi ivmesi","en":"gravitational acceleration","kisa":"g","tur":"olcu","es":["yerçekimi","acceleration due to gravity","yerçekim ivmesi","g sabiti","yerçekimi g"],"tanim":["Dünya kütleçekimi ile dönmeden kaynaklanan merkezkaç kuvvetinin bileşkesi olan ve serbest düşen cisimlere etkiyen net düşey ivme.","Standart büyüklüğü yaklaşık 9,8 m s⁻² olup atmosfer termodinamiğinde parseli düşeyde kaldırırken yapılan birim iş g dz ile ifade edilir.","Hidrostatik denge denkleminde, kuru adyabatik azalma oranında ve parsel kaldırma ivmesi bağıntılarında temel katsayıdır."],"tanim_en":"The downward acceleration of an object produced by the gravitational attraction of Earth and planetary rotation.","bag":{"kavram":["kaldirma","cape","theta"],"soru":["S17","S46"],"hesap":["theta"]}},{"id":"vertical-velocity","tr":"Düşey hız","en":"vertical velocity","kisa":"w","tur":"olcu","es":["updraft hızı","düşey hava hızı","vertical air motion","düşey hız w","dikey hava hareketi"],"tanim":["Havanın düşey doğrultudaki hareket hızı bileşeni; yukarı yönlü hareket pozitif, aşağı yönlü çökme negatif kabul edilir.","Birimi m s⁻¹ olup sinoptik ölçekte birkaç cm s⁻¹ mertebesindeyken kuvvetli konvektif fırtınalarda onlarca m s⁻¹ değerine ulaşır.","Enerji korunumuna göre parselin biriktirdiği CAPE enerjisinden en büyük düşey hız kuramsal olarak hesaplanır."],"tanim_en":"The vertical component of air motion velocity, defined as positive upward and negative downward.","bag":{"kavram":["kaldirma","cape","kararlilik"],"soru":["S9","S10"],"hesap":["cape"]}},{"id":"free-convection","tr":"Serbest konveksiyon","en":"free convection","kisa":"","tur":"surec","es":["serbest yükselme","doğal konveksiyon","kendiliğinden yükselme","kendiliğinden konveksiyon","spontaneous convection"],"tanim":["Yoğunluk ve kaldırma kuvveti farkları sonucu akışkanın dış mekanik zorlama olmadan kendiliğinden düşey harekete geçmesi süreci.","Atmosferde hava parselinin serbest konveksiyon seviyesini aşarak çevre havasından daha sıcak duruma gelmesiyle tetiklenir.","Kümülüs ve kümülonimbüs gibi dikey gelişimli bulutların ana büyüme mekanizmasıdır."],"tanim_en":"Convective motion driven by buoyancy arising from density differences, without external mechanical forcing.","bag":{"kavram":["kaldirma","lcl-lfc","kaldirma-mek"],"soru":["S6","S8","S10","S11"],"hesap":["lcl-lfc"]}},{"id":"updraft","tr":"Yukarı hava akımı","en":"updraft","kisa":"","tur":"surec","es":["yukarı akım","düşey yukarı akım","konvektif yukarı akım","convective updraft","yükselen hava akımı","konvektif akım"],"tanim":["Konvektif bir fırtına hücresi veya bulut sütunu içinde yukarı doğru yönelen belirgin hava akımı.","Şiddetli kümülonimbüs fırtınalarında hızı 50 m s⁻¹ değerini aşabilir ve su damlacıkları ile buz tanelerini yukarı taşır.","Fırtına bulutunun üst üçte birinde en yüksek güce ulaşarak dolunun büyümesini ve örs yapısının yayılmasını destekler."],"tanim_en":"A strong upward-moving current of air within a cloud or convective storm.","bag":{"kavram":["kaldirma","cape","ccn"],"soru":["S9","S10","S32","S41","S46"],"hesap":["cape"]}},{"id":"archimedes-principle","tr":"Arşimet ilkesi","en":"Archimedes' principle","kisa":"","tur":"yontem","es":["Arsimet prensibi","Arşimet kanunu","Arşimet itmesi","buoyancy principle"],"tanim":["Durgun bir akışkana daldırılan cisme veya hava parseline etkiyen kaldırma kuvvetinin, yer değiştiren akışkanın ağırlığına eşit olduğunu belirten temel fizik ilkesi.","Atmosferde parsel ağırlığı ile yer değiştiren çevre havasının itme kuvveti farkından net ivme bağıntısı türetilir.","Referans ortam yer değiştiren çevre havası olduğu için kaldırma ivmesi formülünün paydasında çevrenin sanal sıcaklığı yer alır."],"tanim_en":"The physical law stating that a body immersed in a fluid is buoyed up by a force equal to the weight of displaced fluid.","bag":{"kavram":["kaldirma"],"soru":["S5"],"hesap":["kaldirma"]}},{"id":"front","tr":"Cephe","en":"front","kisa":"","tur":"kavram","es":["cephe yüzeyi","frontal surface","hava cephesi","meteorolojik cephe","frontal zone","cephe eğimi"],"tanim":["Farklı yoğunluk, sıcaklık veya nem özelliklerine sahip iki hava kütlesi arasındaki geçiş kuşağı ya da bu yüzeyin yerle kesişim çizgisi.","Sıcak ve hafif havanın soğuk hava kaması üzerine kaymasıyla düşey cephesel terselme ve geniş bulut katmanları oluşturur.","Atmosferdeki dört ana kaldırma mekanizmasından biri olup havanın CIN engelini aşarak LFC seviyesine yükselmesini sağlar."],"tanim_en":"A transition zone separating air masses, which differ in density, temperature or moisture.","bag":{"kavram":["kaldirma-mek","terselme"],"soru":["S9","S10","S11","S12","S18","S23"],"hesap":[]}},{"id":"orographic-cloud","tr":"Orografik bulut","en":"orographic cloud","kisa":"","tur":"kavram","es":["orographic clouds","dağ bulutu","yamaç bulutu","dalga bulutu"],"tanim":["Nemli hava akıntısının dağ ya da tepe gibi topografik bir engelle karşılaşarak yükselmeye zorlanması sonucu oluşan bulut.","Rüzgârüstü yamaçta LCL seviyesinin aşılmasıyla tabanı oluşur ve dağ zirvesine kadar nemli adyabatik soğumayla kalınlaşır.","Bulut içinde yoğuşan suyun yağışla sistemden ayrılması durumunda gizli ısı havada kalarak rüzgâraltında föhn ısınmasına yol açar."],"tanim_en":"A cloud formed when moist air is forced to ascend over a mountain barrier or elevated terrain.","bag":{"kavram":["kaldirma-mek","fohn"],"soru":["S16"],"hesap":[]}},{"id":"sea-breeze","tr":"Deniz meltemi","en":"Sea breeze","kisa":"","tur":"kavram","es":["kıyı rüzgârı","deniz meltemi cephesi","gündüz meltemi"],"tanim":["Gündüz saatlerinde karanın denizden daha hızlı ısınmasıyla oluşan yerel basınç farkının tetiklediği, denizden karaya doğru esen serin kıyı rüzgârı.","Kıyı çizgisinden içeriye doğru ilerleyerek deniz meltemi cephesi oluşturur ve sıcak kara havasıyla temas ettiğinde alçak seviye yakınsaması meydana getirir.","Yakınsayan havanın kütle sürekliliği gereği yükselmesiyle konvektif bulut gelişimini ve kıyı içi yağışları başlatabilir."],"tanim_en":"A coastal local wind blowing from sea to land during daytime, driven by differential heating between land and water.","bag":{"kavram":["kaldirma-mek"],"soru":["S11"],"hesap":[]}},{"id":"warm-front","tr":"Sıcak cephe","en":"Warm front","kisa":"","tur":"kavram","es":["sıcak cephe sistemi","sıcak cephe hattı","warm frontal boundary"],"tanim":["Sıcak ve hafif bir hava kütlesinin geri çekilen soğuk hava kütlesinin yerine geçtiği geçiş kuşağı.","Yatay eğimi tipik olarak 1/100 ile 1/300 arasında sığ bir eğim gösterir; yaklaşırken gökyüzünde Ci → Cs → As → Ns bulut sırası izlenir.","Geniş alana yayılan sürekli yağış üretir; cephe yüzeyinden düşen ılık yağmur damlalarının soğuk alt katmanda buharlaşmasıyla cephe sisi oluşur."],"tanim_en":"A transition zone where an advancing warm air mass replaces a retreating colder air mass, producing a broad cloud shield and steady precipitation.","bag":{"kavram":["kaldirma-mek","bulut-tur"],"soru":["S12","S18"],"hesap":[]}},{"id":"convective-lifting","tr":"Konvektif kaldırma","en":"Convective lifting","kisa":"","tur":"surec","es":["ısınmayla yükselme","termal konveksiyon","thermal convection","free convective lifting"],"tanim":["Güneş ışınımıyla ısınan yüzeyin alt hava tabakasını ısıtması sonucu, çevre havasından daha sıcak ve hafif hale gelen havanın pozitif kaldırma kuvvetiyle kendiliğinden yükselmesi süreci.","Yükselmenin sürmesi için atmosferin kararsız olması şarttır; serbest konveksiyon seviyesi aşıldığında parsel pozitif CAPE enerjisi kazanır.","Bulut fiziğinde kümülüs ve kümülonimbüs gibi dikey gelişimli kule bulutlarının oluşumunu başlatır."],"tanim_en":"Ascent of air driven by positive buoyancy when surface heating makes low-level parcels warmer than the surrounding air.","bag":{"kavram":["kaldirma-mek","cape"],"soru":["S11"],"hesap":[]}},{"id":"convergence","tr":"Yakınsama","en":"convergence","kisa":"CONV","tur":"surec","es":["hava yakınsaması","yatay yakınsama","flow convergence","konverjans","yakınsama ile kaldırma","yüzey yakınsaması"],"tanim":["Bir vektör alanının büzülmesi veya negatif işaretli ıraksaması; meteorolojide belirli bir alana doğru yönelen yatay hava akışlarının net kütle toplanması oluşturması.","Kütle sürekliliği ilkesi gereği alçak seviyede toplanan hava gidecek yer bulamayarak yükselir ve soğuyarak yoğuşmaya yol açar.","Alçak basınç merkezlerinde ve deniz meltemi hatlarında hava parsellerini yoğuşma seviyesine zorlayarak bulut oluşumunu destekleyen bir kaldırma mekanizmasıdır."],"tanim_en":"The contraction of a vector field, or negative divergence, representing a net horizontal inflow of air into a region that forces vertical ascent by mass continuity.","bag":{"kavram":["kaldirma-mek","lcl-lfc"],"soru":["S8","S11"],"hesap":[]}},{"id":"divergence","tr":"Iraksama","en":"Divergence","kisa":"DIV","tur":"surec","es":["yatay ıraksama","diverjans","horizontal divergence"],"tanim":["Bir vektör alanının genişlemesi veya yayılması; meteorolojide bir hava hacminden dışarıya doğru olan net yatay hava çıkışını ifade eden skaler büyüklük.","Alçak seviyedeki yatay ıraksama kütle sürekliliği nedeniyle yukarıdan inen havayla dengelenir.","Çöken havanın adyabatik olarak ısınıp kuruması nedeniyle bulutların dağılmasına ve antisiklonik çökme terselmesi oluşmasına yol açar."],"tanim_en":"The expansion or spreading out of a vector field, representing a net horizontal outflow of air that induces subsidence and adiabatic warming in the atmospheric column.","bag":{"kavram":["kaldirma-mek"],"soru":["S11"],"hesap":[]}},{"id":"forced-lifting","tr":"Zorlanmış yükselme","en":"forced lifting","kisa":"","tur":"surec","es":["zorlanmış konveksiyon","forced convection","mekanik kaldırma","zorlanmış kaldırma","Zorlamalı kaldırma","zorlamalı kaldırma"],"tanim":["Havanın pürüzlü veya eğimli bir yüzey üzerinden geçmesi gibi mekanik kuvvetlerin etkisiyle yukarı doğru ötelenmesi ve yükselmesi süreci.","Orografik engeller, cephe yüzeyleri ve yüzey yakınsaması olmak üzere üç ana mekanik kaldırma yolunu kapsar.","Kararlı havada katman bulutları oluştururken, havayı serbest konveksiyon seviyesine taşıdığında kule bulutlarının gelişimini başlatır."],"tanim_en":"Upward displacement of air caused by mechanical forcing, such as flow over sloping terrain, along frontal surfaces or in convergence zones.","bag":{"kavram":["kaldirma-mek"],"soru":["S6","S11"],"hesap":[]}},{"id":"frontal-lifting","tr":"Cephesel kaldırma","en":"frontal lifting","kisa":"","tur":"surec","es":["cephe ile yükselme","cephe boyunca yükselme","frontal ascent","cephesel tırmanma"],"tanim":["Farklı yoğunluk ve sıcaklıktaki iki hava kütlesi karşılaştığında, yoğun soğuk havanın kama oluşturarak hafif ılık havayı yukarı doğru ötelemesi ve yükseltmesi süreci.","Yükselen sıcak hava adyabatik olarak genleşip soğur ve yoğuşma seviyesine ulaşarak cephe boyunca geniş bulut örtüsü ve yağış kuşağı oluşturur.","Kararlı havada geniş katman bulutları üretirken, kararsız havada cephe boyunca kule bulutları ve sağanak hatları meydana getirir."],"tanim_en":"The upward displacement of a warm, less dense air mass as it glides over a wedge of denser cold air along a frontal boundary.","bag":{"kavram":["kaldirma-mek","lcl-lfc"],"soru":["S9","S11"],"hesap":[]}},{"id":"orographic-lifting","tr":"Orografik kaldırma","en":"orographic lifting","kisa":"","tur":"surec","es":["dağ etkisiyle kaldırma","dağ etkisiyle yükselme","topographic lifting","orografik yükselme","topoğrafik kaldırma","orographic lift"],"tanim":["Yatay hava akışının dağ veya tepe gibi topoğrafik bir engelle karşılaşarak yamaç boyunca yukarı doğru yükselmeye zorlanması süreci.","Yükselen parsel yoğuşma seviyesine (LCL) kadar kuru adyabatik (9,8 K/km), LCL üzerinde ise nemli adyabatik (4–7 K/km) hızla soğur.","Rüzgârüstü yamaçta orografik bulut ve bol yağış oluştururken, rüzgâraltı yamaçta alçalan havanın kuru adyabatik ısınmasıyla föhn rüzgârına yol açar."],"tanim_en":"The forced ascent of an air mass directed against the sloping terrain of a mountain barrier.","bag":{"kavram":["kaldirma-mek","lcl-lfc","fohn"],"soru":["S11","S16"],"hesap":[]}},{"id":"unit-kelvin-per-kilometer","tr":"Kilometre başına Kelvin","en":"kelvin per kilometer","kisa":"K/km","tur":"birim","es":["K/km","Kelvin bölü kilometre","K km⁻¹","azalma oranı birimi","lapse rate unit","Kelvin/km"],"tanim":["Atmosferde sıcaklığın yükseklikle dikey değişim veya azalma oranını ifade eden türetilmiş SI birimi.","Kuru hava için adyabatik azalma oranı 9,8 K/km iken, doymuş hava için nemli adyabatik azalma oranı tipik olarak 4 ile 7 K/km arasında değişir.","Çevre sondajından hesaplanan sıcaklık gradyanı ile adyabatik oranların karşılaştırılmasında ve statik kararlılık analizinde kullanılır."],"tanim_en":"The standard meteorological unit used to express vertical temperature gradients and lapse rates in the atmosphere.","bag":{"kavram":["kararlilik","kuru-adyabat","gamma-s"],"soru":["S3","S6","S7","S8","S16"],"hesap":[]}},{"id":"skew-t-log-p-diagram","tr":"Skew-T diyagramı","en":"Skew-T log-P diagram","kisa":"Skew-T","tur":"cihaz","es":["Skew-T","skew-T chart","aerological diagram"],"tanim":["Yatay ekseninde eğik izotermlerin, düşey ekseninde ise logaritmik basıncın yer aldığı standart meteorolojik termodinamik diyagram.","Diyagram üzerinde kuru adyabatlar, nemli adyabatlar ve doyma karışma oranı çizgileri bulunur; alan enerjiyle orantılıdır.","Radyosonde verilerini işleyerek atmosferin düşey kararlılık yapısını, yoğuşma seviyelerini ve CAPE ile CIN enerjilerini grafiksel olarak belirlemeye yarar."],"tanim_en":"A standard thermodynamic diagram with temperature plotted on a skewed axis and pressure on a logarithmic vertical scale, used to evaluate atmospheric stability and convective energy.","bag":{"kavram":["kararlilik"],"soru":[],"hesap":[]}},{"id":"sounding","tr":"Sondaj","en":"sounding","kisa":"","tur":"cihaz","es":["atmosfer sondajı","atmospheric sounding","çevre sondajı","environmental sounding","radyosonde","radyosonde profili"],"tanim":["Atmosfer sütununun düşey sıcaklık, basınç, nem ve rüzgâr profilinin radyosonde ile ölçülmesidir.","Ölçülen düşey çevre profili (Γ), kuru (Γd) ve nemli (Γs) adyabatik azalma oranlarıyla karşılaştırılarak atmosferin statik kararlılığı belirlenir.","Sıcaklık terselmesi katmanlarını, bağıl nem dağılımını ve bulut tabanı ile tavanı sınırlarını tespit etmede temel araçtır."],"tanim_en":"An upper-air observation of the vertical profile of temperature, pressure, humidity and wind, usually made with a radiosonde.","bag":{"kavram":["kararlilik","kuru-adyabat"],"soru":["S7"],"hesap":[]}},{"id":"absolute-instability","tr":"Mutlak kararsız","en":"absolute instability","kisa":"Γ > Γd","tur":"kavram","es":["mutlak kararsizlik","absolutely unstable","mutlak kararsızlık","absolutely unstable layer","süperadyabatik katman","mutlak kararsiz"],"tanim":["Çevre sıcaklık azalma oranının kuru adyabatik azalma oranını aştığı (Γ > Γd) atmosferik kararsızlık durumu.","Bu tabakada Brunt–Väisälä frekansının karesi negatiftir (N² < 0) ve düşey yer değiştiren hava parseli doymuş ya da doymamış olmasına bakılmaksızın ivmelenerek çevreden uzaklaşır.","Güneşli günlerde yer yüzeyinin kuvvetli ısınmasıyla zemin üstündeki sığ katmanda süperadyabatik koşul olarak gelişir."],"tanim_en":"State of an atmospheric layer whose environmental lapse rate exceeds the dry adiabatic lapse rate, so that vertically displaced parcels accelerate away from their initial level.","bag":{"kavram":["kararlilik"],"soru":["S6","S7"],"hesap":["gamma"]}},{"id":"absolute-stability","tr":"Mutlak kararlı","en":"absolute stability","kisa":"Γ < Γs","tur":"kavram","es":["mutlak kararlilik","absolutely stable","mutlak kararlılık","absolutely stable layer","mutlak kararlı durum","kararli tabakalasma"],"tanim":["Çevre azalma oranının nemli adyabatik azalma oranından daha küçük olduğu (Γ < Γs) kararlı atmosferik tabakalaşma durumu.","Düşey yer değiştirmeye uğrayan bir hava parseli bütünüyle doymuş olsa dahi çevresinden daha soğuk kalarak başlangıç konumuna geri döner (N² > 0).","LFC seviyesi oluşmaz ve dikey konvektif bulut gelişimi bütünüyle engellenir."],"tanim_en":"State of an atmospheric layer where the environmental lapse rate is lower than the moist adiabatic lapse rate, causing displaced air parcels to return to their initial level.","bag":{"kavram":["kararlilik"],"soru":["S6","S9"],"hesap":["gamma"]}},{"id":"atmospheric-boundary-layer","tr":"Sınır katmanı","en":"atmospheric boundary layer","kisa":"ABL","tur":"kavram","es":["gezegensel sınır katmanı","planetary boundary layer","ABL","PBL","atmosferik sınır tabakası"],"tanim":["Yeryüzü ile doğrudan temas halinde bulunan, yüzey sürtünmesi ve ısı akılarından doğrudan etkilenen alt troposfer tabakası.","Gündüz yüzey ısınmasıyla gelişen konvektif termiklerin ve türbülanslı karışmanın hapsolduğu kalınlığı tipik olarak 1–2 km olan katmandır.","Yüzeyden ısınan termik hava parselleri bu katmanda çevreye göre sıcak kalarak yükselir ve tabakanın tavanındaki kararlı sınırda durur."],"tanim_en":"The lowest layer of the troposphere directly influenced by contact with the planetary surface and driven by turbulent transport.","bag":{"kavram":["kararlilik"],"soru":["S7"],"hesap":[]}},{"id":"conditional-instability","tr":"Koşullu kararsız","en":"conditional instability","kisa":"Γs < Γ < Γd","tur":"kavram","es":["kosullu kararsizlik","conditionally unstable","koşullu kararsızlık","koşullu kararsız katman","conditional stability criteria","koşullu kararsız hava"],"tanim":["Çevre azalma oranının nemli ve kuru adyabatik azalma oranları arasında yer aldığı (Γs < Γ < Γd) statik kararlılık durumu.","Katman doymamış hava parseli için kararlı (N²kuru > 0) iken, doymuş hava parseli için kararsız (N²doymuş < 0) davranır.","Parselin serbest konveksiyona geçebilmesi için dış bir zorlamayla LFC seviyesine kadar yükseltilmesi gerekir."],"tanim_en":"Atmospheric condition where a layer is stable for unsaturated air but unstable for saturated air.","bag":{"kavram":["kararlilik"],"soru":["S6","S7","S8","S9"],"hesap":["gamma"]}},{"id":"haze","tr":"Kuru pus","en":"haze","kisa":"","tur":"kavram","es":["pus (haze)","haze layer","pus tabakası","atmosferik pus","kuru bulanıklık"],"tanim":["Gökyüzüne donuk ve sütümsü bir görünüm veren, gözle tek tek seçilemeyen son derece küçük kuru parçacıkların atmosferdeki asılı durumu.","Bulut fiziğinde (kitapta) haze sözcüğü, higroskopik aerosollerin %100 bağıl nemin altında su çekip şişmesiyle oluşan pus damlacıklarını (haze droplets) da kapsar; bu nemli hâl görüşü daha da düşürür.","Yatay görüş mesafesini düşürür ancak sis sınırının (1 km) üstünde tutar; Köhler eğrisinde kritik yarıçapın solundaki kararlı denge koluna karşılık gelir."],"tanim_en":"Atmospheric suspension of microscopic dry particles or deliquesced aerosol droplets reducing visibility and giving the sky an opalescent appearance.","bag":{"kavram":["kararlilik","higroskopik","ccn"],"soru":["S26","S30"],"hesap":[]}},{"id":"kelvin-helmholtz-waves","tr":"Kelvin–Helmholtz dalgaları","en":"Kelvin–Helmholtz waves","kisa":"K-H","tur":"kavram","es":["Kelvin-Helmholtz cloud","KH dalgaları","dalga bulutu","Kelvin-Helmholtz kararsızlığı","dalga kıvrımları"],"tanim":["Farklı yoğunluk ve hızdaki iki hava tabakası arasındaki dikey rüzgâr kesmesi nedeniyle ara yüzeyde oluşan kıvrımlı dalga yapısı.","Statik olarak kararlı bir ortamda dikey rüzgâr kesmesinin dinamik kararsızlık yaratması sonucu kırılan dalga veya tepe biçimli bulut dizileri üretir.","Kitapta ve bulut morfolojisinde kesme kararsızlığının ve açık hava türbülansının tipik görsel işareti olarak incelenir."],"tanim_en":"Wave trains produced by vertical wind shear across a stable density interface that curl and break into billow clouds.","bag":{"kavram":["kararlilik"],"soru":["S17"],"hesap":[]}},{"id":"neutral-stability","tr":"Nötr kararlılık","en":"neutral stability","kisa":"","tur":"kavram","es":["notr","statically neutral","nötr","neutral","nötr denge"],"tanim":["Düşey olarak yer değiştiren bir hava parseline net bir kaldırma kuvvetinin etki etmediği ve parselin ulaştığı yeni seviyede dengede kaldığı hidrostatik denge durumu.","Kuru havada çevre azalma oranının kuru adyabatik azalma oranına eşit olmasıyla (Γ = Γd) veya potansiyel sıcaklığın yükseklikle değişmemesiyle (dθ/dz = 0) belirlenir.","Bu durumda Brunt–Väisälä frekansının karesi sıfırdır (N² = 0); parsel ne başlangıç konumuna döner ne de ivmelenerek uzaklaşır."],"tanim_en":"State of hydrostatic equilibrium in which a vertically displaced air parcel feels no buoyant net force and remains at its new level.","bag":{"kavram":["kararlilik"],"soru":["S7"],"hesap":[]}},{"id":"superadiabatic","tr":"Süperadyabatik","en":"superadiabatic","kisa":"Γ > Γd","tur":"kavram","es":["kuru adyabatikten dik","superadiabatic lapse rate","aşırı adyabatik","süperadyabatik katman"],"tanim":["Sıcaklığın yükseklikle azalma oranının kuru adyabatik azalma oranından daha büyük olduğu (Γ > Γd) tabaka veya durum.","Kuru havanın düşey potansiyel sıcaklık gradyanının negatif olduğu (dθ/dz < 0) ve mutlak kararsızlığın görüldüğü koşuldur.","Güneşli günlerde yer yüzeyinin güçlü ışınımsal ısınmasıyla yüzeye çok yakın ince sınır katmanında termik hareketleri tetikler."],"tanim_en":"Characterized by an environmental temperature lapse rate that exceeds the dry adiabatic lapse rate.","bag":{"kavram":["kararlilik","kuru-adyabat"],"soru":["S6","S7"],"hesap":[]}},{"id":"brunt-vaisala-frequency","tr":"Brunt–Väisälä frekansı","en":"Brunt–Väisälä frequency","kisa":"N","tur":"olcu","es":["kaldırma frekansı","buoyancy frequency","N frekansı","buoyancy frequency N","N2","statik kararlılık parametresi"],"tanim":["Statik olarak kararlı bir atmosferde düşey olarak dengesinden saptırılan bir hava parselinin yerçekimi ve kaldırma etkisiyle yaptığı salınımın açısal frekansı.","Karesi N² = (g/T)(Γd − Γ) bağıntısıyla hesaplanır; birimi s⁻¹ olup troposferde tipik değeri yaklaşık 0,01 s⁻¹ (periyodu yaklaşık 10 dk) mertebesinde yer alır.","Atmosferik kararlılığın nicel ölçüsüdür: N² > 0 durumu kararlı salınımı, N² = 0 nötr durumu, N² < 0 ise üstel kararsız büyümeyi gösterir."],"tanim_en":"The angular frequency at which a vertically displaced air parcel will oscillate within a statically stable environment.","bag":{"kavram":["kararlilik"],"soru":[],"hesap":["gamma"]}},{"id":"environmental-lapse-rate","tr":"Çevre azalma oranı","en":"environmental lapse rate","kisa":"Γ","tur":"olcu","es":["ELR","cevre gradyani","çevresel azalma oranı","ortam azalma oranı","sıcaklık düşme oranı","ambient lapse rate"],"tanim":["Durgun atmosfer ortamında sıcaklığın yükseklikle dikey olarak azalma hızı (Γ = −ΔT/Δz).","Radyosonde sondajı ile ölçülür; birimi K/km olup standart atmosferdeki tipik değeri 6,5 K/km düzeyinde kabul edilir.","Parsel süreçleri olan Γd ve Γs ile karşılaştırılarak atmosfer tabakasının statik kararlılık sınıfı (mutlak kararlı, koşullu kararsız, mutlak kararsız) belirlenir."],"tanim_en":"The actual rate of decrease of temperature with altitude in the stationary ambient atmosphere.","bag":{"kavram":["kararlilik","terselme"],"soru":["S6","S7","S8","S9"],"hesap":["gamma","lcl-lfc"]}},{"id":"vertical-potential-temperature-gradient","tr":"Düşey potansiyel sıcaklık gradyanı","en":"vertical potential temperature gradient","kisa":"dθ/dz","tur":"olcu","es":["potansiyel sicaklik gradyani","dtheta/dz","potansiyel sıcaklık gradyanı","dθ/dz"],"tanim":["Potansiyel sıcaklığın yüksekliğe göre değişim oranı; atmosferik statik kararlılığı belirleyen temel termodinamik ölçüttür.","Birimi K/m veya K/km olup dθ/dz = (θ/T)(Γd − Γ) bağıntısıyla çevresel azalma oranı ile ilişkilendirilir.","Gradyanın pozitif olması kararlı, sıfır olması nötr, negatif olması ise kararsız tabakaya işaret eder."],"tanim_en":"The vertical rate of change of potential temperature with height that indicates atmospheric static stability.","bag":{"kavram":["kararlilik","theta"],"soru":["S1"],"hesap":["theta"]}},{"id":"hydrostatic-balance","tr":"Hidrostatik denge","en":"hydrostatic balance","kisa":"dP = -ρ g dz","tur":"yontem","es":["hidrostatik denklem","hydrostatic equilibrium","hidrostatik denge yasası"],"tanim":["Düşey basınç gradyanı kuvveti ile yerçekimi kuvvetinin birbirini tam olarak dengelediği durgunluk durumudur.","Diferansiyel ifadesi dP = −ρ g dz olup atmosfer basıncının irtifayla düşüşünü açıklar.","Termodinamiğin birinci yasası ile birleştirilerek kuru adyabatik azalma oranı olan Γd = g/cp eşitliğinin türetilmesinde temel kabuldür."],"tanim_en":"The state of the atmosphere in which the upward vertical pressure gradient force is balanced by downward gravity.","bag":{"kavram":["kararlilik","theta","kuru-adyabat"],"soru":["S9"],"hesap":["theta"]}},{"id":"contrail","tr":"Yoğuşma izi","en":"condensation trail","kisa":"","tur":"kavram","es":["contrail","uçak arkası yoğuşma izi","buhar izi","uçak kuyruk izi","yoğunlaşma izi","uçak izi"],"tanim":["Uçak egzozundan çıkan su buharı ve aerosollerin soğuk üst troposfer havasıyla karışmasıyla oluşan çizgi biçimli yapay buluttur.","İki doymamış havanın izobarik karışımıyla doyma sınırı aşılır; yoğuşan damlacıklar yaklaşık −40 °C altında hemen donar ya da buhar doğrudan buz kristali olarak birikir.","Karışma sisi mekanizması ile açıklanır ve atmosferik nemlilik durumuna göre gökyüzünde uzun süre asılı kalabilir."],"tanim_en":"A line-shaped cloud formed by the mixing of warm water vapor from aircraft exhaust with cold ambient air in the upper troposphere.","bag":{"kavram":["karisma","bulut-tur","sis"],"soru":["S17","S20","S40"],"hesap":[]}},{"id":"mixing-line","tr":"Karışım çizgisi","en":"mixing line","kisa":"","tur":"kavram","es":["karışma çizgisi"],"tanim":["Termodinamik diyagramda farklı sıcaklık ve nem içeriğine sahip iki hava parselinin izobarik karışımıyla oluşan termodinamik durumları birleştiren doğru çizgisidir.","Karışım noktasının sıcaklık ve buhar basıncı, başlangıç parsellerinin kütle ağırlıklı aritmetik ortalamasıyla doğrusal olarak hesaplanır.","Clausius–Clapeyron eğrisinin dışbükeyliği nedeniyle karışım çizgisi doyma eğrisini kesip aşarsa başlangıçta doymamış iki kütle doygunluğa ulaşarak karışma sisi ya da yoğuşma izi oluşturur."],"tanim_en":"A straight line on a psychrometric or thermodynamic diagram connecting two thermodynamic states of air undergoing isobaric mixing.","bag":{"kavram":["karisma"],"soru":["S21","S40"],"hesap":[]}},{"id":"mass-weighted-averaging","tr":"Kütle ağırlıklı ortalama","en":"mass-weighted averaging","kisa":"","tur":"yontem","es":["ağırlıklı ortalama","weighted average","kütlesel ortalama"],"tanim":["İki farklı hava kütlesinin izobarik karışımında son sıcaklık ve buhar basıncının kütle paylarına göre hesaplanması yöntemidir.","Kütle ve entalpi korunumu gereğince TX = (mB TB + mC TC)/mX ve eX = (mB eB + mC eC)/mX bağıntıları ile uygulanır.","Doyma buhar basıncı eğrisinin dışbükey yapısı nedeniyle iki doymamış hava kütlesinin ortalama durumu doyma eğrisinin üzerine çıkabilir."],"tanim_en":"A calculation method for determining the resulting temperature and vapor pressure when two air parcels mix at constant pressure.","bag":{"kavram":["karisma"],"soru":["S20","S21"],"hesap":["karisma"]}},{"id":"unit-micrometer","tr":"Mikrometre","en":"micrometer","kisa":"µm","tur":"birim","es":["mikron","um","µm","micron"],"tanim":["Metrenin milyonda birine (10⁻⁶ m) karşılık gelen uzunluk birimidir; SI temel birimi metrenin ast katıdır.","Bulut fiziğinde aerosol parçacıkları, yoğuşma çekirdekleri ve bulut damlacıklarının boyutlarını ifade etmede temel ölçek olarak kullanılır.","Kelvin eğrilik bağıntısında damla yarıçapı R için doğrudan mikrometre birimi, eğrilik sabiti c₁ için ise µm·K birimi tercih edilir."],"tanim_en":"A metric unit of length equal to one millionth of a meter, commonly applied to quantify aerosol and cloud droplet radii.","bag":{"kavram":["kelvin","kohler","ccn"],"soru":["S28","S29","S36","S38","S41","S42"],"hesap":["kelvin","donma","limit-hiz"]}},{"id":"boltzmann-constant","tr":"Boltzmann sabiti","en":"Boltzmann constant","kisa":"k_B","tur":"olcu","es":["Boltzmann katsayısı","kB sabiti","k_B","kB","Boltzmann sabiti k"],"tanim":["Mikroskobik parçacıkların ortalama termal kinetik enerjisini mutlak sıcaklık ile bağdaştıran temel fizik sabitidir.","Birimi J/K olup kitapta Kelvin eğrilik sabiti bağıntısında c₁ = 2σ/(ρm kB) biçiminde paydada yer alır.","Damla yüzeyindeki su moleküllerinin kimyasal potansiyel farkını Δµ = kB T ln(e/es) eşitliğiyle buhar basıncına bağlar."],"tanim_en":"A fundamental physical constant relating the average thermal kinetic energy of microscopic particles to absolute temperature.","bag":{"kavram":["kelvin","difuzivite"],"soru":["S28"],"hesap":["kelvin"]}},{"id":"droplet-radius","tr":"Damla yarıçapı","en":"droplet radius","kisa":"R","tur":"olcu","es":["damlacık yarıçapı","drop radius","drop radius r","damla boyutu"],"tanim":["Küresel kabul edilen bulut ya da yağmur damlasının merkezinden dış sınırına kadar olan doğrusal uzaklıktır.","Bulut damlacıkları için tipik olarak 10 µm mertebesinde olup mikrofizik formüllerinde mikrometre ya da metre ile temsil edilir.","Köhler eğrisinde hem eğrilik teriminde (1/R) hem de çözünen teriminde (1/R³) bulunarak damlacığın aktivasyonunu denetler."],"tanim_en":"The linear distance from the center of a spherical liquid hydrometeor to its boundary.","bag":{"kavram":["kelvin","kohler","kritik"],"soru":["S28","S29","S32","S36"],"hesap":["kelvin","kohler","ccn","damla-boyu"]}},{"id":"kelvin-curvature-constant","tr":"Kelvin eğrilik sabiti","en":"Kelvin curvature constant","kisa":"c₁","tur":"olcu","es":["eğrilik katsayısı c1","c₁","c1","Kelvin sabiti","curvature constant c1","eğrilik sabiti"],"tanim":["Küresel su damlacıklarında yüzey gerilimi kaynaklı eğrilik etkisini termodinamik dengeye bağlayan sabittir.","Kitapta c₁ = 2σ/(ρm kB) olarak ifade edilir; değeri 0,334 µm·K (veya 3,34×10⁻⁷ m·K) olarak alınır.","Kelvin denkleminde üstel terimin payında yer alır; damlacık küçüldükçe denge buhar basıncı, dolayısıyla dengede kalmak için gereken aşırı doymuşluk artar."],"tanim_en":"A thermodynamic constant in the Kelvin relation that accounts for the curvature effect on droplet equilibrium vapor pressure.","bag":{"kavram":["kelvin","kohler","kritik"],"soru":["S28","S29","S30","S31"],"hesap":["kohler"]}},{"id":"surface-tension","tr":"Yüzey gerilimi","en":"surface tension","kisa":"σ","tur":"olcu","es":["su yüzey gerilimi","sigma","surface energy","yüzey enerjisi"],"tanim":["İki akışkan ortam arasındaki arayüzeyde birim uzunluk başına düşen teğetsel gerilme kuvvetidir.","WMO tanımı doğrultusunda kılcallık üreten arayüzey kuvvetidir; sıvı su için kitapta tipik değeri σ ≈ 0,076 N/m olarak verilir.","Eğri yüzey basınç farkı denkleminde damla iç basıncını 2σ/R kadar yükselterek su moleküllerinin ayrılmasını kolaylaştırır."],"tanim_en":"The interfacial force per unit length that acts to contract the boundary of a liquid.","bag":{"kavram":["kelvin"],"soru":["S26","S29","S33","S40"],"hesap":["kelvin"]}},{"id":"sodium-chloride","tr":"Sodyum klorür","en":"sodium chloride","kisa":"NaCl","tur":"kavram","es":["tuz","sofra tuzu","kaya tuzu","NaCl"],"tanim":["Deniz spreyi yoluyla atmosfere karışarak dev CCN oluşturan, bulut fiziğinde standart çözünen kabul edilen inorganik bir tuz bileşiğidir.","Van 't Hoff faktörü i = 2 ve molar kütlesi M_s = 0,05844 kg/mol olup doymuş çözeltisinin kritik bağıl nem eşiği %75 civarındadır.","Raoult etkisiyle suyun denge buhar basıncını düşürerek bağıl nem %100 altında bile kararlı pus damlacıkları oluşturur."],"tanim_en":"A common atmospheric salt aerosol that acts as an efficient cloud condensation nucleus by lowering the equilibrium vapor pressure of water through Raoult effect.","bag":{"kavram":["kohler","raoult","ccn"],"soru":["S30","S31","S33"],"hesap":[]}},{"id":"solution-droplet","tr":"Çözelti damlası","en":"solution droplet","kisa":"","tur":"kavram","es":["tuzlu damla","tuz çözeltisi damlası","çözelti damlacığı","saline droplet"],"tanim":["Bünyesinde çözünmüş madde (çözünen) bulunduran ve suyun mol kesri saf sudan küçük olan sıvı su damlacığıdır.","Yüzeyindeki denge buhar basıncı Raoult yasası uyarınca suyun mol kesri x_w ile orantılı olarak saf su doyma basıncından düşüktür.","Köhler eğrisinin tepe noktasından önceki kararlı sol kolunda doymamış havada pus damlacığı olarak dengede durabilir; kritik yarıçapı aşınca seyrelerek bulut damlasına dönüşür."],"tanim_en":"An aqueous droplet containing dissolved solute; because of the solute (Raoult) effect it can remain in equilibrium below water saturation.","bag":{"kavram":["kohler","raoult"],"soru":["S24","S26","S30"],"hesap":[]}},{"id":"kohler-solute-constant","tr":"Köhler çözünen sabiti","en":"Köhler solute constant","kisa":"c₂","tur":"olcu","es":["çözünen katsayısı c2","c₂","c2","çözünen katsayısı","solute constant c2","Raoult katsayısı"],"tanim":["Köhler formülasyonunda çözünmüş maddenin damlacık buhar basıncını düşürücü etkisini ölçekleyen sabittir.","Suyun molar kütlesi ile yoğunluğundan c₂ = 3 Mw / (4π ρL) olarak türetilir ve değeri 4,3×10⁻⁶ m³/mol olarak alınır.","Köhler bağıntısında çözünen teriminin (−c₂ i ms / [Ms R³]) katsayısı olarak yer alıp damlacığın doymamış havada dengelenmesini sağlar."],"tanim_en":"A physical constant in the Köhler relation governing the magnitude of the solute effect on droplet equilibrium vapor pressure.","bag":{"kavram":["kohler","raoult","kritik"],"soru":["S30","S31"],"hesap":["kohler"]}},{"id":"saturation-ratio","tr":"Doygunluk oranı","en":"saturation ratio","kisa":"e/eₛ","tur":"olcu","es":["doyma oranı","e*/es","S_R","denge doygunluk oranı"],"tanim":["Havadaki (ya da bir damla yüzeyindeki denge) buhar basıncının, aynı sıcaklıkta düz saf su (ya da buz) yüzeyindeki doyma buhar basıncına oranı: e/eₛ ya da e*/eₛ.","Boyutsuz bir büyüklüktür; 100 ile çarpıldığında denge bağıl nem yüzdesini verir (e*/eₛ × 100 = denge RH).","Köhler denkleminde e*/eₛ biçiminde Kelvin eğrilik etkisi ile Raoult çözelti etkisinin birleşik sonucunu (denge doygunluk oranını) verir."],"tanim_en":"The ratio of the actual (or droplet-equilibrium) vapor pressure to the saturation vapor pressure over a plane surface of pure water or ice at the same temperature.","bag":{"kavram":["kohler"],"soru":["S27","S37"],"hesap":["kohler"]}},{"id":"solute-mass","tr":"Çözünen kütlesi","en":"solute mass","kisa":"m_s","tur":"olcu","es":["tuz kütlesi","aerosol kütlesi","m_s","ms","çekirdek kütlesi","mass of solute"],"tanim":["Yoğuşma çekirdeğini oluşturan ve su damlacığı içinde çözünerek çözelti oluşturan kuru aerosolün kütlesi.","SI birimi kg olup atmosferik yoğuşma çekirdeklerinde tipik büyüklüğü 10⁻¹⁹ kg mertebesinde yer alır.","Köhler kuramında Raoult terimini belirler; kütle büyüdükçe kritik aşırı doymuşluk (S*) azalır ve damlacığın aktivasyonu kolaylaşır."],"tanim_en":"The total mass of dry soluble aerosol substance dissolved in a cloud droplet.","bag":{"kavram":["kohler","kritik","raoult"],"soru":["S30","S31"],"hesap":["kohler"]}},{"id":"solute-molar-mass","tr":"Çözünenin mol kütlesi","en":"solute molar mass","kisa":"M_s","tur":"olcu","es":["tuzun mol ağırlığı","M_s","Ms","mol kütlesi","molekül kütlesi","tuz molekül ağırlığı"],"tanim":["Çözelti damlacığı içindeki çözünen aerosol maddesinin bir molünün kütlesi.","Birimi kg/mol olup deniz tuzu (NaCl) için 0,05844 kg/mol değerine sahiptir.","Raoult teriminde paydada yer alarak çözeltideki çözünmüş mol sayısını belirler; mol kütlesi büyüdükçe aynı kütledeki tuzun buhar basıncını düşürme etkisi azalır."],"tanim_en":"The mass of one mole of a soluble chemical compound forming the cloud condensation nucleus.","bag":{"kavram":["kohler","kritik","raoult"],"soru":["S30","S31"],"hesap":["kohler"]}},{"id":"van-t-hoff-factor","tr":"Van 't Hoff faktörü","en":"van 't Hoff factor","kisa":"i","tur":"olcu","es":["iyon sayısı","ayrışma derecesi","iyonlaşma faktörü","van t Hoff katsayısı","van 't Hoff katsayısı","degree of dissociation"],"tanim":["Çözeltideki bir mol çözünen maddenin ayrışması sonucu ortama verdiği etkin tanecik sayısını gösteren katsayı.","Boyutsuz bir büyüklük olup tam ayrışan sodyum klorür (NaCl) için 2, amonyum sülfat ((NH₄)₂SO₄) için 3 değerini alır.","Raoult ve Köhler bağıntılarında çözünen mol sayısı ile çarpılarak suyun kimyasal potansiyelindeki ve denge buhar basıncındaki düşüşü artırır."],"tanim_en":"A dimensionless factor indicating the number of separate ions produced per formula unit of solute dissolved in water.","bag":{"kavram":["kohler","raoult","kritik"],"soru":["S30","S31"],"hesap":["drh"]}},{"id":"droplet-activation","tr":"Damla aktivasyonu","en":"droplet activation","kisa":"","tur":"surec","es":["aktivasyon","CCN aktivasyonu","aktifleşmiş damlacık","activated cloud droplet","aktif bulut damlası","aktive olmuş damla"],"tanim":["Bir aerosol çözelti damlacığının ortam aşırı doymuşluğu etkisiyle kritik yarıçapını (R*) aşarak kararlı denge durumundan kendiliğinden kontrolsüz büyüme evresine geçişi.","Ortam aşırı doymuşluğu kritik değeri (S*) aştığında gerçekleşir; mikrometre altı pus damlacığı bundan sonra kendiliğinden büyüyen bulut damlasına dönüşür.","Köhler eğrisinin yerel tepe noktasında Kelvin eğrilik etkisi ile Raoult çözelti etkisinin dengelenmesiyle tetiklenir; kritik eşiği geçen damla için gereken denge aşırı doymuşluğu gittikçe düşer."],"tanim_en":"The growth transition of a solution droplet beyond its critical radius to become an actively growing cloud droplet.","bag":{"kavram":["kohler","kritik","ccn"],"soru":["S31","S33"],"hesap":[]}},{"id":"dry-adiabat","tr":"Kuru adyabat","en":"dry adiabat","kisa":"","tur":"kavram","es":["kuru adyabat egrisi","kuru adyabat eğrisi","kuru adyabat çizgisi","dry adiabatic line","dry adiabatic lapse rate line","dry adiabatic curve"],"tanim":["Termodinamik diyagram üzerinde doymamış bir hava parselinin ısı alışverişi olmadan yükselirken ya da alçalırken izlediği sıcaklık–basınç eğrisi.","Bu çizgi boyunca potansiyel sıcaklık (θ) sabit kalır ve düşey sıcaklık değişimi kuru adyabatik azalma oranına (Γd ≈ 9,8 K/km) karşılık gelir.","Parsel yönteminde doymamış havanın kaldırılma seviyesinden yoğuşma seviyesine (LCL) kadar olan hareketini izlemek için kullanılır."],"tanim_en":"A line on a thermodynamic diagram that shows the temperature change of an unsaturated air parcel undergoing adiabatic expansion or compression.","bag":{"kavram":["kuru-adyabat","theta"],"soru":["S3","S6","S7","S8","S16"],"hesap":["theta"]}},{"id":"adiabatic-cooling","tr":"Adyabatik soğuma","en":"Adiabatic cooling","kisa":"","tur":"surec","es":["yükselerek soğuma","ısı alışverişsiz soğuma","adyabatik genleşmeyle soğuma","genleşmeyle soğuma","adiabatic expansion","cooling by adiabatic expansion"],"tanim":["Yükselen bir hava parselinin çevre basıncının düşmesiyle genleşmesi ve çevreye karşı iş yapması sonucu dış ortamla ısı alışverişi olmadan iç enerjisinin ve sıcaklığının azalması.","Doymamış havada kuru adyabatik azalma oranı (Γd ≈ 9,8 K/km) ile, doymuş havada ise gizli ısı salımı nedeniyle nemli adyabatik azalma oranı (Γs ≈ 4–7 K/km) ile gerçekleşir.","Atmosferde bulut ve yağış oluşumuna yol açan en temel soğuma mekanizmasıdır."],"tanim_en":"A reduction in parcel temperature resulting from adiabatic expansion during ascent without heat exchange with the environment.","bag":{"kavram":["kuru-adyabat","gamma-s","sis"],"soru":["S8","S18"],"hesap":[]}},{"id":"adiabatic-warming","tr":"Adyabatik ısınma","en":"adiabatic warming","kisa":"","tur":"surec","es":["adyabatik sıkışmayla ısınma","adiabatic compression warming","adyabatik sikisma","ısı alışverişsiz sıkışma","adyabatik sıkışma","adiabatic compression"],"tanim":["Alçalan bir hava parselinin üzerine binen çevre basıncının artması sonucu sıkışması ve dış ortamla ısı alışverişi olmadan sıcaklığının artması.","Bulutsuz ve doymamış çöken havada kuru adyabatik azalma oranına (Γd ≈ 9,8 K/km) eşit bir ısınma hızıyla gerçekleşir.","Föhn rüzgârlarında dağın rüzgâraltı yamacındaki ani sıcaklık artışını ve antisiklonik çökme alanlarında çökme terselmesi (subsidence inversion) oluşumunu yönlendirir."],"tanim_en":"The thermal warming of descending air due to adiabatic compression during downward motion without external heat transfer.","bag":{"kavram":["kuru-adyabat","fohn","theta"],"soru":["S4","S9","S23"],"hesap":[]}},{"id":"altostratus","tr":"Altostratus","en":"altostratus","kisa":"As","tur":"kavram","es":["altostratus bulutu","altostratus cloud","As","orta katman bulutu","orta seviye katman bulutu"],"tanim":["Gökyüzünü kısmen ya da tamamen örten, grimsi veya mavimsi renkte, çizgili veya düzgün görünüşlü orta katman bulut cinsi (As).","Tabanı ılıman kuşakta genellikle 2 ile 7 km arasında bulunur; ince kısımlarından Güneş buzlu camın arkasındaymış gibi seçilir ancak yerde gölge oluşturmaz ve optik hale üretmez.","Geniş ölçekli ve yavaş cephesel yükselmeyle oluşur; tabanı yüzeye türbülansla bağlı olmadığı için taban yüksekliği yerel LCL formülüyle hesaplanmaz."],"tanim_en":"A middle-level cloud sheet of gray or blue appearance through which the sun may be faintly visible without ground shadow or halo phenomenon.","bag":{"kavram":["lcl-lfc","bulut-tur"],"soru":["S3","S12"],"hesap":[]}},{"id":"cloud-base","tr":"Bulut tabanı","en":"cloud base","kisa":"","tur":"kavram","es":["bulut taban seviyesi","base of cloud","taban yüksekliği","cloud base height","cloud base level","bulut tabanı yüksekliği"],"tanim":["Bir bulutun ya da bulut katmanının gözlenen en alçak seviyesi.","Yüzeyden yükseklik olarak metre veya kilometre cinsinden ifade edilir ve havacılıkta tavan yüksekliğinin belirlenmesinde temel alınır.","Yüzeye türbülansla bağlı konvektif bulutlarda taban seviyesi doğrudan yükselme yoğuşma seviyesine (LCL) karşılık gelir."],"tanim_en":"The lowest level of a cloud or cloud layer.","bag":{"kavram":["lcl-lfc","bulut-tur","su-butcesi"],"soru":["S8","S14","S16","S41","S45"],"hesap":["lcl-lfc","fohn","su-butcesi"]}},{"id":"stratocumulus","tr":"Stratokümülüs","en":"stratocumulus","kisa":"Sc","tur":"kavram","es":["stratokümülüs bulutu","stratocumulus cloud","Sc","stratokiymülüs","katmanlı küme bulut"],"tanim":["Genellikle yuvarlatılmış kütleler, yuvalar veya silindirler halinde gri veya beyazımsı tabaka oluşturan alçak bulut cinsi.","Tabanı 2 km yüksekliğin altında yer alır; yüzeye türbülansla bağlı olduğunda bulut tabanı z_LCL ≈ 0,125 km/K × (T − T_d) formülüyle bulunur.","Gemi bacası aerosolleri bu bulutlarda damla sayısını artırıp Twomey etkisiyle uydu görüntüsünde parlak gemi izleri meydana getirir."],"tanim_en":"A low cloud genus composed of gray or whitish sheets with rounded elements and a base below 2 km.","bag":{"kavram":["lcl-lfc","bulut-tur"],"soru":["S13"],"hesap":[]}},{"id":"stratus","tr":"Stratus","en":"stratus","kisa":"St","tur":"kavram","es":["stratus bulutu","stratus cloud","St","katman bulut","alçak stratus"],"tanim":["Oldukça tekdüze bir tabana sahip, çisenti, buz prizması veya kar taneciği bırakabilen, genellikle gri alçak bulut katmanı.","Tabanı yerden 2 km yüksekliğe kadar uzanan alçak katmanda bulunur; Güneş arkasından görüldüğünde çevresi net seçilebilir ve hale oluşturmaz.","Kararlı sınır katmanında yerin ışınımla soğuması ya da nemli havanın soğuk yüzey üzerine taşınması (adveksiyon) sonucu oluşur; konvektif kökenli olmadığından tabanı doğrudan yüzey parselinin LCL seviyesine karşılık gelmez."],"tanim_en":"A low cloud genus forming an extensive gray sheet with a uniform base capable of producing drizzle or snow grains.","bag":{"kavram":["lcl-lfc","bulut-tur","sis"],"soru":["S11","S12","S14","S23"],"hesap":[]}},{"id":"dew-point-lapse-rate","tr":"Çiğ noktası azalma oranı","en":"dew-point lapse rate","kisa":"Γ_Td","tur":"olcu","es":["çiğ noktası düşme hızı","1.8 K/km","dew-point lapse","Çiğ noktası düşüş oranı","Gamma_Td","Γ_Td"],"tanim":["Doymamış bir hava parseli adyabatik yükselirken basınç düşüşüne bağlı olarak çiğ noktası sıcaklığının yükseklikle azalma oranı.","Birimi K/km olup doymamış hava için tipik değeri yaklaşık 1,8 K/km kabul edilir.","Kuru adyabatik düşüş oranıyla (9,8 K/km) olan farkı (≈ 8 K/km) üzerinden LCL katsayısının (0,125 km/K) türetilmesinde temel değişkendir."],"tanim_en":"The rate of dew point decrease with height for an unsaturated ascending air parcel, typically taken as 1.8 K/km.","bag":{"kavram":["lcl-lfc","ciy-don"],"soru":["S14"],"hesap":["kaldir-z"]}},{"id":"condensation","tr":"Yoğuşma","en":"condensation","kisa":"","tur":"surec","es":["kondenzasyon","yoğunlaşma","su buharı yoğuşması","condensation process","buhar yoğuşması"],"tanim":["Su buharının gaz halinden sıvı hale geçişini ifade eden faz değişimi süreci.","Bağıl nem doyma düzeyine (%100) ulaştığında açığa çıkan gizli ısı (Lv ≈ 2,5×10⁶ J/kg) ortam havasını ısıtır.","Yükselen havanın LCL seviyesinde doymasıyla başlar ve sıcaklık düşüş oranını kuru adyabatik değerden nemli adyabatik değere (Γs ≈ 4–7 K/km) düşürür."],"tanim_en":"The physical transition of water vapor into liquid water with latent heat liberation.","bag":{"kavram":["lcl-lfc","theta-e","theta"],"soru":["S3","S4","S8","S16","S17","S40"],"hesap":["kaldir-z"]}},{"id":"intermediate-regime","tr":"Ara rejim","en":"intermediate regime","kisa":"k₂","tur":"kavram","es":["geçiş rejimi","intermediate flow regime","k2 katsayısı","k_2","k2","ara rejim hız katsayısı"],"tanim":["Yarıçapı 40 µm ile 0,6 mm arasındaki bulut ve yağmur damlalarının düşüşünde geçerli olan akış rejimidir.","Limit düşme hızı yarıçapla doğrusal orantılıdır (w_T = k₂ R) ve katsayı k₂ = 8×10³ s⁻¹ alınır.","Çarpışma-birleşme sürecinde damla yarıçapının zamana göre üstel büyümesini sağlayarak sıcak yağmur gelişimini hızlandırır."],"tanim_en":"The terminal fall velocity regime for droplets with radii between 40 µm and 0.6 mm where falling speed varies linearly with radius.","bag":{"kavram":["limit-hiz","carpisma"],"soru":["S41","S42"],"hesap":["carpisma"]}},{"id":"large-drop-regime","tr":"Büyük damla rejimi","en":"large-drop regime","kisa":"k₃","tur":"kavram","es":["türbülanslı rejim","large droplet regime","basık damla rejimi","large droplet fall regime","k3 katsayısı","k_3"],"tanim":["Yarıçapı 0,6 mm ile 2 mm arasındaki yağmur damlalarının aerodinamik sürüklenme altında düştüğü akış rejimidir.","Limit düşme hızı yarıçapın kareköküyle orantılıdır (w_T = k₃ √R) ve katsayı k₃ = 220 m^½ s⁻¹ alınır.","Damla tabanının aerodinamik basınçla yassılaşması ve arkasında oluşan girdaplar nedeniyle sürtünme katsayısının yaklaşık sabit kalmasını yansıtır."],"tanim_en":"The terminal velocity regime for raindrops with radii between 0.6 mm and 2 mm where falling speed is proportional to the square root of radius.","bag":{"kavram":["limit-hiz"],"soru":["S41"],"hesap":["limit-hiz"]}},{"id":"drag-coefficient","tr":"Sürtünme katsayısı","en":"drag coefficient","kisa":"C_D","tur":"olcu","es":["sürüklenme katsayısı","sürükleme katsayısı","direnç katsayısı","C_D"],"tanim":["Düşen bir hidrometeora etkiyen aerodinamik sürükleme kuvvetini akışkanın dinamik basıncına ve damla kesit alanına bağlayan boyutsuz sayıdır.","Reynolds sayısı Re ≲ 1 olan Stokes akışında C_D = 24/Re iken yüksek Reynolds sayılarında ve büyük damlalarda yaklaşık sabit bir değere yaklaşır.","Damlanın ağırlığı ile sürükleme kuvveti dengelendiğinde ulaşılan limit düşme hızının büyüklüğünü ve hız rejimlerini belirler."],"tanim_en":"A dimensionless parameter that quantifies the aerodynamic resistance encountered by a hydrometeor moving through air.","bag":{"kavram":["limit-hiz"],"soru":["S41"],"hesap":["limit-hiz"]}},{"id":"dynamic-viscosity","tr":"Dinamik viskozite","en":"dynamic viscosity","kisa":"η","tur":"olcu","es":["havanın dinamik viskozitesi","eta","akışmazlık katsayısı"],"tanim":["Bir akışkanın kayma gerilimi altında deformasyona karşı gösterdiği iç direncin ölçüsü.","Havanın dinamik viskozitesi yaklaşık 1,8×10⁻⁵ Pa s mertebesinde olup sıcaklıkla değişir.","Küçük bulut damlalarının Stokes rejimindeki aerodinamik sürüklenme direncini ve limit düşme hızını belirler."],"tanim_en":"A measure of the internal resistance of a fluid to deformation under shear stress.","bag":{"kavram":["limit-hiz"],"soru":[],"hesap":["limit-hiz"]}},{"id":"reynolds-number","tr":"Reynolds sayısı","en":"Reynolds number","kisa":"Re","tur":"olcu","es":["Re sayısı","damla Reynolds sayısı","Re"],"tanim":["Akışkan hareketinde atalet kuvvetlerinin viskoz kuvvetlere oranını ifade eden boyutsuz büyüklük.","Bulut damlalarında yarıçap 10 µm iken yaklaşık 0,016, yarıçap 40 µm iken yaklaşık 1 değerini alır.","Kitapta akış rejiminin sınırını belirler; Re ≲ 1 kaldığı sürece Stokes yasası geçerlidir."],"tanim_en":"A dimensionless number expressing the ratio of inertial forces to viscous forces in a fluid flow.","bag":{"kavram":["limit-hiz"],"soru":[],"hesap":["limit-hiz"]}},{"id":"aerodynamic-drag","tr":"Aerodinamik sürüklenme","en":"aerodynamic drag","kisa":"","tur":"surec","es":["sürüklenme","drag force","hava direnci","eylemsizlik sürüklenmesi","form direnci","Atalet sürüklenmesi"],"tanim":["Akışkan içindeki bir cismin hareketine karşı bağıl akış yönünde etki eden direnç kuvveti.","Küçük damlacıklarda (Re ≲ 1, R < 40 µm) Stokes sürüklenmesi F_D = 6πηRw bağıntısıyla hesaplanırken büyük damlalarda atalet etkisiyle doğrusal ve karekök rejimlerine geçer.","Düşen bulut ve yağmur damlalarında yerçekimi kuvvetini dengeleyerek damlanın sabit bir limit düşme hızına ulaşmasını sağlar."],"tanim_en":"The retarding force exerted by air on a falling precipitation particle in the direction of relative flow.","bag":{"kavram":["limit-hiz","cape"],"soru":["S10","S23","S41"],"hesap":[]}},{"id":"stokes-law","tr":"Stokes yasası","en":"Stokes' law","kisa":"","tur":"yontem","es":["Stokes sürtünmesi","Stokes drag law","Stokes sürüklenmesi","Stokes direnç formülü","Stokes' drag law","küçük damla rejimi"],"tanim":["Düşük Reynolds sayılarında laminer akış içindeki küçük küresel parçacıklara etki eden akışkan viskoz sürüklenme kuvvetini açıklayan fiziksel yasa.","Yarıçapı 40 µm altındaki bulut damlacıkları için katsayı k₁ = 1,19×10⁸ m⁻¹ s⁻¹ olup düşme hızı yarıçapın karesiyle orantılı olarak hesaplanır.","Bulut fiziğinde küçük damlaların limit düşme hızını doğrudan türetmek ve çarpışma öncesi bağıl hareketi modellemek için temel alınır."],"tanim_en":"A physical law stating that the drag force on a spherical particle in laminar flow is proportional to fluid viscosity, particle radius, and fall velocity.","bag":{"kavram":["limit-hiz"],"soru":["S41"],"hesap":["limit-hiz"]}},{"id":"median-cloud-size","tr":"Konum parametresi (medyan bulut boyu)","en":"location parameter (median cloud size)","kisa":"L_x","tur":"olcu","es":["medyan çap","medyan boyut","Lx","medyan bulut boyu","L_x","konum parametresi"],"tanim":["Bulut boyu dağılımında bölgedeki bulutların yarısının kendisinden daha küçük boyutta olduğu lognormal konum parametresi.","Sembolü L_x olup birimi km cinsindendir; atmosferik gözlemlerde tipik değeri 1 km mertebesinde kalır.","Dağılım eğrisinde ln(X/L_x) logaritmasını sıfırlayarak üstel terimi 1 yapar ve tepe frekansa sahip mod değerinden büyük kalır."],"tanim_en":"The lognormal location parameter representing the median cloud dimension where half of the cloud population is smaller.","bag":{"kavram":["lognormal"],"soru":["S15"],"hesap":["lognormal"]}},{"id":"sym-shape-parameter","tr":"Yayılım parametresi","en":"spread parameter (lognormal)","kisa":"S_x","tur":"olcu","es":["Sx","S_x","dispersion parameter","boyutsuz yayılım"],"tanim":["Lognormal bulut boyu dağılımında boyut logaritmasının standart sapmasını ifade eden boyutsuz yayılım parametresi.","Sembolü S_x olup boyutsuzdur; bulut boyutu dağılımlarında tipik değeri 0,5 kabul edilir.","Değeri büyüdükçe bulut boylarındaki çeşitlilik artar, dağılımın sağa çarpıklığı belirginleşir ve mod boyutu medyan boyuttan daha çok uzaklaşır."],"tanim_en":"The dimensionless parameter equal to the standard deviation of the natural logarithm of cloud size in a lognormal distribution.","bag":{"kavram":["lognormal"],"soru":["S15"],"hesap":["lognormal"]}},{"id":"sym-x-mod","tr":"Mod bulut boyu","en":"modal cloud size","kisa":"X_mod","tur":"olcu","es":["X_mod","mod boy","modal diameter","en sık görülen çap"],"tanim":["Lognormal bulut boyu olasılık yoğunluk fonksiyonunun tepe noktasına karşılık gelen en sık görülen bulut boyutu.","Sembolü X_mod olup birimi km cinsindendir; X_mod = L_x exp(−S_x²) bağıntısıyla hesaplanır.","Bulut dağılımı sağa çarpık olduğundan küçük bulutların frekansı daha yüksektir ve mod boyutu daima medyan değerin solunda kalır."],"tanim_en":"The cloud size corresponding to the peak of the lognormal size distribution, representing the most frequently observed cloud dimension.","bag":{"kavram":["lognormal"],"soru":["S15"],"hesap":["lognormal"]}},{"id":"drop-size-distribution","tr":"Damla boy dağılımı","en":"drop size distribution","kisa":"DSD","tur":"kavram","es":["damlacık boyutu dağılımı","DSD","damla boyutu dağılımı","N(D)","boy dağılımı fonksiyonu","sayı yoğunluğu dağılımı"],"tanim":["Birim hava hacminde bulunan damlaların sayı yoğunluğunun damla çapına veya yarıçapına bağlı değişimini gösteren istatistiksel dağılım fonksiyonu.","Çoğunlukla m⁻³ mm⁻¹ birimiyle tanımlanır ve yağmur damlaları için en yaygın olarak üstel Marshall–Palmer biçimi kullanılır.","Bulutun mikrofiziksel evrimini, radar yansıma faktörünü ve yeryüzüne ulaşan yağış hızını belirlemede temel kabul edilir."],"tanim_en":"The number concentration of drops per unit volume of air and per unit size interval, as a function of drop diameter.","bag":{"kavram":["mp"],"soru":["S44","S46"],"hesap":[]}},{"id":"drop-diameter","tr":"Damla çapı","en":"drop diameter","kisa":"D","tur":"olcu","es":["damla boyutu","yağmur damlası çapı","droplet diameter"],"tanim":["Küresel veya basık küremsi biçimdeki bir bulut veya yağmur damlasının merkezinden geçen en büyük doğrusal genişlik ölçüsü.","Yağmur damlalarında tipik olarak mm birimiyle ve 0,5–5 mm aralığında ifade edilir.","Marshall–Palmer dağılımında bağımsız değişken olup Rayleigh saçılmasında radar yansıması bu büyüklüğün altıncı kuvveti (D⁶) ile ölçeklenir."],"tanim_en":"The linear distance across the center of a cloud droplet or falling raindrop.","bag":{"kavram":["mp","radar"],"soru":["S44","S46"],"hesap":["mp"]}},{"id":"intercept-parameter","tr":"Kesişim parametresi","en":"intercept parameter","kisa":"N₀","tur":"olcu","es":["Marshall Palmer kesişim parametresi","kesme parametresi","N0 parametresi","intercept value","N0","N_0"],"tanim":["Marshall–Palmer damla boy dağılımı fonksiyonunun sıfır çap noktasındaki kuramsal sayı yoğunluğu değeri.","Standart Marshall–Palmer bağıntısında yağış hızından bağımsız sabit bir katsayı olarak N₀ = 8000 m⁻³ mm⁻¹ değerini alır.","Yarı-logaritmik grafikte dağılım doğrusunun düşey ekseni kestiği noktadır; toplam damla sayısı N_T = N₀/Λ olur."],"tanim_en":"The theoretical value of droplet number concentration at zero diameter in an exponential size distribution.","bag":{"kavram":["mp"],"soru":["S44"],"hesap":["mp"]}},{"id":"median-volume-diameter","tr":"Medyan hacim çapı","en":"median volume diameter","kisa":"D₀","tur":"olcu","es":["medyan damla çapı","mass median diameter","hacimsel medyan çap","D0 çapı","D0","D_0"],"tanim":["Bir yağış hacmindeki toplam sıvı su miktarını iki eşit parçaya bölen karakteristik damla çapı.","Toplam sıvı suyun yarısı bu değerden küçük damlacıklarda, diğer yarısı ise daha büyük damlalarda yer alır.","Marshall–Palmer dağılımında D₀ = 3,67/Λ bağıntısıyla hesaplanır ve yağışın baskın damla boyutunu gösterir."],"tanim_en":"The droplet diameter such that half the total liquid water volume is contained in drops of smaller diameter.","bag":{"kavram":["mp"],"soru":["S44"],"hesap":["mp"]}},{"id":"slope-parameter","tr":"Eğim parametresi","en":"slope parameter","kisa":"Λ","tur":"olcu","es":["Marshall Palmer eğim parametresi","dağılım eğimi","Marshall-Palmer eğimi","lambda","Lambda"],"tanim":["Marshall–Palmer damla boy dağılımında damla sayısının çapla üstel azalma oranını belirleyen eğim katsayısı.","Birimi mm⁻¹ olup doğrudan yağış hızına (RR) bağlıdır ve ampirik olarak Λ = 4,1 RR^(−0,21) bağıntısıyla bulunur.","Şiddetli yağışlarda küçülerek eğrinin yatıklaşmasını, böylece spektrumda iri damlaların payının artmasını sağlar."],"tanim_en":"The parameter determining the rate of exponential decay in droplet concentration with increasing diameter.","bag":{"kavram":["mp"],"soru":["S25","S44"],"hesap":["mp"]}},{"id":"total-drop-concentration","tr":"Toplam damla konsantrasyonu","en":"total drop concentration","kisa":"N_T","tur":"olcu","es":["toplam damla sayısı yoğunluğu","toplam damla derişimi","birim hacimdeki toplam damla","total drop number density","toplam damla sayısı","NT"],"tanim":["Birim hava hacminde bulunan tüm boyutlardaki bulut veya yağmur damlalarının toplam sayısını ifade eden sayı yoğunluğu.","Yağmur için birimi m⁻³ olup Marshall–Palmer dağılımının integralinden N_T = N₀/Λ eşitliğiyle hesaplanır.","Bulutun mikrofiziksel yapısını yansıtır; sıvı suyun kaç damla arasında bölüşüldüğünü gösterir."],"tanim_en":"The total number of cloud droplets or raindrops per unit volume of air integrated across the droplet size spectrum.","bag":{"kavram":["mp"],"soru":["S44"],"hesap":["mp"]}},{"id":"gamma-drop-distribution","tr":"Gama dağılımı","en":"gamma drop size distribution","kisa":"","tur":"yontem","es":["gama boy dağılımı","gamma distribution","gamma size distribution"],"tanim":["Yağmur ve bulut hidrometeorlarının boyut spektrumunu modellemek için kullanılan üç parametreli istatistiksel dağılım.","Biçimi N(D) = N₀ D^μ e^(−ΛD) olup μ = 0 için üstel (Marshall–Palmer) dağılıma indirgenir; μ > 0 iken küçük çaplarda damla sayısı azalır ve dağılım bir tepe yapar.","Konvektif yağışlarda ve mikrofizik parametrizasyonlarında damla konsantrasyonu ile radar yansımasını hesaplamada kullanılır."],"tanim_en":"A three-parameter size distribution, N(D) = N₀ D^μ exp(−ΛD), that generalizes the exponential (Marshall–Palmer) form and represents the deficit of small drops more realistically.","bag":{"kavram":["mp"],"soru":[],"hesap":["radar"]}},{"id":"kinematic-flux","tr":"Kinematik akı","en":"kinematic flux","kisa":"F","tur":"olcu","es":["kinematik nem akısı","kinematic moisture flux","kinematik buhar akısı"],"tanim":["Bir atmosferik büyüklüğün birim alandan birim zamanda taşınan kütlesel akısının hava yoğunluğuna bölünmesiyle tanımlanan akı büyüklüğü.","Nem taşınımında karışma oranı ile hızın çarpımı birimiyle ((kg/kg)(m/s)) ifade edilir ve F = −D (Δr/Δx) formülüyle hesaplanır.","Hava yoğunluğunun değişiminden arındırılmış olması nedeniyle sınır katmanı karışım hesaplarında doğrudan gradyanla çalışmayı kolaylaştırır."],"tanim_en":"A flux expressed in kinematic units, that is, the mass (dynamic) flux divided by air density; for moisture its unit is (kg/kg)(m/s).","bag":{"kavram":["nem-akisi"],"soru":["S35"],"hesap":["nem-akisi"]}},{"id":"weather-radar","tr":"Meteoroloji radarı","en":"weather radar","kisa":"","tur":"cihaz","es":["hava radarı","meteorological radar","radar","yağış radarı"],"tanim":["Atmosferdeki hidrometeorları tespit etmek, konumlandırmak ve yağış miktarını belirlemek amacıyla elektromanyetik dalgalar yayan ve yansıyan sinyali toplayan uzaktan algılama cihazı.","Dönüş sinyalinden türetilen radar yansıma çarpanı (Z), Rayleigh saçılması uyarınca damla çapının altıncı kuvvetiyle (D⁶) orantılıdır ve dBZ ile ifade edilir.","Bulut ve yağış fiziğinde yağış hızını (RR), fırtına yapısını ve aşırı hava olaylarını anlık izlemede kullanılır."],"tanim_en":"A remote sensing instrument that transmits electromagnetic radiation to detect, locate, and measure hydrometeors.","bag":{"kavram":["radar"],"soru":["S43","S44"],"hesap":["radar"]}},{"id":"hydrometeor","tr":"Hidrometeor","en":"hydrometeor","kisa":"","tur":"kavram","es":["bulut-yağış taneciği","su parçacığı","yağış tanesi","precipitation particle","hidrometeorlar"],"tanim":["Atmosferde asılı kalan, çöken, rüzgârla savrulan veya yeryüzündeki nesneler üzerinde biriken sıvı ya da katı su taneciklerinin genel adı.","Bulut damlası, yağmur, kar, dolu, çiy ve kırağı gibi tüm sıvı ve buz parçacıklarını kapsar.","Radar hacmindeki tanecik boyutu dağılımı (Z ∝ D⁶) ve hava paketlerinin hidrometeor yükü, yağış fiziğinde temel belirleyicidir."],"tanim_en":"Any liquid or solid water particle that is suspended in or falling through the atmosphere, blown by the wind, or deposited on objects on the ground.","bag":{"kavram":["radar","yagis-surec"],"soru":["S17","S43"],"hesap":[]}},{"id":"radar-reflectivity-factor","tr":"Radar yansıma çarpanı","en":"radar reflectivity factor","kisa":"Z","tur":"olcu","es":["yansıma çarpanı","radar reflectivity factor Z","Z faktörü","reflectivity factor Z"],"tanim":["Birim radar hacmindeki hidrometeorların eşdeğer küresel çaplarının altıncı kuvvetlerinin toplamı olan meteorolojik büyüklük.","Doğrusal birimi mm⁶ m⁻³ olup logaritmik ölçekte dBZ = 10 log₁₀ Z olarak ifade edilir.","Yağmur damlalarından geri saçılan radar gücünü belirler ve ampirik Z–R formülüyle yağış hızını kestirmede kullanılır."],"tanim_en":"The sum of the sixth powers of the equivalent diameters of all hydrometeors per unit volume.","bag":{"kavram":["radar","mp"],"soru":["S43"],"hesap":["radar"]}},{"id":"rainfall-rate","tr":"Yağış hızı","en":"rainfall rate","kisa":"RR","tur":"olcu","es":["yağış şiddeti","rain rate","precipitation rate","RR","R_rain"],"tanim":["Birim zamanda birim yatay alana düşen yağmur suyu yüksekliği veya hacmi.","Meteorolojide standart olarak mm/h birimiyle ölçülür ve radarda Marshall–Palmer Z–R ilişkisiyle (Z = 200 RR^1,6) tahmin edilir.","Damla boy dağılımının eğim parametresini (Λ) kontrol ederek bulut mikrofiziği ile yüzey hidrolojisi arasındaki bağı kurar."],"tanim_en":"The depth of liquid precipitation falling on a horizontal plane per unit time.","bag":{"kavram":["radar","mp","su-butcesi"],"soru":["S41","S43","S44","S45"],"hesap":["radar","mp"]}},{"id":"reflectivity-decibel","tr":"Desibel yansıma","en":"decibels of reflectivity (dBZ)","kisa":"dBZ","tur":"olcu","es":["dBZ değeri","radar yansıması","radar yansıma birimi","decibels relative to Z","yansıma desibeli"],"tanim":["Radar yansıma faktörünün (Z) standart 1 mm⁶ m⁻³ referans değerine oranının logaritmik ifadesi.","Hesap bağıntısı dBZ = 10 log₁₀ Z olup yağışlı atmosferde değerler çoğunlukla 0 ile 65 dBZ arasında kalır.","Geri saçılan radar sinyalinin çok geniş dinamik aralığını sıkıştırarak yağış şiddetini radar ekranlarında sınıflandırmayı sağlar."],"tanim_en":"A logarithmic scale expressing radar reflectivity factor relative to one millimeter to the sixth power per cubic meter.","bag":{"kavram":["radar","mp"],"soru":["S43"],"hesap":["radar"]}},{"id":"rayleigh-scattering","tr":"Rayleigh saçılması","en":"Rayleigh scattering","kisa":"","tur":"yontem","es":["Rayleigh saçılma rejimi","Rayleigh scattering regime"],"tanim":["Saçıcı parçacık çapının gelen elektromanyetik dalga boyundan çok daha küçük olduğu durumda gerçekleşen elastik saçılma rejimi.","Bu rejimde saçılan güç parçacık çapının altıncı kuvvetiyle (D⁶) doğru, dalga boyunun dördüncü kuvvetiyle (λ⁴) ters orantılıdır.","Meteoroloji radarlarında bulut ve yağmur damlalarından dönen sinyalin doğrudan Z faktörü ile modellenmesini sağlar."],"tanim_en":"Elastic scattering of electromagnetic radiation by particles that are much smaller than the incident wavelength.","bag":{"kavram":["radar"],"soru":[],"hesap":["radar"]}},{"id":"dilute-solution","tr":"Seyreltik çözelti","en":"Dilute solution","kisa":"","tur":"kavram","es":["seyreltik eriyik"],"tanim":["Çözünen madde miktarının çözücüye oranla çok az olduğu çözelti.","Çözünen mol sayısı suyun mol sayısından çok küçük olduğunda suyun mol kesri birinci mertebeden açılımla hesaplanır.","Bulut fiziğinde büyüyen çözelti damlalarında Raoult etkisini basitleştirerek Köhler denklemine aktarmada kullanılır."],"tanim_en":"A solution in which the concentration of solute is very low compared to the solvent.","bag":{"kavram":["raoult"],"soru":[],"hesap":[]}},{"id":"ideal-solution","tr":"İdeal çözelti","en":"Ideal solution","kisa":"","tur":"kavram","es":["Raoult çözeltisi"],"tanim":["Çözücü ve çözünen molekülleri arasındaki etkileşimlerin özdeş kabul edildiği ve her derişimde Raoult yasasına tam uyan kuramsal çözelti.","Denge buhar basıncı, saf çözücünün buhar basıncı ile çözücünün mol kesrinin çarpımına eşittir.","Bulut fiziğinde aerosollerin higroskopik büyümesini ve kritik bağıl nemini modellemede temel alınır."],"tanim_en":"A solution that obeys Raoult's law over the entire range of concentration.","bag":{"kavram":["raoult","higroskopik"],"soru":[],"hesap":[]}},{"id":"solute","tr":"Çözünen","en":"solute","kisa":"","tur":"kavram","es":["çözünen madde","solute substance"],"tanim":["Bir çözelti içinde çözücü faz içinde dağılmış ya da çözünmüş olan bileşen.","Atmosferde bulut yoğuşma çekirdeklerini oluşturan NaCl (M_s = 0,05844 kg/mol, van 't Hoff faktörü i = 2) ve amonyum sülfat gibi higroskopik aerosol tuzlarıdır.","Raoult yasasına göre suyun denge buhar basıncını düşürerek bulut damlacıklarının doymamış veya düşük aşırı doymuşlukta büyümesine imkan tanır."],"tanim_en":"A dissolved substance in a solution that acts to reduce the equilibrium vapor pressure according to Raoult's law.","bag":{"kavram":["raoult","higroskopik"],"soru":["S25","S26","S27","S30","S31","S33"],"hesap":["es","kohler"]}},{"id":"solvent","tr":"Çözücü","en":"solvent","kisa":"","tur":"kavram","es":["çözücü faz","solvent phase"],"tanim":["Bir çözelti içinde çözünen maddeyi çözündüren ve çözeltide genellikle baskın miktarda bulunan sıvı faz.","Bulut ve yağış fiziğinde atmosferik çözeltilerin ana çözücüsü sıvı sudur (H₂O, buharlaşma gizli ısısı Lv ≈ 2,5×10⁶ J/kg).","Çözünen aerosol tuzu eklendiğinde yüzeyden ayrılan su molekülü sayısı azalır ve çözeltinin denge buhar basıncı (e*) saf suyun eₛ değerinin altına düşer."],"tanim_en":"The liquid medium of a solution in which solute particles are dissolved, represented by water in cloud microphysics.","bag":{"kavram":["raoult","higroskopik"],"soru":[],"hesap":[]}},{"id":"equilibrium-vapor-pressure","tr":"Denge buhar basıncı","en":"equilibrium vapor pressure","kisa":"e*","tur":"olcu","es":["denge buhar gerilimi","e*","estar","damla buhar basıncı","denge basıncı","e_star"],"tanim":["Belirli bir sıcaklıkta, eğrilik ve çözünen derişimi içeren sıvı damlacık veya çözelti yüzeyi ile çevre buhar fazı arasındaki termodinamik denge durumundaki su buharı kısmi basıncı.","Kitapta e* sembolüyle ve kPa birimiyle gösterilir; düz saf su yüzeyine göre oranı e*/eₛ denge bağıl nemini verir.","Köhler eğrisinin temel değişkeni olup ortamdaki buhar basıncı e* değerinden büyük olduğunda damla difüzyonla büyür, küçük olduğunda buharlaşır."],"tanim_en":"The partial vapor pressure at which a curved solution droplet maintains thermodynamic equilibrium with surrounding water vapor.","bag":{"kavram":["raoult","kelvin","kohler"],"soru":["S24","S26","S27","S28","S30","S33"],"hesap":["kohler"]}},{"id":"mole-fraction","tr":"Mol kesri","en":"mole fraction","kisa":"x","tur":"olcu","es":["mol kesiri","molar fraction","çözeltideki su mol kesri","x_w","x_su","xw"],"tanim":["Bir karışımdaki veya çözeltideki belirli bir bileşenin mol sayısının, karışımdaki toplam mol sayısına oranı olan boyutsuz büyüklük.","Kitapta çözeltideki su için x_w sembolüyle gösterilir ve 0 ile 1 arasında değer alır.","Raoult bağıntısında buhar basıncı düşüşünü ifade eder; çözünen madde eklendikçe suyun mol kesri düşer ve damlacığın daha düşük bağıl nemde dengede kalmasını sağlar."],"tanim_en":"The dimensionless ratio of the amount of a given constituent to the total amount of all constituents in a solution.","bag":{"kavram":["raoult","higroskopik"],"soru":["S26","S27"],"hesap":["es"]}},{"id":"advection-fog","tr":"Adveksiyon sisi","en":"advection fog","kisa":"","tur":"kavram","es":["deniz sisi","advective fog","yatay taşınım sisi"],"tanim":["Ilık ve nemli bir hava kütlesinin daha soğuk bir yer veya su yüzeyi üzerinden yatay olarak geçerken alttan iletim ve türbülansla soğuyarak doyması sonucu oluşan sis türü.","Oluşumu ve dikey gelişimi için 3–9 kt aralığında rüzgâr idealdir; rüzgâr 9 kt üzerine çıktığında mekanik karışma nedeniyle stratus bulutuna dönüşür.","Genellikle deniz kıyılarında ve soğuk okyanus akıntıları üzerinde geniş alanları kaplar, ışınım sisinden daha kalıcıdır ve gündüz de varlığını sürdürebilir."],"tanim_en":"Fog formed by the horizontal movement of warm, moist air over a colder water or land area.","bag":{"kavram":["sis"],"soru":["S18","S19","S20","S21","S23"],"hesap":[]}},{"id":"frontal-fog","tr":"Cephe sisi","en":"frontal fog","kisa":"","tur":"kavram","es":["precipitation fog","yağış sisi","cephesel sis"],"tanim":["Cephe kuşaklarında ve cephe geçişlerinde, özellikle sıcak cephe eğiminden düşen ılık yağmur damlalarının alttaki soğuk ve kararlı hava katmanında buharlaşarak havayı doyurmasıyla oluşan sis.","Esas olarak soğuma yerine buharlaşmayla nem ekleme mekanizmasına dayanır; yağış altındaki soğuk hava katmanında çiy noktasını ortam sıcaklığına yükseltir.","WMO-No. 182 tanımı uyarınca cephe öncesi yağış sisi, cephe ardı sisi veya cephe kuşağındaki karışma sisi biçiminde gelişebilir."],"tanim_en":"Fog formed in a frontal zone when evaporation of falling raindrops moistens a cold air layer near the ground.","bag":{"kavram":["sis"],"soru":["S18"],"hesap":[]}},{"id":"ground-fog","tr":"Yer sisi","en":"ground fog","kisa":"","tur":"kavram","es":["sığ yer sisi","shallow fog"],"tanim":["Yere temas eden çok sığ bir katmanda meydana gelen, dikey kalınlığı az olup içinden Güneş veya yıldızların genellikle görülebildiği sığ ışınım sisi.","Rüzgârın 0–2 kt olduğu durumlarda mekanik karışma yetersiz kaldığı için soğuma sadece zeminle temas eden ilk metrelerde sınırlı kalır.","Kitapta ışınım sisi başlığı altında ele alınır; hafif türbülanslı karışma (3–7 kt) olmadıkça derin bir sis tabakasına dönüşemez ve zemin üzerinde sığ kalır."],"tanim_en":"A shallow radiation fog of small vertical extent through which the Sun or stars remain visible.","bag":{"kavram":["sis"],"soru":["S19","S23"],"hesap":[]}},{"id":"steam-fog","tr":"Buhar sisi","en":"steam fog","kisa":"","tur":"kavram","es":["tüten sis","arctic sea smoke","buharlaşma sisi","arktik deniz dumanı","arctic smoke","arktik buhar sisi"],"tanim":["Çok soğuk ve kuru bir hava kütlesinin kendisinden belirgin derecede daha ılık olan su yüzeyi üzerine gelmesiyle, buharlaşma ve izobarik karışma sonucu oluşan sis.","Ilık sudan hızla buharlaşan nem, soğuk tabaka ile karışarak aşırı doymuşluğa ulaşır ve dikey tüten dumanlar biçiminde yoğunlaşır.","Clausius–Clapeyron bağıntısının dışbükey yapısı nedeniyle iki doymamış hava kütlesinin karışım noktasının doyma eğrisinin üstünde kalması prensibiyle açıklanır; kutup denizlerinde arktik duman olarak adlandırılır."],"tanim_en":"Fog formed when cold air moves over relatively warm water and rapid evaporation with mixing brings the air to saturation.","bag":{"kavram":["sis","karisma"],"soru":["S18","S21"],"hesap":[]}},{"id":"upslope-fog","tr":"Yamaç sisi","en":"upslope fog","kisa":"","tur":"kavram","es":["orografik sis","yamaç boyunca yükselme sisi"],"tanim":["Nemli havanın rüzgâr etkisiyle dağ veya tepe yamacı boyunca zorlanmış yükselmesi ve adyabatik genleşmeyle soğuyarak doyması sonucu oluşan sis türü.","Yükselme sırasında hava parseli kuru adyabatik azalma oranıyla (Γd ≈ 9,8 K/km) soğur ve yoğuşma düzeyine ulaştığında sis tabanı başlar.","İzobarik soğumaya dayanan ışınım sisinin aksine adyabatik genleşme ve basınç düşüşü mekanizmasıyla çalışır; rüzgâr devam ettiği sürece dağın rüzgârüstü yamacında kalır."],"tanim_en":"Fog formed on windward terrain by the forced ascent of moist air leading to adiabatic cooling.","bag":{"kavram":["sis","kaldirma-mek"],"soru":["S18"],"hesap":[]}},{"id":"cold-air-pooling","tr":"Soğuk hava göllenmesi","en":"cold air pooling","kisa":"","tur":"surec","es":["vadi göllenmesi","cold pool","soğuk hava drenajı"],"tanim":["Açık ve sakin gecelerde yamaçlarda ışınımla soğuyan yoğun havanın yerçekimi etkisiyle drenaj akışı yaparak vadi ve çukur alanların tabanında birikmesi süreci.","Vadi tabanında güçlü bir yüzey terselmesi meydana getirerek kararlı bir soğuk hava katmanı oluşturur.","Çukur tabanında sıcaklığı hızla çiy noktasına düşürerek yoğun ışınım sisinin gelişmesine zemin hazırlar."],"tanim_en":"The accumulation of cold, dense air in valleys or topographic depressions driven by nocturnal radiative cooling and gravity drainage.","bag":{"kavram":["sis","terselme"],"soru":["S18"],"hesap":[]}},{"id":"fog-dissipation","tr":"Sisin dağılması","en":"fog dissipation","kisa":"","tur":"surec","es":["burn off","sisin yanması"],"tanim":["Görüş mesafesini 1 km altına düşüren bulut damlacıklarının buharlaşarak veya taşınarak atmosferik sis tabakasının ortadan kalkması süreci.","Temel olarak üç mekanizmayla gerçekleşir: Güneş ışınımı veya adveksiyonla ısınma, kuru hava karışımıyla nem kaybı ve kuvvetli türbülanslı karışma.","Yer yüzeyinin Güneş tarafından ısıtılmasıyla alttan başlayan buharlaşma sürecine literatürde güneşle dağılma (burn off) adı verilir."],"tanim_en":"The clearing or evaporation of fog droplets through solar heating, dry air entrainment, or strong turbulent mixing.","bag":{"kavram":["sis"],"soru":["S23"],"hesap":[]}},{"id":"turbulent-mixing","tr":"Türbülanslı karışma","en":"turbulent mixing","kisa":"","tur":"surec","es":["türbülans karışımı","düşey karışma"],"tanim":["Atmosfer sınır katmanında rastgele ve düzensiz girdap hareketleri aracılığıyla momentum, ısı ve su buharının düşey veya yatay doğrultuda etkin biçimde taşınması ve harmanlanması.","Işınım sisinde 3–7 kt şiddetindeki hafif türbülans soğumayı 10–30 m dikey katmana yayarak derin sis oluşturur; 9 kt üzerindeki güçlü türbülans ise sisi tabandan kaldırıp stratus bulutuna çevirir.","Bulut fiziğinde entrainment ve karışma sisi süreçlerinin temel itici mekanizması olup doyma buhar basıncının eğrisel doğası nedeniyle doymamış parselleri doygunluğa ulaştırabilir."],"tanim_en":"The transport and homogenization of heat, moisture, and momentum within the atmospheric boundary layer by irregular eddy motions.","bag":{"kavram":["sis","karisma"],"soru":["S19","S23"],"hesap":[]}},{"id":"precipitable-water","tr":"Yağışa geçebilir su","en":"precipitable water","kisa":"dW","tur":"olcu","es":["yagisa gecebilir su","dW","çökelebilir su","yoğuşabilir su"],"tanim":["Atmosferin düşey bir sütununda bulunan tüm su buharının yoğuşup yere yağış olarak indiği varsayıldığında elde edilecek toplam sıvı su derinliği.","Genellikle mm ya da kg m⁻² birimiyle ifade edilir ve radyosonde profillerinden dikey integral alınarak hesaplanır.","Katmanın su bütçesinde ve atmosferik nem zincirinde potansiyel yağış miktarının belirlenmesinde temel ölçüdür."],"tanim_en":"Total depth of liquid water resulting from the condensation of all water vapor contained in a vertical column of the atmosphere.","bag":{"kavram":["su-butcesi"],"soru":[],"hesap":["su-butcesi"]}},{"id":"precipitation-flux","tr":"Yağış akısı","en":"precipitation flux","kisa":"P_r","tur":"olcu","es":["yağış su akısı","yağmur akısı","yağış kütle akısı","rainfall flux","Pr","P_r"],"tanim":["Birim zamanda birim yatay alandan düşey doğrultuda geçen yağış suyu miktarı.","Sıvı su derinliği akısı cinsinden m s⁻¹ veya yoğunlukla çarpılarak kg m⁻² s⁻¹ birimleriyle ifade edilir.","Katmanın su bütçesinde üstten giren ve alttan çıkan yağış akıları farkı, katmandaki toplam su değişimini belirler."],"tanim_en":"The downward flux of precipitation water per unit area per unit time.","bag":{"kavram":["su-butcesi"],"soru":["S45"],"hesap":["su-butcesi"]}},{"id":"total-water-mixing-ratio","tr":"Toplam su karışma oranı","en":"total water mixing ratio","kisa":"r_T","tur":"olcu","es":["toplam nem karışma oranı","toplam su oranı","total mixing ratio r_T","rT","total mixing ratio","r_T"],"tanim":["Bir hava hacmindeki su buharı, sıvı su ve buz kütleleri toplamının kuru hava kütlesine oranı.","Birimi kg/kg ya da g/kg'dır; yağış düşmedikçe faz değişimlerinde korunan bir termodinamik değişkendir.","Euler katman su bütçesinde yağış akısı farkına bağlı olarak katmanın nemlenme veya kuruma hızını belirler."],"tanim_en":"The ratio of the total mass of water in all states (vapor, liquid and ice) to the mass of dry air.","bag":{"kavram":["su-butcesi"],"soru":["S45"],"hesap":["damla-boyu"]}},{"id":"advection","tr":"Adveksiyon","en":"advection","kisa":"","tur":"surec","es":["yatay taşınım","horizontal transport","advective transport"],"tanim":["Hava kütlesi özelliklerinin atmosferin hız alanı tarafından taşınması süreci.","Meteorolojide genellikle yatay taşınımı belirtir; adveksiyon sisi oluşumunda tipik rüzgâr hızı 3–9 kt aralığındadır.","Bulut fiziğinde nem ve sıcaklık taşınımını temsil eder; basit tek boyutlu su bütçesi modellerinde ihmal edilebilir."],"tanim_en":"The transfer of air mass properties by the velocity field of the atmosphere.","bag":{"kavram":["su-butcesi"],"soru":["S18","S19","S20","S21","S23","S45"],"hesap":[]}},{"id":"downdraft","tr":"Aşağı hava akımı","en":"downdraft","kisa":"","tur":"surec","es":["iniş hamlesi","aşağı akım","descending air current","çöküntü akımı"],"tanim":["Konvektif bir bulut içinde gelişen, yer seviyesine doğru yönelmiş düşey hava hareketi.","Yağış parçacıklarının sürtünme yükü ve bulut altındaki doymamış havada buharlaşması sonucu oluşan soğuma ile tetiklenir.","Hava kütlesinin negatif kaldırma kuvveti kazanmasına yol açarak yere ulaştığında kuvvetli hamleli rüzgârlara neden olur."],"tanim_en":"A downward current of air within a convective cloud driven by precipitation drag and evaporative cooling.","bag":{"kavram":["su-butcesi","kaldirma"],"soru":["S45"],"hesap":[]}},{"id":"turbulence","tr":"Türbülans","en":"turbulence","kisa":"","tur":"surec","es":["çalkantı","atmospheric turbulence"],"tanim":["Havanın ortalama hareketi üzerine binen, rastgele ve sürekli değişen hava hareketleri.","Atmosfer sınır katmanında momentum, ısı ve nemin düşey karışmasını sağlar; kümülüs ve stratokümülüs bulutlarını yüzeye bağlar.","Basit su bütçesi modellerinde analizi yalınlaştırmak amacıyla türbülanslı nem taşınımı ihmal edilir."],"tanim_en":"Random and continuously changing air motions superposed on the mean motion of the air.","bag":{"kavram":["su-butcesi"],"soru":["S17","S19","S23","S41","S45"],"hesap":[]}},{"id":"eulerian-framework","tr":"Euler yaklaşımı","en":"Eulerian approach","kisa":"","tur":"yontem","es":["kutu modeli","sabit kontrol hacmi","Euler bakışı","Eulerian framework"],"tanim":["Akışkan hareketini ve termodinamik özellikleri uzayda sabit bir kontrol hacmi üzerinden inceleyen analiz yöntemi.","Akışkan parselini zaman boyunca takip etmek yerine, sabit bir katmana giren ve çıkan kütle akılarını hesaba katar.","Bulut fiziğinde bir hava katmanının yağış ve buharlaşmaya bağlı su bütçesi değişimini belirlemede kullanılır."],"tanim_en":"A framework where atmospheric variables are evaluated within a fixed spatial control volume rather than following moving air parcels.","bag":{"kavram":["su-butcesi"],"soru":["S45"],"hesap":["su-butcesi"]}},{"id":"air-mass","tr":"Hava kütlesi","en":"air mass","kisa":"","tur":"kavram","es":["hava kütleleri","hava parseli kütlesi","air parcel mass"],"tanim":["Yatay yönde sıcaklık ve nem gibi fiziksel özellikleri geniş mesafeler boyunca oldukça homojen ve sürekli kalan çok geniş atmosfer gövdesi.","Yatayda milyonlarca kilometrekarelik bir alana ve dikeyde birkaç kilometrelik derinliğe yayılabilir.","Farklı özelliklere sahip iki kütle karşılaştığında sınırlarında cephe oluşturur; izobarik karışmaları ise karışma sisine yol açabilir."],"tanim_en":"An extensive body of the atmosphere whose physical properties such as temperature and humidity exhibit small horizontal variation.","bag":{"kavram":["terselme","karisma"],"soru":["S11"],"hesap":["ccn"]}},{"id":"anticyclone","tr":"Antisiklon","en":"anticyclone","kisa":"","tur":"kavram","es":["yüksek basınç","high-pressure system","yüksek basınç merkezi","high pressure area","antisiklonal sistem","yüksek basınç alanı"],"tanim":["Merkezinde çevresine göre yüksek atmosfer basıncı bulunan, rüzgârların Kuzey Yarımkürede saat yönünde saptığı geniş ölçekli hava sistemi.","Merkez bölgesinde havanın alçalması (çökme) nedeniyle adyabatik ısınma gerçekleşir ve genellikle bulutsuz, açık hava koşulları egemen olur.","Kış aylarında altında oluşan çökme ve yüzey ışınım terselmesi kirleticileri alt katmana hapsederek sis ve smog oluşumuna yol açar."],"tanim_en":"An atmospheric circulation system with high central pressure characterized by descending air and generally clear sky.","bag":{"kavram":["terselme","sis"],"soru":["S9","S11","S19"],"hesap":[]}},{"id":"capping-inversion","tr":"Kapak terselmesi","en":"capping inversion","kisa":"","tur":"kavram","es":["terselme kapağı","cap","lid","capping lid","lid inversion"],"tanim":["Konvektif sınır katmanının üzerinde yer alan ve alttan yükselen termiklerin dikey gelişimini sınırlayan kararlı sıcaklık terselmesi tabakası.","Termodinamik diyagramda konvektif inhibisyon (CIN) negatif alanı olarak görülür ve konvektif patlamayı geciktirir.","Yeterli yüzey ısınması veya zorlanmış yükselme ile aşıldığında altta biriken yüksek CAPE enerjisi serbest kalarak şiddetli fırtınalara yol açar."],"tanim_en":"A stable elevated temperature inversion layer that limits vertical convection until sufficient surface heating or lift occurs.","bag":{"kavram":["terselme"],"soru":["S7","S8","S9","S13","S19"],"hesap":["bulut-ortu"]}},{"id":"cumulus","tr":"Kümülüs","en":"cumulus","kisa":"Cu","tur":"kavram","es":["kümülüs bulutu","cumulus cloud","Cu","küme bulut","kümülas","Cu bulutu"],"tanim":["Genellikle yoğun ve keskin sınırlara sahip, kubbe veya kule biçiminde dikey gelişen, tepe kısmı karnabahara benzeyen ayrık bulut cinsi.","Güneş alan kısımları parlak beyaz, tabanı ise görece koyu ve neredeyse yataydır.","Yüzeye türbülansla bağlıdır; taban yüksekliği z_LCL ≈ 0,125 km/K × (T − T_d) formülüyle hesaplanır ve ılıman bölgelerde 2 km altında yer alır."],"tanim_en":"A detached, dense cloud with sharp outlines that develops vertically into domes or cauliflower-like towers with a nearly horizontal dark base.","bag":{"kavram":["terselme","bulut-tur","lcl-lfc"],"soru":["S7","S11","S12","S14","S15","S46"],"hesap":[]}},{"id":"frontal-inversion","tr":"Cephe terselmesi","en":"frontal inversion","kisa":"","tur":"kavram","es":["cephesel terselme","cephesel enverziyon","front inversion"],"tanim":["Yoğunluk farkı nedeniyle sıcak hava kütlesinin eğimli bir cephe yüzeyi boyunca soğuk havanın üstüne çıkmasıyla oluşan sıcaklık terselmesi.","Geçiş katmanında sıcak ve hafif havanın üstte, soğuk ve yoğun havanın altta konumlanmasıyla dikey sıcaklık gradyanı pozitiftir (dT/dz > 0).","Sıcak cephe eğimi boyunca geniş bir alana yayılır ve terselme katmanının üzerinde nimbostratus bulutları ile sürekli yağış oluşur."],"tanim_en":"A temperature inversion formed where warm air overrides colder, denser air along a frontal surface.","bag":{"kavram":["terselme","kaldirma-mek"],"soru":["S9"],"hesap":[]}},{"id":"longwave-radiation","tr":"Uzun dalga ışınım","en":"longwave radiation","kisa":"","tur":"kavram","es":["yer ışınımı","terrestrial radiation","termal kızılötesi ışıma","yer ışıması","uzun dalga ışınımı","radyatif soğuma"],"tanim":["Yeryüzü ve atmosfer tarafından termal kızılötesi dalga boylarında yayılan elektromanyetik radyasyon.","Açık ve sakin gecelerde yeryüzünden uzaya doğru net uzun dalga ışınım kaybı zemin sıcaklığının hızla düşmesine neden olur.","Bu radyatif soğuma yüzey terselmesine, havanın çiy noktasına kadar soğumasına ve ışınım sisinin başlamasına zemin hazırlar."],"tanim_en":"Thermal infrared radiation emitted by the ground and the atmosphere that governs nocturnal radiative cooling.","bag":{"kavram":["terselme","sis"],"soru":["S7","S9","S18","S19"],"hesap":[]}},{"id":"radiation-fog","tr":"Işınım sisi","en":"radiation fog","kisa":"","tur":"kavram","es":["radyasyon sisi","gece sisi","yer ışıması sisi"],"tanim":["Açık ve sakin gecelerde yer yüzeyinin uzun dalga ışınımla soğuması ve buna bağlı olarak temas eden havanın çiy noktasına ulaşmasıyla oluşan sis.","Oluşumu için 3–7 kt rüzgâr hızı idealdir; 0–2 kt rüzgârda sığ yer sisi kalırken, 8 kt üstündeki rüzgâr türbülanslı karışma nedeniyle sis oluşumunu engeller.","Sabah güneş ışınlarının zemini ısıtmasıyla tabandan itibaren buharlaşarak dağılır."],"tanim_en":"Fog produced by nocturnal radiational cooling of the ground that cools the adjacent air to saturation.","bag":{"kavram":["terselme","sis"],"soru":["S9","S18","S19","S23","S33"],"hesap":["isinim-sisi"]}},{"id":"radiation-inversion","tr":"Işınım terselmesi","en":"radiation inversion","kisa":"","tur":"kavram","es":["radyasyon terselmesi","gece ışıma enverziyonu","radyasyon enverziyonu","nocturnal inversion"],"tanim":["Açık ve sakin gecelerde yer yüzeyinin uzun dalga ışınımla soğuması sonucu yere değen havanın alttan soğumasıyla oluşan sıcaklık terselmesi (dT/dz > 0).","Alt katmanda güçlü bir statik kararlılık meydana getirerek dikey karışımı ve termik yükselmeleri durdurur.","Bulutlu veya rüzgârlı gecelerde bulutların uzun dalga ışınımı geri göndermesi ve rüzgârın alt katmanı karıştırması nedeniyle zayıf kalır veya hiç oluşmaz."],"tanim_en":"A nocturnal temperature inversion produced by radiational cooling of the ground that cools the adjacent air layer from below.","bag":{"kavram":["terselme"],"soru":["S9"],"hesap":[]}},{"id":"smog","tr":"Smog","en":"smog","kisa":"","tur":"kavram","es":["dumanlı sis","smoke and fog","hava kirliliği sisi","şehir dumanı","kış smogu","winter smog"],"tanim":["Duman ve sis sözcüklerinin birleşiminden türetilen, atmosferik kirleticiler ile sis damlacıklarının bir arada bulunduğu hava kirliliği durumu.","Kış aylarında antisiklonik yüksek basınç altındaki kuvvetli terselme katmanının kirleticileri yüzeye yakın hapsetmesiyle şiddetlenir.","Yatay görüş mesafesini 1 km altına düşürür ve kükürt dumanı gibi zararlı gazların aerosollerle birleşmesiyle insan sağlığını olumsuz etkiler."],"tanim_en":"A hazardous atmospheric mixture of smoke and fog trapped near the ground beneath a temperature inversion.","bag":{"kavram":["terselme","sis"],"soru":["S9"],"hesap":[]}},{"id":"stratosphere","tr":"Stratosfer","en":"stratosphere","kisa":"","tur":"kavram","es":["stratosfer katmanı","stratospheric layer","stratosfer tabakası"],"tanim":["Troposferin üstünde, tropopoz ile stratopoz arasında yer alan ve sıcaklığın ozonun morötesi ışınımı soğurması nedeniyle yükseklikle arttığı atmosfer katmanı.","Sıcaklığın yükseklikle artması (çevre azalma oranının negatif olması, Γ < 0) nedeniyle statik olarak mutlak kararlı bir tabakadır.","Güçlü kararlılığı sayesinde düşey hava hareketlerini bastırır; konvektif fırtına bulutlarının (Cb) tepe sınırını oluşturarak örs şeklinde yatay yayılmasına yol açar."],"tanim_en":"The atmospheric layer above the tropopause in which temperature is constant or increasing with height, owing to absorption of ultraviolet radiation by ozone; it is therefore very stable.","bag":{"kavram":["terselme","kararlilik"],"soru":["S9","S12","S17"],"hesap":[]}},{"id":"subsidence-inversion","tr":"Çökme terselmesi","en":"subsidence inversion","kisa":"","tur":"kavram","es":["alçalma terselmesi","subsident inversion","çökme enverziyonu","alçalma enverziyonu"],"tanim":["Antisiklon alanlarında geniş ölçekli havanın çökmesi ve adyabatik sıkışmayla ısınması sonucu alt ve orta seviyelerin üstünde oluşan sıcaklık terselmesi.","Alçalan katmanın alt seviyedeki daha soğuk hava tabakasının üzerine oturmasıyla dikey sıcaklık gradyanı tersine döner (dT/dz > 0).","Yüksek kararlılığa sahip bu tabaka bir kapak görevi görerek dikey hava hareketlerini, kümülüs gelişimini ve kirletici dağılımını bastırır."],"tanim_en":"A temperature inversion formed aloft when a large-scale descending air layer warms by adiabatic compression above cooler lower air.","bag":{"kavram":["terselme"],"soru":["S9","S11"],"hesap":[]}},{"id":"surface-inversion","tr":"Yüzey terselmesi","en":"surface inversion","kisa":"","tur":"kavram","es":["yer terselmesi","ground inversion","yer enverziyonu","surface-based inversion","yer seviyesi terselmesi"],"tanim":["Yere doğrudan temas eden en alt hava katmanında, sıcaklığın yükseklikle artış gösterdiği sığ atmosferik terselme tabakası.","Açık ve sakin gecelerde yer yüzeyinin net uzun dalga ışınım kaybıyla hızla soğuması ve bitişik hava katmanını alttan soğutmasıyla oluşur.","Düşey karışımı tamamen durdurarak yüzey yakınında radyasyon sisi oluşumunu ve hava kirliliği birikimini destekler."],"tanim_en":"A shallow temperature inversion formed directly adjacent to the ground when nocturnal longwave radiative cooling chills the lowest atmospheric layer from below.","bag":{"kavram":["terselme"],"soru":["S7","S9","S18"],"hesap":[]}},{"id":"tropopause","tr":"Tropopoz","en":"tropopause","kisa":"","tur":"kavram","es":["tropopoz seviyesi","tropopause boundary","tropopoz kapağı"],"tanim":["Troposfer ile stratosfer arasındaki sınır olup sıcaklık azalma oranında belirgin bir değişimin gerçekleştiği geçiş seviyesi.","Sıcaklık azalma oranının 2 °C/km veya altına indiği ve üstündeki 2 km boyunca bu değeri aşmadığı en alt seviye olarak belirlenir; potansiyel sıcaklık bu seviyede tipik olarak 330–380 K aralığına ulaşır.","Stratosferik kararlılığın başladığı bu seviye, konvektif hava hareketlerine ve fırtına bulutlarına (Cb) aşılmaz bir üst tavan oluşturur."],"tanim_en":"The boundary between the troposphere and the stratosphere where the lapse rate drops to 2 °C/km or less, creating an upper limit for deep convective clouds.","bag":{"kavram":["terselme","theta","bulut-tur"],"soru":["S9","S12"],"hesap":[]}},{"id":"visibility","tr":"Görüş mesafesi","en":"visibility","kisa":"VIS","tur":"olcu","es":["görüş uzaklığı","yatay görüş","meteorological visibility","meteorolojik görüş","VIS","görüş"],"tanim":["Gündüz uygun boyutlardaki koyu bir hedefin ufuk fonunda seçilip tanınabildiği en büyük yatay mesafe.","Havada asılı su damlacıkları, buz kristalleri veya aerosol partiküllerinin ışığı saçması ve soğurmasıyla azalır; birimi metre veya kilometredir.","Meteorolojide sis ile pus ayrımının temel ölçütüdür; yatay görüşün 1 km altına inmesi sis, 1 km ve üzerinde kalması pus olarak tanımlanır."],"tanim_en":"The greatest horizontal distance at which a dark target of suitable dimensions can be seen and recognized against the horizon sky.","bag":{"kavram":["terselme","sis","higroskopik"],"soru":["S23","S33"],"hesap":["gamma"]}},{"id":"radiative-cooling","tr":"Işınımla soğuma","en":"radiative cooling","kisa":"","tur":"surec","es":["radyatif soğuma","gece soğuması","yer ışıması ile soğuma","ışınımsal soğuma","net uzun dalga ışıma kaybı","terrestrial radiation cooling"],"tanim":["Yeryüzünün veya bir hava tabakasının yaydığı kızılötesi (uzun dalga) ışınımın soğurulan ışınımdan fazla olması nedeniyle net radyasyon kaybıyla sıcaklığının düşmesi süreci.","Açık ve sakin gecelerde zemin seviyesinde hava sıcaklığının düşüş hızını tipik olarak saatte yaklaşık 1,0 K düzeyine çıkarır.","Alt atmosferi alttan soğutarak yüzey terselmesi ve radyasyon sisi oluşumunu sağlayan temel termodinamik süreçtir."],"tanim_en":"A drop in temperature at the ground or within an air layer driven by a negative radiation balance where outgoing infrared emission exceeds absorption.","bag":{"kavram":["terselme","sis"],"soru":["S9","S18"],"hesap":[]}},{"id":"subsidence","tr":"Çökme","en":"subsidence","kisa":"","tur":"surec","es":["alçalma","descending air","düşey çökme","large-scale subsidence","subsident motion","çökme hareketi"],"tanim":["Antisiklonik yüksek basınç sistemlerinde geniş bir alana yayılan havanın yavaş ve geniş ölçekli düşey alçalma hareketi.","Alçalan hava kütlesi daha yüksek basınca maruz kalarak adyabatik sıkışmayla ısınır ve bağıl nemi düşer.","Atmosferde bulutların dağılmasına, açık hava koşullarına ve orta seviyelerde çökme terselmesi oluşarak dikey karışımın engellenmesine yol açar."],"tanim_en":"A slow, large-scale downward motion of an air layer typically associated with high-pressure systems, leading to adiabatic warming and cloud dissipation.","bag":{"kavram":["terselme"],"soru":["S9","S11","S23"],"hesap":[]}},{"id":"unit-kilopascal","tr":"Kilopaskal","en":"kilopascal","kisa":"kPa","tur":"birim","es":["kPa","basınç birimi","kilo-pascal","kilo pascal","1000 Pa"],"tanim":["Uluslararası Birimler Sisteminde (SI) 1000 paskala (10³ Pa ya da 10 hPa) eşit olan türetilmiş basınç birimi.","Kitapta atmosfer basıncı, referans basınç (P₀ = 100 kPa) ve su buharı kısmi basınçları (0 °C için e₀ = 0,611 kPa) için standart birim olarak kullanılır.","Termodinamik hesaplamalarda potansiyel sıcaklık ve Clausius–Clapeyron bağıntılarında basınç değişkenlerinin doğrudan tutarlı biçimde yazılmasını sağlar."],"tanim_en":"A metric unit of pressure equal to 1000 pascals, standard in atmospheric thermodynamics for ambient pressure and water vapor pressure.","bag":{"kavram":["theta","es-cc","difuzivite"],"soru":["S1","S3","S4","S20","S21","S34"],"hesap":["es"]}},{"id":"air-parcel","tr":"Hava parseli","en":"air parcel","kisa":"","tur":"kavram","es":["parsel","parcel","akışkan parseli","fluid parcel","yükselen hava parseli","doymuş hava"],"tanim":["Çevresinden yalıtılmış kabul edilen ve düşey hareketi sırasında adyabatik davrandığı varsayılan kuramsal küçük hava hacmi.","İçindeki sıcaklık, basınç ve nem gibi termodinamik özellikleri homojen kabul edilerek çevre ortam havasıyla kıyaslanır.","Parsel yöntemiyle atmosferik kararlılık, kaldırma kuvveti ivmesi ve bulut oluşum seviyelerinin (LCL, LFC) analizinde temel model birimi olarak kullanılır."],"tanim_en":"A hypothetical volume of air assumed to be thermally insulated from its environment and moving adiabatically during vertical displacement.","bag":{"kavram":["theta","kaldirma","kararlilik"],"soru":["S3","S5","S6","S8","S10","S20"],"hesap":[]}},{"id":"conserved-variable","tr":"Korunan değişken","en":"conserved variable","kisa":"","tur":"kavram","es":["korunan buyukluk","korunan büyüklük","conservative property","muhafaza edilen değişken","korunan özellik","korunumlu büyüklük"],"tanim":["Belirli bir termodinamik süreç veya faz değişimi boyunca değeri değişmeden sabit kalan fiziksel özellik veya büyüklük.","Kuru adyabatik süreçte potansiyel sıcaklık (θ), doymuş adyabatik süreçte eşdeğer potansiyel sıcaklık (θe), izobarik karışmada ise iç enerji ve su buharı kütlesi (T ve e) korunur.","Atmosferik süreçlerin matematiksel çözümünde ve hava kütlelerinin karışma hesaplarında temel korunum denklemlerinin kurulmasını sağlar."],"tanim_en":"A physical property of an air parcel that remains constant during a specific thermodynamic transformation or mixing event.","bag":{"kavram":["theta","theta-e","karisma"],"soru":["S3","S20"],"hesap":[]}},{"id":"isentrope","tr":"İzentrop","en":"isentrope","kisa":"","tur":"kavram","es":["eş entropi çizgisi","isentropic surface","sabit θ çizgisi","isentropic line"],"tanim":["Termodinamik diyagramda ya da atmosferik kesitte entropinin veya potansiyel sıcaklığın (θ) sabit olduğu hat veya yüzey.","Kuru hava için entropi s = c_p ln θ + sabit bağıntısıyla doğrudan potansiyel sıcaklığa bağlıdır; bu nedenle diyagramdaki kuru adyabat çizgileri birer izentroptur.","Doymamış ve adyabatik hareket eden hava parseli izentrop yüzeyi boyunca yer değiştirir."],"tanim_en":"A line or level of constant entropy, along which potential temperature remains constant during dry adiabatic motion.","bag":{"kavram":["theta"],"soru":[],"hesap":[]}},{"id":"air-density","tr":"Hava yoğunluğu","en":"air density","kisa":"ρ","tur":"olcu","es":["yoğunluk","kütle yoğunluğu","atmospheric density","kuru hava yoğunluğu","dry air density","ρ_d"],"tanim":["Birim hacimdeki havanın kütlesi.","SI birimi kg m⁻³ olup kuru hava ve su buharı kısmi yoğunluklarının toplamı (ρ = ρ_d + ρ_v) olarak ifade edilir.","Atmosferik kaldırma kuvveti ile parsel ivmelenmesini belirler ve sanal sıcaklık formülüyle (P = ρ ℜd Tᵥ) gaz durum denklemine bağlanır."],"tanim_en":"The mass of air per unit volume.","bag":{"kavram":["theta","tv","kaldirma"],"soru":["S2","S5","S17","S29","S33","S35"],"hesap":["damla-boyu","nem-akisi","su-butcesi"]}},{"id":"gas-constant-dry-air","tr":"Kuru hava gaz sabiti","en":"gas constant for dry air","kisa":"ℜd","tur":"olcu","es":["Rd","kuru hava ozgul gaz sabiti","özgül gaz sabiti","dry air gas constant","R_d sabiti"],"tanim":["Kuru havanın termodinamik durum denkleminde ve adyabatik bağıntılarda kullanılan özgül gaz sabiti.","Evrensel gaz sabitinin kuru havanın ortalama molar kütlesine oranıyla elde edilir ve kitapta ℜd = 287 J kg⁻¹ K⁻¹ kabul edilir.","Potansiyel sıcaklık hesabındaki Poisson üssünde (ℜd/c_p ≈ 0,28571) ve hidrostatik denge türetimlerinde temel parametredir."],"tanim_en":"The specific gas constant for dry air, defined as the universal gas constant divided by the mean molecular weight of dry air.","bag":{"kavram":["theta","tv"],"soru":["S3","S5"],"hesap":["kaldir-z","isobarik"]}},{"id":"mixing-ratio","tr":"Karışma oranı","en":"mixing ratio","kisa":"r","tur":"olcu","es":["karisma orani","su buharı karışma oranı","water vapor mixing ratio","nem karışma oranı","mixing ratio r","buhar karışma oranı r"],"tanim":["Nemli hava parselindeki su buharı kütlesinin kuru hava kütlesine oranı.","Boyutsuz olup SI birimi kg kg⁻¹ olarak belirtilir; meteorolojide yaygın olarak g kg⁻¹ cinsinden verilir ve tipik troposfer değeri 0,001–0,02 kg kg⁻¹ aralığında seyreder.","Yoğuşma veya buharlaşma gerçekleşmediği sürece parsel hareketi boyunca korunan bir büyüklüktür ve sanal sıcaklık formülünde havayı hafifletici etkiyi belirler."],"tanim_en":"The ratio of the mass of water vapor to the mass of dry air in a given moist air parcel.","bag":{"kavram":["theta","tv","nem-akisi"],"soru":["S2","S3","S4","S5","S35","S45"],"hesap":["theta","kaldir-z","tv","theta-e"]}},{"id":"poisson-constant","tr":"Poisson sabiti","en":"Poisson constant","kisa":"ℜd/c_p","tur":"olcu","es":["Rd/cp","kappa","Rd/cp oranı","Poisson exponent","Poisson üssü"],"tanim":["Kuru hava gaz sabitinin sabit basınçtaki özgül ısıya oranı (ℜd/c_p) olarak tanımlanan termodinamik üs sabiti.","İki atomlu gaz kabul edilen kuru hava için boyutsuz bir büyüklüktür ve kitapta değeri ℜd/c_p ≈ 0,28571 (yaklaşık 2/7) olarak alınır.","Kuru adyabatik süreçte basınç değişimine bağlı sıcaklık değişimini veren Poisson denkleminde ve potansiyel sıcaklık hesabında yer alır."],"tanim_en":"The dimensionless ratio of the gas constant for dry air to the specific heat at constant pressure, used as an exponent in adiabatic relations.","bag":{"kavram":["theta"],"soru":["S3"],"hesap":["theta"]}},{"id":"reference-pressure","tr":"Referans basınç","en":"reference pressure","kisa":"P₀","tur":"olcu","es":["standart referans basinc","P0","standart referans basıncı","base pressure","100 kPa basıncı","1000 hPa"],"tanim":["Termodinamik hesaplamalarda ve potansiyel sıcaklık tanımında temel alınan standart basınç düzeyi.","Meteorolojide ve kitapta potansiyel sıcaklık tanımı için standart değer P₀ = 100 kPa (1000 hPa) olarak kabul edilir.","Farklı yüksekliklerdeki hava parsellerinin termodinamik durumunu karşılaştırmak için adyabatik olarak indirildikleri ortak basınç seviyesini oluşturur."],"tanim_en":"A standard base pressure level, conventionally taken as 100 kPa (1000 hPa) in meteorology, to which an air parcel is adiabatically brought to define its potential temperature.","bag":{"kavram":["theta","difuzivite"],"soru":["S1","S3","S34"],"hesap":["theta"]}},{"id":"specific-heat-at-constant-pressure","tr":"Sabit basınçta özgül ısı","en":"specific heat at constant pressure","kisa":"c_p","tur":"olcu","es":["cp","sabit basınç özgül ısısı","isobaric specific heat","c_p özgül ısı","ozgul isi","kuru havanın sabit basınçtaki özgül ısısı"],"tanim":["Sabit basınç altında birim kütledeki havanın sıcaklığını bir Kelvin yükseltmek için gereken ısı enerjisi miktarı.","SI birimi J kg⁻¹ K⁻¹ olup kuru hava için kitapta standart değeri c_p ≈ 1004 J kg⁻¹ K⁻¹ kabul edilir.","Kuru adyabatik azalma oranının (Γd = g/c_p) paydasında ve birinci yasa entalpi türetimlerinde (dq = c_p dT − α dP) yer alır."],"tanim_en":"The amount of heat required to raise the temperature of a unit mass of dry air by one kelvin at constant pressure.","bag":{"kavram":["theta","gamma-s"],"soru":["S1","S3"],"hesap":["theta"]}},{"id":"dry-adiabatic-process","tr":"Kuru adyabatik süreç","en":"dry adiabatic process","kisa":"","tur":"surec","es":["dry adiabatic ascent","doymamış adyabatik süreç","kuru kaldirma","dry adiabatic lifting","kuru adyabatik kaldırma"],"tanim":["Doymamış bir hava parselinin çevresiyle ısı alışverişi yapmaksızın genleşerek soğuması veya sıkışarak ısınması süreci.","Bu süreç boyunca potansiyel sıcaklık (θ) ve karışma oranı (r) sabit kalırken parsel kuru adyabatik azalma oranıyla (Γd ≈ 9,8 K/km) soğur.","Parsel yükselirken bağıl nemi artar ve doyma düzeyine (LCL) ulaştığında yerini nemli adyabatik sürece bırakır."],"tanim_en":"A thermodynamic process of expansion or compression in an unsaturated air parcel without heat exchange with the environment.","bag":{"kavram":["theta","kuru-adyabat","kaldirma-mek"],"soru":["S3","S6","S8","S16"],"hesap":[]}},{"id":"first-law-of-thermodynamics","tr":"Termodinamiğin birinci yasası","en":"first law of thermodynamics","kisa":"","tur":"yontem","es":["termodinamik 1. yasa","enerji korunumu","first law"],"tanim":["Bir termodinamik sisteme verilen ısının sistemin iç enerjisindeki değişime ve yaptığı işe eşit olduğunu belirten enerji korunum ilkesi.","Atmosfer biliminde birim kütle ve entalpi biçimiyle dq = c_p dT − α dP denklemi olarak ifade edilir.","Adyabatik durumlarda (dq = 0) potansiyel sıcaklık ve kuru adyabatik azalma oranının, doymuş durumlarda ise gizli ısı salımıyla nemli adyabatın temel dayanağıdır."],"tanim_en":"The principle of conservation of energy stating that heat added to a system equals the change in internal energy plus work done by the system.","bag":{"kavram":["theta","gamma-s"],"soru":[],"hesap":["theta"]}},{"id":"ideal-gas-law","tr":"İdeal gaz yasası","en":"ideal gas law","kisa":"P = ρ R T","tur":"yontem","es":["ideal gaz denklemi","gaz durum denklemi","equation of state","durum denklemi","Ideal gas law"],"tanim":["Bir gazın basıncı (P), özgül hacmi (α = 1/ρ) ve mutlak sıcaklığı (T) arasındaki ilişkiyi P α = ℜ T denklemiyle veren durum denklemi.","Kuru hava için P = ρ ℜd T biçiminde yazılırken nemli havada su buharının etkisi sanal sıcaklık kullanılarak P = ρ ℜd Tᵥ formuna dönüştürülür.","Hidrostatik dengeyle birleştiğinde atmosferik basıncın yükseklikle üstel azalmasını tanımlayan hipsometrik bağıntının temelini oluşturur."],"tanim_en":"The equation of state relating pressure, specific volume, and temperature of a gas through the specific gas constant.","bag":{"kavram":["theta","tv","es-cc"],"soru":["S39"],"hesap":["theta"]}},{"id":"poisson-equation","tr":"Poisson denklemi","en":"Poisson's equation","kisa":"θ = T (P₀/P)^κ","tur":"yontem","es":["Poisson bagintisi","Poisson relation","Poisson bağıntısı","Poisson ilişkisi","Poisson adiabatic equation","Poisson equation"],"tanim":["Kuru havanın tersinir adyabatik genleşme ve sıkışmasında sıcaklık ile basınç arasındaki üstel ilişkiyi veren termodinamik bağıntı.","Bağıntıdaki Poisson üssü κ = ℜd/c_p ≈ 0,28571 değerinde olup iki atomlu ideal gaz için boyutsuzdur.","Parselin 100 kPa referans basıncındaki potansiyel sıcaklığını hesaplamakta ve kuru adyabat çizgisini tanımlamakta kullanılır."],"tanim_en":"An equation describing the temperature and pressure relationship for an ideal gas undergoing a reversible dry adiabatic change.","bag":{"kavram":["theta"],"soru":["S1","S3","S4"],"hesap":["theta"]}},{"id":"potential-instability","tr":"Potansiyel kararsızlık","en":"potential instability","kisa":"dθe/dz < 0","tur":"kavram","es":["konvektif kararsızlık","convective instability","katmansal kararsızlık"],"tanim":["Doymamış bir hava tabakasının bir bütün halinde doyana kadar yükseltildiğinde kararsız duruma geçmesi hali.","Katmanın eşdeğer potansiyel sıcaklığının yükseklikle azalması ile belirlenir.","Katmanın alt bölümü üstten daha nemli olduğunda yükselmeyle birlikte taban önce doyar ve sıcaklık gradyanı dikleşir."],"tanim_en":"The state of an unsaturated layer that becomes unstable when lifted as a whole until saturated; it occurs where equivalent potential temperature falls with height.","bag":{"kavram":["theta-e","kararlilik"],"soru":["S17"],"hesap":[]}},{"id":"latent-heat-of-vaporization","tr":"Buharlaşma gizli ısısı","en":"latent heat of vaporization","kisa":"Lᵥ","tur":"olcu","es":["buharlasma gizli isisi","Lv","buharlaşma gizil ısısı","latent heat of evaporation","buharlaşma ısısı","buharlaşma entalpisi"],"tanim":["Birim kütledeki suyun sabit sıcaklıkta sıvı halden buhar haline geçmesi sırasında soğurulan veya yoğuşurken salınan ısı miktarı.","Kitapta Lᵥ ≈ 2,5×10⁶ J/kg (Lᵥ/c_p ≈ 2490 K, Lᵥ/ℜᵥ = 5423 K) sabit değeriyle kullanılır.","Bulut içinde su buharı yoğuşurken açığa çıkarak parsele ek enerji sağlar ve nemli adyabatik azalma oranını düşürür."],"tanim_en":"The amount of thermal energy absorbed or released per unit mass when water changes between liquid and vapor states.","bag":{"kavram":["theta-e","gamma-s","es-cc"],"soru":["S4","S22","S25","S26"],"hesap":["theta-e"]}},{"id":"liquid-water-potential-temperature","tr":"Sıvı su potansiyel sıcaklığı","en":"liquid-water potential temperature","kisa":"θL","tur":"olcu","es":["sivi su potansiyel sicakligi","theta-L","θ_L","sıvı suyu hesaba katan potansiyel sıcaklık","theta_L"],"tanim":["Doymuş bir hava parselindeki mevcut sıvı suyun bütünüyle buharlaşması durumunda parselin sahip olacağı potansiyel sıcaklık.","Sıvı su karışma oranı terimi (r_L) kadar düzeltme içerir ve θL ≈ θ − (Lᵥ/c_p)(θ/T) r_L bağıntısıyla ifade edilir.","Sıvı su damlacıkları içeren bulutlu sınır katmanında ve doymuş adyabatik süreçlerde korunan değişkendir."],"tanim_en":"A conserved potential temperature for cloudy air: the potential temperature a parcel would have if all of its liquid water were evaporated.","bag":{"kavram":["theta-e"],"soru":["S4"],"hesap":["theta-e"]}},{"id":"evaporation","tr":"Buharlaşma","en":"evaporation","kisa":"","tur":"surec","es":["buharlaşma süreci","vaporization","su buharlaşması","damla buharlaşması","buharlaşım","evaporational loss"],"tanim":["Suyun kaynama noktasının altındaki bir sıcaklıkta sıvı fazdan buhar fazına dönüştüğü faz değişimi.","Süreç ortamdan Lᵥ ≈ 2,5×10⁶ J/kg buharlaşma gizli ısısı çeker ve havaya su buharı katar.","Bulut altındaki yağmur damlalarının buharlaşması virga ve aşağı hava akımı oluştururken ılık su üstündeki buharlaşma buhar sisini besler."],"tanim_en":"A transition wherein liquid water transforms into vapor at a temperature below boiling point.","bag":{"kavram":["theta-e","karisma","sis"],"soru":["S4","S18","S25","S29","S30","S45"],"hesap":["cc-iki"]}},{"id":"evaporative-cooling","tr":"Buharlaşma soğuması","en":"evaporative cooling","kisa":"","tur":"surec","es":["buharlasma sogumasi","buharlaşmayla soğuma","evaporation cooling","evaporatif soğuma"],"tanim":["Sıvı suyun buharlaşması için gereken gizli ısının çevredeki hava parselinden çekilmesi sonucu ortam sıcaklığının düşmesi.","Yoğuşan her bir kilogram suyun yeniden buharlaşması havadan yaklaşık 2,5×10⁶ J ısı çeker.","Bulut altındaki kuru katmanda buharlaşan yağmur damlaları virga oluşturur; buharlaşmayla soğuyan ve yoğunluğu artan hava aşağı hava akımlarını tetikler."],"tanim_en":"The temperature drop of an air volume resulting from heat extraction during water droplet evaporation.","bag":{"kavram":["theta-e","su-butcesi","kaldirma"],"soru":["S4","S17","S45"],"hesap":[]}},{"id":"unit-gram-per-kilogram","tr":"Gram bölü kilogram","en":"gram per kilogram","kisa":"g/kg","tur":"birim","es":["g/kg","g kg⁻¹","karışma oranı birimi","grams per kilogram"],"tanim":["Bir kilogram kuru hava başına düşen su buharı veya hidrometeor kütlesini gram birimiyle gösteren meteorolojik oran birimi.","Termodinamik bağıntılara konurken 1000'e bölünerek kg/kg boyutsuz değerine çevrilir.","Tipik buhar karışma oranı 1–20 g/kg (0,001–0,020 kg/kg) aralığında yer alır ve sanal sıcaklık formülünde yoğunluk katkısını belirler."],"tanim_en":"A metric unit expressing the mass of moisture or condensate in grams per kilogram of dry air.","bag":{"kavram":["tv","ccn","nem-akisi"],"soru":["S2","S3","S4","S5","S35","S45"],"hesap":[]}},{"id":"cloud-droplet","tr":"Bulut damlacığı","en":"cloud droplet","kisa":"","tur":"kavram","es":["bulut damlası","cloud drop","küçük bulut damlacıkları","Bulut damlası"],"tanim":["Bir bulut içinde yer alan, aşırı soğumuş veya sıvı haldeki, çapı yaklaşık 4 ile 100 µm arasında olan küçük su damlası.","Tipik yarıçapı ≈ 10 µm olup düşme limit hızı yaklaşık 1,2 cm/s mertebesinde kalır.","Köhler eğrisinde kritik aşırı doymuşluğu aşan aktive olmuş bulut yoğuşma çekirdekleri üzerinde difüzyonla büyüyerek oluşur."],"tanim_en":"A liquid or supercooled water drop in a cloud with a diameter ranging from about 4 to 100 micrometers.","bag":{"kavram":["tv","ccn","bulut-tur"],"soru":["S28","S29","S30","S33","S36","S41"],"hesap":[]}},{"id":"ice-crystal","tr":"Buz kristali","en":"ice crystal","kisa":"","tur":"kavram","es":["bulut buz kristali","cloud ice crystal","katı buz kristali","buz tanesi","buz kristalleri","kristal"],"tanim":["Atmosferde su buharının doğrudan buz olarak birikmesi (depozisyon) ya da aşırı soğumuş damlacıkların donmasıyla oluşan altıgen yapılı katı su parçacığı.","Biçimi sıcaklığa bağlıdır: 0 ile −4 °C levha, −4 ile −10 °C iğne ve sütun, −10 ile −22 °C levha ve dendrit (dendritler ≈ −15 °C), −22 °C altında sütun.","Karma fazlı bulutlarda buza göre doyma basıncının düşüklüğü sebebiyle Bergeron süreciyle damlalar aleyhine hızla büyür."],"tanim_en":"A solid particle of ice formed in the atmosphere exhibiting macroscopic hexagonal crystalline symmetry.","bag":{"kavram":["tv","buz-kutle","donma"],"soru":["S12","S37","S39","S40","S46"],"hesap":["buz-kutle"]}},{"id":"liquid-water-loading","tr":"Sıvı su yükü","en":"liquid-water loading","kisa":"","tur":"kavram","es":["sivi su yuku","water loading","damla yükü","su yükü","yoğuşan su yüklemesi","condensate loading"],"tanim":["Hava parseli içinde asılı duran sıvı su damlacıklarının parsel kütlesine fazladan ağırlık bindirmesi etkisi.","Sanal sıcaklıkta −r_L terimiyle yer alır ve parselin yoğunluğunu artırarak pozitif kaldırma kuvvetini zayıflatır.","Konvektif fırtınalarda yüksek sıvı su içeriği parsel ivmesini ve CAPE kaynaklı düşey hızı azaltır, aşağı yönlü akımları besler."],"tanim_en":"The negative buoyancy effect produced by the downward gravitational drag of suspended liquid droplets in an air parcel.","bag":{"kavram":["tv","kaldirma","cape"],"soru":["S2","S10"],"hesap":[]}},{"id":"partial-pressure","tr":"Kısmi basınç","en":"partial pressure","kisa":"","tur":"kavram","es":["buhar kısmi basıncı","partial vapor pressure","kısmi buhar basıncı"],"tanim":["İdeal gaz karışımında tek bir bileşenin aynı hacim ve sıcaklıkta tek başına bulunması durumunda uygulayacağı basınçtır.","Atmosferde su buharının kısmi basıncı e simgesiyle gösterilir ve birimi genellikle hektopaskal (hPa) ya da kilopaskal (kPa) olarak alınır.","Kuru hava ile su buharının kısmi basınçlarının toplamı toplam atmosfer basıncını verir ve bağıl nem hesabında temel değişkendir."],"tanim_en":"The pressure exerted by a single component in an ideal gas mixture at the same temperature and volume.","bag":{"kavram":["tv"],"soru":["S3"],"hesap":[]}},{"id":"water-vapor","tr":"Su buharı","en":"water vapor","kisa":"","tur":"kavram","es":["su buhari","buhar","atmosferik su buharı","moisture","su buharı gazı","water vapour"],"tanim":["Suyun gaz hâlindeki görünmez biçimidir; atmosferdeki başlıca sera gazı ve bulut oluşumunun ham maddesidir.","Gaz sabiti kuru havadan yüksek olduğundan nemli havayı kuru havaya kıyasla daha hafif yapar.","Yoğuşarak bulut ve sis damlacıklarına dönüştüğünde çevreye buharlaşma gizli ısısını verir."],"tanim_en":"Water in the gaseous state present within the atmosphere.","bag":{"kavram":["tv","es-cc"],"soru":["S18","S21","S22","S24","S27","S34"],"hesap":["drh"]}},{"id":"gas-constants-ratio","tr":"Gaz sabitleri oranı","en":"ratio of gas constants","kisa":"ε","tur":"olcu","es":["epsilon","Rd/Rv","Rd/Rv oranı","Mv/Md oranı","0.622 sabiti","molecular weight ratio"],"tanim":["Kuru havanın özgül gaz sabitinin su buharının özgül gaz sabitine oranıdır (Rd/Rv).","Boyutsuz bir büyüklük olup bulut fiziğinde ve termodinamikte yaklaşık 0,622 değerini alır.","Sanal sıcaklık formülündeki 0,61 katsayısının ve doyma karışma oranı bağıntılarının türetilmesinde temel sabittir."],"tanim_en":"The dimensionless ratio of the dry air gas constant to the water vapor gas constant, equal to approximately 0.622.","bag":{"kavram":["tv","gamma-s","es-cc"],"soru":[],"hesap":["theta","kaldir-z"]}},{"id":"ice-mixing-ratio","tr":"Buz karışma oranı","en":"ice mixing ratio","kisa":"r_I","tur":"olcu","es":["buz karisma orani","rI","buz kristali karışma oranı","ice water mixing ratio","r_I"],"tanim":["Bir hava parselindeki buz kristallerinin toplam kütlesinin kuru havanın kütlesine oranıdır.","Birimi kg/kg olup bulut içinde tipik değerleri 0 ile 0,002 kg/kg arasındadır; bulut dışındaki açık havada sıfırdır.","Karma fazlı bulutlarda parselin sanal sıcaklığını hesaplarken buz yükünün kaldırma kuvvetini azaltıcı etkisini temsil eder."],"tanim_en":"The ratio of the mass of ice crystals to the mass of dry air in an air parcel.","bag":{"kavram":["tv"],"soru":["S2"],"hesap":["tv"]}},{"id":"liquid-water-mixing-ratio","tr":"Sıvı su karışma oranı","en":"liquid water mixing ratio","kisa":"r_L","tur":"olcu","es":["sivi su karisma orani","rL","bulut suyu karışma oranı","cloud water mixing ratio","r_L"],"tanim":["Bir hava parseli içindeki sıvı su damlacıklarının toplam kütlesinin kuru havanın kütlesine oranıdır.","Birimi kg/kg olup bulut içinde tipik olarak 0 ile 0,003 kg/kg aralığındadır; bulut dışındaki açık havada sıfır kabul edilir.","Sanal sıcaklık hesabında sıvı su yükünü temsil ederek net kaldırma ivmesini azaltıcı yönde etki yapar."],"tanim_en":"The ratio of the mass of liquid water droplets to the mass of dry air in an air parcel.","bag":{"kavram":["tv","theta-e"],"soru":["S2","S4","S5"],"hesap":["tv","theta-e","kaldirma"]}},{"id":"molar-mass","tr":"Molar kütle","en":"molar mass","kisa":"M","tur":"olcu","es":["mol kütlesi","molecular weight","molekül ağırlığı","mol ağırlığı"],"tanim":["Bir kimyasal maddenin bir molünün kütlesidir.","Birimi g/mol ya da kg/mol olup kuru hava için yaklaşık 0,02897 kg/mol, su buharı için yaklaşık 0,01802 kg/mol değerini alır.","Özgül gaz sabitinin evrensel gaz sabitinden türetilmesinde ve Köhler eğrisinde çözünen aerosolün etkisini hesaplamada kullanılır."],"tanim_en":"The mass of a given chemical substance divided by the amount of substance in moles.","bag":{"kavram":["tv","cc-iki"],"soru":["S2","S5","S30","S31"],"hesap":["tv"]}},{"id":"water-vapor-gas-constant","tr":"Su buharı gaz sabiti","en":"gas constant for water vapor","kisa":"R_v","tur":"olcu","es":["Rv","özgül su buharı gaz sabiti","water vapor gas constant","su buharı özel gaz sabiti","özgül buhar gaz sabiti","R_v sabiti"],"tanim":["Evrensel gaz sabitinin su buharının molar kütlesine bölünmesiyle elde edilen özgül gaz sabitidir (Rv).","Değeri 461,5 J kg⁻¹ K⁻¹ olup kuru havanın gaz sabitinden (287 J kg⁻¹ K⁻¹) belirgin biçimde büyüktür.","Clausius–Clapeyron denkleminde doyma buhar basıncının sıcaklıkla değişim oranını ve nemli adyabatik azalma oranını belirlemede kullanılır."],"tanim_en":"The specific gas constant for water vapor, equal to approximately 461.5 J kg⁻¹ K⁻¹.","bag":{"kavram":["tv","es-cc","difuzivite"],"soru":[],"hesap":["theta"]}},{"id":"convective-precipitation","tr":"Konvektif yağış","en":"convective precipitation","kisa":"","tur":"kavram","es":["konvektif yağmur","convective rain","sağanak yağış"],"tanim":["Kararsız atmosfer koşullarında güçlü düşey konvektif hava hareketleri sonucu oluşan yağış türü.","Kümülonimbüs gibi dikey gelişimli bulutlardan düşer; kısa sürede yüksek yağış şiddeti ve ani başlangıç gösterir.","Damla spektrumunda iri damlalar barındırır ve radar yansımasında 50 dBZ üzerindeki değerlere ulaşabilir."],"tanim_en":"Precipitation generated by convective vertical motion in an unstable atmosphere.","bag":{"kavram":["yagis-surec","bulut-tur","radar"],"soru":["S43"],"hesap":[]}},{"id":"freezing-level","tr":"Donma seviyesi","en":"freezing level","kisa":"0 °C","tur":"kavram","es":["0 °C izotermi","zero-degree isotherm","erime seviyesi","melting level","0 °C seviyesi"],"tanim":["Atmosferde sıcaklığın 0 °C'ye (273,15 K) düştüğü irtifayı belirtir; çöken kar taneleri ile buz kristallerinin erimeye başladığı erime seviyesidir.","Radyosonde ölçümleri ve Skew-T diyagramı üzerinden metre veya basınç birimiyle saptanır.","Bulut mikrofiziğinde soğuk yağmur ile sıvı yağış bölgelerini ayıran temel sınırdır."],"tanim_en":"The atmospheric altitude where the temperature is 0 °C, defining the level at which descending ice crystals and snowflakes melt into rain.","bag":{"kavram":["yagis-surec","donma","bergeron"],"soru":["S4","S8","S21","S22","S28","S46"],"hesap":["ciy-don"]}},{"id":"graupel","tr":"Graupel","en":"graupel","kisa":"","tur":"kavram","es":["kar paleti","kar peleti","snow pellets","soft hail","yumuşak dolu"],"tanim":["Aşırı soğumuş bulut damlacıklarının düşen bir buz kristaline çarpıp anında donmasıyla (kırağılaşma) oluşan beyaz, opak ve gevrek buz taneleridir.","Çapı genellikle 2 ile 5 mm arasında değişir; konik veya küresel biçimlidir ve yere çarptığında kolayca ufalanır.","Soğuk bulut mikrofiziğinde kar kristalleri ile dolu arasında bir geçiş basamağı oluşturur ve fırtına bulutlarında dolu embriyosu işlevi görür."],"tanim_en":"An opaque, spherical or conical ice pellet formed when supercooled water droplets freeze upon collision with an ice crystal through riming.","bag":{"kavram":["yagis-surec"],"soru":[],"hesap":[]}},{"id":"hail","tr":"Dolu","en":"Hail","kisa":"GR","tur":"kavram","es":["dolu tanesi","hailstones","hailstone","iri buz hidrometeoru","iri dolu"],"tanim":["Genellikle 5 ile 50 mm çapında, saydam veya yarı saydam katmanlardan oluşan ve kümülonimbüs bulutlarından düşen buz küreleri veya parçaları biçimindeki yağıştır.","Güçlü yukarı hava akımı tanecikleri uzun süre aşırı soğumuş su bölgesinde tutar; tanecik çarptığı aşırı soğumuş damlacıkları dondurarak (ıslak ve kuru büyüme) katman katman büyür.","Radar gözlemlerinde iri boyutları ve katı fazları nedeniyle 55 dBZ ve üzeri çok yüksek yansıma değerleriyle kendini gösterir."],"tanim_en":"Precipitation of ice particles usually between 5 and 50 millimeters in diameter falling from cumulonimbus clouds.","bag":{"kavram":["yagis-surec","radar"],"soru":["S12","S27","S43","S46"],"hesap":[]}},{"id":"precipitation","tr":"Yağış","en":"precipitation","kisa":"","tur":"kavram","es":["yagis","yağışlar","atmosferik yağış","hydrometeors"],"tanim":["Bulutlardan düşerek yer yüzeyine ulaşan sıvı ya da katı hâldeki su tanecikleri topluluğudur.","Yoğuşmayla oluşan bulut damlacıkları ile depozisyonla oluşan buz kristalleri difüzyon, çarpışma-birleşme, kırağılanma ve topaklanmayla büyüyüp yerçekimine yenik düştüğünde başlar.","Birim yatay alana birim zamanda düşen su yüksekliği (mm ya da kg/m²) olarak ölçülür ve radar meteorolojisinde yansıma faktörü Z ile izlenir."],"tanim_en":"Any liquid or solid hydrometeor falling from clouds and reaching the ground.","bag":{"kavram":["yagis-surec"],"soru":["S12","S16","S33","S43","S45","S46"],"hesap":["kaldirma","radar","mp","su-butcesi"]}},{"id":"rain-shower","tr":"Sağanak","en":"shower","kisa":"SH","tur":"kavram","es":["sağanak yağış","rain shower","Convective shower","convective shower","sağanak yağmur"],"tanim":["Konvektif bulutlardan düşen, aniden başlayıp biten ve şiddeti hızla değişen yağıştır.","Genellikle kısa süreli olup gökyüzünün hızla açılıp kapanması ve yerel olarak kuvvetli yağmur bırakmasıyla tanınır.","Kararsız hava katmanlarında yüksek CAPE ve düşük CIN ortamında gelişen düşey hava hareketlerinin ürünüdür."],"tanim_en":"Precipitation of liquid water falling from convective clouds, characterized by sudden onset and rapid change of intensity.","bag":{"kavram":["yagis-surec"],"soru":["S10","S11","S12","S43"],"hesap":[]}},{"id":"virga","tr":"Virga","en":"Virga","kisa":"","tur":"kavram","es":["buharlaşan yağış izi","fallstreak","yere ulaşmayan yağış","virga yağışı","fall streaks","virga (yere ulaşmayan yağış)"],"tanim":["Bulut tabanına bağlı, yere ulaşmadan önce altındaki kuru hava katmanında buharlaşan ya da süblimleşen düşey veya eğik yağış izi.","Yağış damlalarının buharlaşması alt katmanı nemlendirir ve buharlaşma soğuması yoluyla aşağı yönlü hava hareketini tetikler.","Çoğunlukla sirrokümülüs, altokümülüs, altostratus, nimbostratus, stratokümülüs, kümülüs ve kümülonimbüs bulutlarında ek özellik olarak görülür."],"tanim_en":"Vertical or inclined trails of precipitation hanging from a cloud base that evaporate or sublimate before reaching the ground.","bag":{"kavram":["yagis-surec","su-butcesi"],"soru":["S14","S45"],"hesap":[]}},{"id":"melting","tr":"Erime","en":"melting","kisa":"","tur":"surec","es":["buz erimesi","melting of ice","kar erimesi","faz değişimi"],"tanim":["Buz ve kar gibi katı fazdaki hidrometeorların, sıcaklığın 0 °C (273,15 K) üzerine çıkmasıyla çevreden ısı alarak sıvı suya dönüşüm sürecidir.","Buzun erime gizli ısısı yaklaşık 3,3×10⁵ J/kg olup bu faz dönüşümü süresince ortam havasından ısı çekilir ve hava soğur.","Soğuk yağmur mekanizmasında donma seviyesi altına inen kar tanelerinin yağmura dönüşmesini sağlar ve radarda parlak bant katmanını oluşturur."],"tanim_en":"The thermodynamic transition in which ice or snow absorbs latent heat at 0 °C and turns into liquid water.","bag":{"kavram":["yagis-surec","bergeron"],"soru":["S24","S46"],"hesap":[]}},{"id":"steady-precipitation","tr":"Sürekli yağış","en":"Steady precipitation","kisa":"","tur":"surec","es":["aralıksız yağış","continuous rain","steady rain","sürekli yağmur"],"tanim":["Geniş bir alana yayılan, şiddeti ani dalgalanmalar göstermeyen ve uzun süre kesintisiz süren yağış türü.","Dikey konveksiyon yerine geniş ölçekli yatay katman bulutlarının yavaş yükselmesiyle üretilir.","Genellikle nimbostratus (tabanı çoğu kez alçak) ve orta seviye altostratus gibi katman bulut sistemleriyle ilişkilidir."],"tanim_en":"Continuous precipitation of uniform intensity that falls over a wide area from stratiform clouds such as nimbostratus.","bag":{"kavram":["yagis-surec"],"soru":["S12"],"hesap":[]}},{"id":"cloud-microphysics","tr":"Bulut mikrofiziği","en":"cloud microphysics","kisa":"","tur":"kavram","es":["bulut mikro-fiziği","microphysics of clouds"],"tanim":["Bulut ve yağış taneciklerinin çekirdeklenme, yoğuşma, buharlaşma, çarpışma, donma ve erime gibi mikroskobik süreçlerini inceleyen atmosfer fiziği dalı.","Yaklaşık 0,1 µm yarıçaplı aerosollerden başlayıp 10 µm yarıçaplı bulut damlalarına ve 1 mm yarıçaplı yağmur damlalarına kadar uzanan tanecik boyut spektrumunu ele alır.","Köhler eğrisi, buhar difüzyonu, Bergeron süreci ve çarpışma–birleşme mekanizmalarıyla yağış oluşumunu açıklar."],"tanim_en":"The branch of atmospheric physics that studies the nucleation, growth, collision, and fallout of cloud and precipitation particles.","bag":{"kavram":[],"soru":[],"hesap":[]}}]};
